    assetIndex: number;
  } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  useEffect(() => {
    if (project) {
      const stepData = project.steps?.[currentStepId] || { notes: '', isComplete: false };
      let initialNotes = stepData.notes;
      if (currentStepId === 'problem' && !initialNotes && project.notes) {
        initialNotes = project.notes;
      }
      setNotes(initialNotes);
      notesRef.current = initialNotes;
    }
  }, [project?.id, currentStepId]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps?.[currentStepId]?.isComplete || false;

    setTimeout(() => {
      updateStepData(currentStepId, {
        notes: notesRef.current,
        isComplete: currentIsComplete
      });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 500);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => {
      if (saveStatus === 'modified') handleSave();
    }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project) return;
    const isComplete = project.steps?.[currentStepId]?.isComplete || false;
    updateStepData(currentStepId, { notes, isComplete: !isComplete });
  };

  const handleNextStep = () => {
    if (project && notes.trim().length > 10 && !project.steps?.[currentStepId]?.isComplete) {
        updateStepData(currentStepId, { notes, isComplete: true });
    }
    if (nextStep) onStepSelect(nextStep.id);
  };

  const saveTitle = () => {
    if (!project) return;
    if (editTitleVal.trim() && editTitleVal !== project.title) {
      updateProject(project.id, { title: editTitleVal });
    }
    setIsEditingTitle(false);
  };

  const handleContextMenu = (e: React.MouseEvent, index: number) => {
    e.preventDefault();
    setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, assetIndex: index });
  };

  if (!project) {
    return (
      <div className={`flex-1 flex flex-col items-center justify-center bg-white md:border md:border-slate-200 md:rounded-xl p-10 text-center shadow-sm min-h-[400px] ${className}`} role="main">
        <div className="w-16 h-16 rounded-full bg-slate-50 flex items-center justify-center mb-4 text-slate-300">
          <IconFile className="w-8 h-8" aria-hidden="true" />
        </div>
        <h2 className="text-lg font-semibold text-slate-900 mb-2">Ready to work?</h2>
        <p className="text-slate-500 max-w-sm leading-relaxed">Select an existing project or create a new one to start your design journey.</p>
      </div>
    );
  }

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const completedStepsCount = STAGES.filter(s => project.steps?.[s.id]?.isComplete).length;
  const progress = Math.round((completedStepsCount / STAGES.length) * 100);
  const stepAssets = project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId));

  if (currentStepId === 'casestudy') {
    const previewHtml = generateFullHtml(project, true);
    return (
      <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`}>
         <div className="bg-white border-b md:border md:border-slate-200 md:rounded-xl p-4 md:p-6 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div>
                <h1 className="text-xl md:text-2xl font-bold text-slate-900">Case Study Preview</h1>
                <p className="text-slate-500 text-xs md:text-sm mt-1">Review your automated portfolio presentation.</p>
            </div>
            <Button onClick={() => onExport(project)} className="bg-blue-600 text-white w-full md:w-auto">
                <IconDownload className="w-4 h-4 mr-2" /> Export Case Study
            </Button>
         </div>
         <div className="flex-1 bg-slate-100 md:rounded-xl overflow-hidden relative border-y md:border border-slate-200">
            <iframe srcDoc={previewHtml} title="Case Study Preview" className="w-full h-full border-0 bg-white" sandbox="allow-same-origin" />
         </div>
         <div className="px-4 md:px-0 pb-20 md:pb-0">
            <Button variant="outline" onClick={() => onStepSelect(prevStep.id)} className="w-full md:w-auto">Back to Process</Button>
         </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`} role="main">
      {/* 1. Header: Ultra-clean on Mobile */}
      <div className="bg-white border-b md:border md:border-slate-200 md:rounded-xl p-4 md:p-6 shadow-sm flex flex-col gap-3 md:gap-4">
        <div className="flex justify-between items-center">
          <div className="min-w-0">
            <div className="text-[10px] md:text-xs font-bold text-blue-600 uppercase tracking-widest mb-0.5">Step {currentStepIndex + 1} of 12</div>
            <h1 className="text-lg md:text-2xl font-bold text-slate-900 truncate">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <div className="flex items-center gap-3 shrink-0">
             <div className="hidden sm:flex flex-col items-end">
                <div className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">Progress</div>
                <div className="font-mono text-blue-600 font-bold leading-none">{progress}%</div>
             </div>
             <ProgressRing progress={progress} radius={window.innerWidth < 768 ? 20 : 24} stroke={window.innerWidth < 768 ? 3 : 4} className="text-blue-600" />
          </div>
        </div>

        <div className="flex items-center gap-2 pt-3 border-t border-slate-100 overflow-hidden">
             <span className="text-[10px] text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded shrink-0">Project</span>
             {isEditingTitle ? (
                 <input autoFocus type="text" className="text-xs font-bold text-slate-900 bg-white border-b border-blue-500 outline-none flex-1 min-w-0" value={editTitleVal} onChange={e => setEditTitleVal(e.target.value)} onBlur={saveTitle} onKeyDown={e => e.key === 'Enter' && saveTitle()} />
               ) : (
                 <span className="text-xs font-bold text-slate-700 truncate cursor-pointer" onDoubleClick={() => {setEditTitleVal(project.title); setIsEditingTitle(true);}}>{project.title}</span>
            )}
             <button onClick={() => setIsHistoryOpen(true)} className="ml-auto text-[10px] text-slate-400 hover:text-blue-600 flex items-center gap-1 shrink-0 px-2 py-1 rounded-md hover:bg-slate-50">
                <IconHistory className="w-3 h-3" /> <span className="hidden xs:inline">History</span>
             </button>
        </div>
      </div>

      {/* 2. Content Area */}
      <div className="flex-1 flex flex-col lg:grid lg:grid-cols-3 gap-4 md:gap-6 px-4 md:px-0">
        <div className="lg:col-span-2 flex flex-col h-full min-h-[350px] md:min-h-[500px]">
          <div className="bg-white border border-slate-200 rounded-xl shadow-sm flex-1 flex flex-col relative overflow-hidden">
            <div className="flex items-center justify-between px-3 py-2 border-b border-slate-100 bg-slate-50/50">
               <Button size="sm" variant="ghost" onClick={openTemplates} className="text-blue-600 text-xs h-8">
                  <IconLayout className="w-3.5 h-3.5 mr-1.5" /> <span className="hidden xs:inline">Insert Template</span><span className="xs:hidden">Template</span>
               </Button>
               <div className={`text-[10px] font-bold uppercase tracking-wider ${saveStatus === 'saved' ? 'text-emerald-500' : saveStatus === 'saving' ? 'text-blue-500' : 'text-slate-300'}`}>
                   {saveStatus === 'saving' ? 'Saving' : saveStatus === 'saved' ? 'Saved' : ''}
               </div>
            </div>
            <textarea
              value={notes}
              onChange={handleNotesChange}
              onBlur={handleSave} 
              placeholder={`Add notes for ${currentStage.label.toLowerCase().replace(/^\d+\.\s/, '')}...\n\nTips: ${currentStage.help}`}
              className="w-full flex-1 bg-white p-4 md:p-8 resize-none focus:outline-none text-slate-700 leading-relaxed text-base md:text-lg font-sans"
            />
          </div>
        </div>

        <div className="flex flex-col gap-4 md:gap-6">
           <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Milestone</h3>
              <button 
                onClick={toggleStepCompletion}
                className={`w-full flex items-center gap-3 p-3 rounded-xl border transition-all ${isStepComplete ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-slate-200 text-slate-500 hover:border-blue-300'}`}
              >
                 <div className={`w-6 h-6 rounded-full border flex items-center justify-center shrink-0 ${isStepComplete ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-white border-slate-300'}`}>
                    {isStepComplete && <IconCheck className="w-4 h-4" />}
                 </div>
                 <span className="text-sm font-bold">{isStepComplete ? 'Completed' : 'Mark as Done'}</span>
              </button>
           </div>

           <div className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm flex flex-col">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Step Assets</h3>
                <label className="cursor-pointer">
                   <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                   <div className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-xs font-bold hover:bg-blue-100">Add</div>
                </label>
              </div>

              {stepAssets.length === 0 ? (
                <div className="py-8 flex flex-col items-center justify-center text-center border-2 border-dashed border-slate-100 rounded-xl text-slate-300 text-xs">
                   <IconFile className="w-6 h-6 mb-2 opacity-30" />
                   No visual evidence yet
                </div>
              ) : (
                <div className="grid grid-cols-2 lg:grid-cols-1 gap-3 max-h-[300px] overflow-y-auto pr-1">
                   {[...stepAssets].reverse().map((asset, i) => (
                      <AssetCard key={i} asset={asset} onClick={() => { const url = asset.url || asset.dataURL; if(url) window.open(url, '_blank'); }} onContextMenu={(e) => handleContextMenu(e, project.assets.indexOf(asset))} onMoreClick={(e) => handleContextMenu(e, project.assets.indexOf(asset))} />
                   ))}
                </div>
              )}
           </div>
        </div>
      </div>

      <div className="sticky bottom-0 md:static bg-white/95 md:bg-transparent backdrop-blur-xl p-4 md:p-0 border-t md:border-0 border-slate-200 flex justify-between items-center z-30 pb-safe">
         <Button variant="ghost" onClick={() => prevStep && onStepSelect(prevStep.id)} className={`${!prevStep && 'invisible'}`}>Back</Button>
         <div className="flex gap-3">
            {nextStep ? (
                <Button onClick={handleNextStep} className="bg-blue-600 px-8 shadow-lg shadow-blue-500/20">
                    Next Step <IconArrowRight className="w-4 h-4 ml-2" />
                </Button>
            ) : (
                <Button onClick={() => onStepSelect('casestudy')} className="bg-emerald-600 hover:bg-emerald-700 text-white shadow-lg shadow-emerald-500/20">
                    Finish Case Study
                </Button>
            )}
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Download', icon: <IconDownload className="w-4 h-4" />, onClick: () => { if(contextMenu) { const a = project.assets[contextMenu.assetIndex]; const url = a.url || a.dataURL; if(url) { const l = document.createElement('a'); l.href = url; l.download = a.name; l.click(); } } } },
          { label: 'Replace', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />
      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
    </main>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, AppState } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
import { IconPlus, IconCheck, IconTrash, IconCopy, IconDownload, IconChevronDown, IconSearch, IconArrowRight } from './ui/Icons';

interface SidebarProps {
  state: AppState;
  onOpenCreateModal: () => void;
  switchProject: (id: string) => void;
  deleteProject: (id: string) => void;
  duplicateProject: (id: string) => void;
  onExport: (project: Project) => void;
  activeProject: Project | null;
  onStepSelect: (stepId: string) => void;
  currentStepId: string;
  className?: string;
  mobileOpen?: boolean;
  onCloseMobile?: () => void;
}

const PROJECT_ROW_HEIGHT = 88;

export const Sidebar: React.FC<SidebarProps> = ({
  state,
  onOpenCreateModal,
  switchProject,
  deleteProject,
  duplicateProject,
  onExport,
  activeProject,
  onStepSelect,
  currentStepId,
  className = '',
  mobileOpen = false,
  onCloseMobile
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const listRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(400);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setScrollTop(0);
      if (listRef.current) listRef.current.scrollTop = 0;
    }, 200);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  useEffect(() => {
    if (listRef.current) {
      setViewportHeight(listRef.current.clientHeight);
      const ro = new ResizeObserver(entries => {
        for (let entry of entries) setViewportHeight(entry.contentRect.height);
      });
      ro.observe(listRef.current);
      return () => ro.disconnect();
    }
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => setScrollTop(e.currentTarget.scrollTop);

  const filteredProjects = useMemo(() => {
    const all = Object.values(state.projects) as Project[];
    const sorted = all.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    if (!debouncedSearch.trim()) return sorted;
    const lower = debouncedSearch.toLowerCase();
    return sorted.filter(p => p.title.toLowerCase().includes(lower) || (p.desc && p.desc.toLowerCase().includes(lower)));
  }, [state.projects, debouncedSearch]);

  const totalCount = filteredProjects.length;
  const startIndex = Math.max(0, Math.floor(scrollTop / PROJECT_ROW_HEIGHT) - 2);
  const endIndex = Math.min(totalCount, Math.ceil((scrollTop + viewportHeight) / PROJECT_ROW_HEIGHT) + 2);
  const visibleProjects = filteredProjects.slice(startIndex, endIndex);
  const paddingTop = startIndex * PROJECT_ROW_HEIGHT;
  const paddingBottom = (totalCount - endIndex) * PROJECT_ROW_HEIGHT;

  const containerClasses = `
    transition-all duration-300 ease-in-out
    md:relative md:flex md:translate-y-0 md:w-80 lg:w-96 md:flex-col md:gap-6 md:z-0
    fixed inset-0 z-[60] bg-white flex flex-col md:bg-transparent
    ${mobileOpen ? 'translate-y-0 opacity-100' : 'translate-y-full opacity-0 md:opacity-100'}
  `;

  return (
    <aside className={`${containerClasses} ${className}`} role="complementary">
        <div className="md:hidden h-[72px] flex items-center justify-between px-6 border-b border-slate-100 sticky top-0 bg-white z-20">
           <h2 className="text-xl font-extrabold text-slate-900 tracking-tight">Process Menu</h2>
           <button onClick={onCloseMobile} className="w-10 h-10 flex items-center justify-center bg-slate-50 rounded-full active:scale-90 transition-transform">
             <IconChevronDown className="w-6 h-6 text-slate-600" />
           </button>
        </div>

        <div className="md:bg-white md:border md:border-slate-200 md:rounded-xl p-5 md:shadow-sm flex flex-col h-1/2 md:h-auto md:max-h-[45vh] overflow-hidden border-b md:border-b-0">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">Active Projects</h3>
            <Button size="sm" onClick={onOpenCreateModal} className="text-xs h-8"><IconPlus className="w-3.5 h-3.5 mr-1" /> New</Button>
          </div>

          <div className="relative mb-4 shrink-0">
            <IconSearch className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
            <input type="text" placeholder="Filter..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-xl py-2 pl-9 pr-4 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" />
          </div>

          <div ref={listRef} onScroll={handleScroll} className="flex-1 overflow-y-auto pr-1">
            {totalCount === 0 ? (
              <div className="text-center py-10 text-slate-400 text-xs italic">No projects found</div>
            ) : (
              <div style={{ paddingTop: `${paddingTop}px`, paddingBottom: `${paddingBottom}px` }}>
                {visibleProjects.map(p => {
                  const isActive = activeProject?.id === p.id;
                  const completedCount = STAGES.filter(s => p.steps?.[s.id]?.isComplete).length;
                  return (
                    <div key={p.id} style={{ height: `${PROJECT_ROW_HEIGHT}px` }} className="pb-3 box-border">
                      <div className={`p-4 h-full rounded-xl transition-all cursor-pointer border flex justify-between items-center ${isActive ? 'bg-blue-50 border-blue-200 shadow-sm' : 'bg-white hover:bg-slate-50 border-slate-100'}`} onClick={() => switchProject(p.id)}>
                        <div className="min-w-0 pr-2">
                          <div className={`text-sm font-bold truncate ${isActive ? 'text-blue-700' : 'text-slate-800'}`}>{p.title}</div>
                          <div className="text-[10px] text-slate-400 mt-0.5 truncate">{completedCount}/{STAGES.length} Milestones</div>
                        </div>
                        <div className="flex gap-1">
                          <button className="p-1.5 text-slate-400 hover:text-blue-600" onClick={(e) => { e.stopPropagation(); duplicateProject(p.id); }}><IconCopy className="w-4 h-4" /></button>
                          <button className="p-1.5 text-slate-400 hover:text-red-600" onClick={(e) => { e.stopPropagation(); deleteProject(p.id); }}><IconTrash className="w-4 h-4" /></button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        <div className="flex-1 bg-slate-50 md:bg-white md:border md:border-slate-200 md:rounded-xl p-5 md:shadow-sm overflow-hidden flex flex-col">
          <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Step by Step Guide</h3>
          <div className="overflow-y-auto flex-1 pr-1 space-y-2 pb-20 md:pb-0">
            {activeProject ? (
              STAGES.map((stage, idx) => {
                const isDone = activeProject.steps?.[stage.id]?.isComplete;
                const isActive = currentStepId === stage.id;
                return (
                  <button key={stage.id} onClick={() => onStepSelect(stage.id)} className={`w-full text-left rounded-xl transition-all border flex items-center gap-3 p-3 ${isActive ? 'bg-white border-blue-200 shadow-md ring-1 ring-blue-100' : 'border-transparent hover:bg-white/50'}`}>
                      <div className={`w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-black border shrink-0 ${isActive ? 'bg-blue-600 border-blue-600 text-white' : isDone ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-white border-slate-200 text-slate-400'}`}>
                        {isDone && !isActive ? <IconCheck className="w-4 h-4 stroke-[4]" /> : (idx + 1)}
                      </div>
                      <div className="flex-1 min-w-0">
                         <div className={`text-sm font-bold truncate ${isActive ? 'text-blue-700' : isDone ? 'text-emerald-700' : 'text-slate-600'}`}>{stage.label.split('. ')[1]}</div>
                         {isActive && <div className="text-[10px] text-blue-500 font-medium animate-pulse">Editing now...</div>}
                      </div>
                      {isActive && <IconArrowRight className="w-4 h-4 text-blue-400" />}
                  </button>
                );
              })
            ) : (
              <div className="text-center py-10 text-slate-400 text-xs italic">Select a project to see steps</div>
            )}
          </div>
        </div>
    </aside>
  );
};

import { Project, Asset, StepData } from "../types";
import { STAGES } from "../constants";

// --- Helpers ---

function escapeHtml(s: string) {
  return (s || '').toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function renderNotesHtml(notes: string): string {
  if (!notes) return '';
  // Preserve details/summary tags, convert newlines to BR for other text
  const parts = notes.split(/(<\/?details(?: open)?>|<\/?summary>)/g);
  return parts.map(part => {
    if (part.match(/<\/?details(?: open)?>|<\/?summary>/)) {
      return part;
    } else {
      return escapeHtml(part).replace(/\n/g, '<br>');
    }
  }).join('');
}

function getAssetHtml(assets: Asset[]) {
  if (!assets || assets.length === 0) return '';

  return `
    <div class="assets-grid">
      ${assets.map(a => {
         const displayUrl = a.url || a.dataURL;
         if (!a.type.startsWith('image') || !displayUrl) return '';
         return `
           <div class="asset-item">
             <img src="${displayUrl}" alt="${escapeHtml(a.name)}" />
             <div class="asset-caption">${escapeHtml(a.name)}</div>
           </div>
         `;
      }).join('')}
    </div>
  `;
}

// --- Main Generator ---

export function generateCaseStudyHtml(project: Project): string {
  const dateStr = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

  // 1. Generate Steps HTML
  const stepsHtml = STAGES.map((stage, index) => {
    const stepData = project.steps?.[stage.id] || { notes: '', isComplete: false };
    const content = stepData.notes || (stage.id === 'problem' ? project.notes : '');
    const stepAssets = project.assets.filter(a => (a.stepId === stage.id) || (stage.id === 'problem' && !a.stepId));
    const stepNumber = String(index + 1).padStart(2, '0');

    if (stage.id === 'casestudy') return '';

    return `
      <section class="step-section no-break">
        <div class="step-header">
          <span class="step-num">${stepNumber}</span>
          <div class="step-title-group">
            <h2 class="step-title">${escapeHtml(stage.label.replace(/^\d+\.\s/, ''))}</h2>
            <div class="step-desc">${escapeHtml(stage.description)}</div>
          </div>
        </div>

        <div class="step-content">
          ${content 
            ? `<div class="step-notes">${renderNotesHtml(content)}</div>` 
            : `<div class="empty-state">No notes added for this step.</div>`
          }
          ${getAssetHtml(stepAssets)}
        </div>
      </section>
      <div class="divider"></div>
    `;
  }).join('');

  const summaryData = project.steps?.['casestudy'] || { notes: '', isComplete: false };
  const summaryHtml = summaryData.notes 
    ? `
      <section class="step-section page-break">
