}) => {
  const [notes, setNotes] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editTitleVal, setEditTitleVal] = useState('');
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  useEffect(() => {
    if (project) {
      const stepData = project.steps?.[currentStepId] || { notes: '', isComplete: false };
      let initialNotes = stepData.notes;
      if (currentStepId === 'problem' && !initialNotes && project.notes) {
        initialNotes = project.notes;
      }
      setNotes(initialNotes);
      notesRef.current = initialNotes;
    }
  }, [project?.id, currentStepId]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps?.[currentStepId]?.isComplete || false;

    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project) return;
    const isComplete = project.steps?.[currentStepId]?.isComplete || false;
    updateStepData(currentStepId, { notes, isComplete: !isComplete });
  };

  const saveTitle = () => {
    if (project && editTitleVal.trim() && editTitleVal !== project.title) {
      updateProject(project.id, { title: editTitleVal });
    }
    setIsEditingTitle(false);
  };

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = Math.round((STAGES.filter(s => project?.steps?.[s.id]?.isComplete).length / STAGES.length) * 100);
  const stepAssets = project?.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) || [];

  if (!project) {
    return (
      <div className={`flex-1 flex flex-col items-center justify-center p-10 text-center ${className}`}>
        <IconFile className="w-12 h-12 text-slate-200 mb-4" />
        <h2 className="text-lg font-semibold text-slate-900 mb-2">Select a Project</h2>
        <p className="text-slate-500 max-w-xs text-sm">Choose or create a project to start documenting your design process.</p>
      </div>
    );
  }

  if (currentStepId === 'casestudy') {
    const previewHtml = generateFullHtml(project, true);
    return (
      <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`}>
         <div className="bg-white border-b md:border md:border-slate-200 md:rounded-2xl p-4 md:p-6 shadow-soft flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div>
                <h1 className="text-xl md:text-2xl font-bold text-slate-900">Portfolio Preview</h1>
                <p className="text-slate-500 text-xs md:text-sm mt-0.5">Automated case study based on your process.</p>
            </div>
            <Button onClick={() => onExport(project)} className="bg-blue-600 text-white w-full md:w-auto shadow-lg shadow-blue-500/20">
                <IconDownload className="w-4 h-4 mr-2" /> Export Document
            </Button>
         </div>
         <div className="flex-1 bg-white md:rounded-2xl overflow-hidden relative border-y md:border border-slate-200 shadow-inner">
            <iframe srcDoc={previewHtml} title="Preview" className="w-full h-full border-0 bg-white" sandbox="allow-same-origin" />
         </div>
         <div className="px-4 md:px-0 pb-24 md:pb-0">
            <Button variant="outline" onClick={() => onStepSelect(prevStep.id)} className="w-full md:w-auto">Back to Editor</Button>
         </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`} role="main">
      {/* 1. Optimized Header */}
      <div className="bg-white border-b md:border md:border-slate-200 md:rounded-2xl p-4 md:p-6 shadow-soft flex flex-col gap-3 md:gap-4 shrink-0">
        <div className="flex justify-between items-start">
          <div className="min-w-0 pr-4">
            <div className="text-[10px] md:text-xs font-bold text-blue-600 uppercase tracking-widest mb-1">Step {currentStepIndex + 1}</div>
            <h1 className="text-lg md:text-2xl font-extrabold text-slate-900 truncate leading-tight">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <ProgressRing progress={progress} radius={window.innerWidth < 768 ? 20 : 24} className="text-blue-600 shrink-0" />
        </div>

        <div className="flex items-center gap-2 pt-3 border-t border-slate-50 overflow-hidden">
             {isEditingTitle ? (
                 <input autoFocus type="text" className="text-xs font-bold text-slate-900 bg-blue-50 border-b-2 border-blue-500 outline-none flex-1 px-1 py-0.5 rounded" value={editTitleVal} onChange={e => setEditTitleVal(e.target.value)} onBlur={saveTitle} onKeyDown={e => e.key === 'Enter' && saveTitle()} />
               ) : (
                 <span className="text-xs font-bold text-slate-500 truncate cursor-pointer hover:text-blue-600 transition-colors" onClick={() => {setEditTitleVal(project.title); setIsEditingTitle(true);}}>{project.title}</span>
            )}
             <button onClick={() => setIsHistoryOpen(true)} className="ml-auto text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-md active:scale-95">
                <IconHistory className="w-3 h-3 mr-1 inline" /> History
             </button>
        </div>
      </div>

      {/* 2. Focused Content Area */}
      <div className="flex-1 flex flex-col lg:grid lg:grid-cols-3 gap-4 md:gap-6 overflow-hidden px-4 md:px-0">
        <div className="lg:col-span-2 flex flex-col min-h-0 flex-1">
          <div className="bg-white border border-slate-200 rounded-2xl shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex items-center justify-between px-4 py-2 border-b border-slate-50 bg-slate-50/30">
               <button onClick={openTemplates} className="text-blue-600 text-[10px] font-black uppercase tracking-wider flex items-center h-8 active:scale-95">
                  <IconLayout className="w-4 h-4 mr-1.5" /> Insert Template
               </button>
               <div className={`text-[10px] font-bold uppercase ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                   {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Saved' : ''}
               </div>
            </div>
            <textarea
              value={notes}
              onChange={handleNotesChange}
              onBlur={handleSave} 
              placeholder={`Document your ${currentStage.label.toLowerCase().replace(/^\d+\.\s/, '')}...`}
              className="w-full flex-1 bg-white p-5 md:p-8 resize-none focus:outline-none text-slate-800 leading-relaxed text-base md:text-lg font-sans"
            />
          </div>
        </div>

        <div className="hidden lg:flex flex-col gap-6 w-full max-w-sm">
           <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-soft">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Milestone Control</h3>
              <button 
                onClick={toggleStepCompletion}
                className={`w-full flex items-center gap-3 p-4 rounded-xl border-2 transition-all ${isStepComplete ? 'bg-emerald-50 border-emerald-500 text-emerald-700' : 'bg-white border-slate-100 text-slate-500 hover:border-blue-200'}`}
              >
                 <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 ${isStepComplete ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-white border-slate-300'}`}>
                    {isStepComplete && <IconCheck className="w-4 h-4" />}
                 </div>
                 <span className="text-sm font-bold">{isStepComplete ? 'Completed Stage' : 'Mark as Done'}</span>
              </button>
           </div>

           <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-soft flex flex-col flex-1 min-h-0 overflow-hidden">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Evidence Gallery</h3>
                <label className="cursor-pointer active:scale-95 transition-transform">
                   <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                   <div className="px-3 py-1 bg-blue-600 text-white rounded-lg text-xs font-bold shadow-sm">Upload</div>
                </label>
              </div>

              <div className="flex-1 overflow-y-auto pr-1 space-y-3">
                {stepAssets.length === 0 ? (
                  <div className="h-32 flex flex-col items-center justify-center text-center border-2 border-dashed border-slate-100 rounded-xl text-slate-300 text-xs px-6">
                     No assets added for this step.
                  </div>
                ) : (
                  [...stepAssets].reverse().map((asset, i) => (
                    <AssetCard key={i} asset={asset} onClick={() => { const url = asset.url || asset.dataURL; if(url) window.open(url, '_blank'); }} onContextMenu={(e) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, assetIndex: project.assets.indexOf(asset) })} onMoreClick={(e) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, assetIndex: project.assets.indexOf(asset) })} />
                  ))
                )}
              </div>
           </div>
        </div>
      </div>

      {/* 3. Mobile Navigation Controls */}
      <div className="sticky bottom-0 md:static bg-white/95 md:bg-transparent backdrop-blur-xl p-4 md:p-0 border-t md:border-0 border-slate-200 flex justify-between items-center z-40 pb-safe">
         <Button variant="ghost" onClick={() => prevStep && onStepSelect(prevStep.id)} className={`px-2 ${!prevStep && 'invisible'}`}>Back</Button>
         <div className="flex gap-2">
            <button 
                onClick={toggleStepCompletion} 
                className={`p-3 rounded-full border transition-all active:scale-90 ${isStepComplete ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-slate-50 border-slate-200 text-slate-400'}`}
                title="Mark step complete"
            >
                <IconCheck className="w-6 h-6" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} className="bg-blue-600 px-8 shadow-xl shadow-blue-500/20 rounded-full font-black">
                {nextStep ? 'Continue' : 'Finalize'} <IconArrowRight className="w-4 h-4 ml-2" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Download', icon: <IconDownload className="w-4 h-4" />, onClick: () => { if(contextMenu) { const a = project.assets[contextMenu.assetIndex]; const url = a.url || a.dataURL; if(url) { const l = document.createElement('a'); l.href = url; l.download = a.name; l.click(); } } } },
          { label: 'Replace', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />
      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
    </main>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Project, AppState, Asset, ProjectVersion } from './types';
import { STAGES } from './constants';
import { Sidebar } from './components/Sidebar';
import { Workspace } from './components/Workspace';
import { TemplatesModal } from './components/TemplatesModal';
import { CreateProjectModal } from './components/CreateProjectModal';
import { ConfirmModal } from './components/ConfirmModal';
import { ExportModal } from './components/ExportModal';
import { Toast, ToastProps } from './components/ui/Toast';
import { Tour } from './components/Tour';
import { Button } from './components/ui/Button';
import { IconMenu, IconLayout, IconPlus, IconBug, IconTrash, IconClose } from './components/ui/Icons';

function uid() {
  return 'p_' + Math.random().toString(36).slice(2, 9);
}

const STORAGE_KEY = 'uxmate_projects_v2';
const STORAGE_WARNING_THRESHOLD = 4.5 * 1024 * 1024; 

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    try {
      const local = localStorage.getItem(STORAGE_KEY);
      if (local) return JSON.parse(local);
    } catch (e) { console.error('Failed to load state', e); }
    return { projects: {}, activeProjectId: null };
  });

  const [isTemplatesOpen, setIsTemplatesOpen] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [exportProject, setExportProject] = useState<Project | null>(null);
  const [fbReady, setFbReady] = useState(false);
  const [showMobileProjects, setShowMobileProjects] = useState(false);
  const [toast, setToast] = useState<Omit<ToastProps, 'onClose'> | null>(null);
  const [confirmConfig, setConfirmConfig] = useState<{isOpen: boolean; title: string; message: string; onConfirm: () => void;}>({ isOpen: false, title: '', message: '', onConfirm: () => {} });
  const [devClickCount, setDevClickCount] = useState(0);
  const [isDevMode, setIsDevMode] = useState(false);
  const [isDebugOpen, setIsDebugOpen] = useState(false);

  useEffect(() => {
    try {
      const json = JSON.stringify(state);
      localStorage.setItem(STORAGE_KEY, json);
      if (new Blob([json]).size > STORAGE_WARNING_THRESHOLD) setToast({ message: 'Storage critical!', type: 'error' });
    } catch (e) { setToast({ message: 'Storage full!', type: 'error' }); }
  }, [state]);

  useEffect(() => {
    if (Object.keys(state.projects).length === 0) {
      const id = uid();
      const example: Project = {
        id, title: 'Project: Grocery App', desc: 'Redesigning the cart experience', notes: '',
        stages: {}, steps: STAGES.reduce((acc, s) => ({ ...acc, [s.id]: { notes: '', isComplete: false } }), {}),
        assets: [], createdAt: new Date().toISOString(), currentStepId: 'problem'
      };
      setState({ projects: { [id]: example }, activeProjectId: id });
    }
  }, []);

  const activeProject = state.activeProjectId ? state.projects[state.activeProjectId] : null;

  const handleCreateProject = (title: string, desc: string) => {
    const id = uid();
    const newProj: Project = { id, title, desc, notes: '', stages: {}, steps: STAGES.reduce((acc, s) => ({ ...acc, [s.id]: { notes: '', isComplete: false } }), {}), assets: [], createdAt: new Date().toISOString(), currentStepId: 'problem' };
    setState(prev => ({ projects: { ...prev.projects, [id]: newProj }, activeProjectId: id }));
    setShowMobileProjects(false);
  };

  const deleteProject = (id: string) => {
    setState(prev => {
      const nextProjects = { ...prev.projects };
      delete nextProjects[id];
      return { projects: nextProjects, activeProjectId: prev.activeProjectId === id ? (Object.keys(nextProjects)[0] || null) : prev.activeProjectId };
    });
  };

  const updateProject = (id: string, updates: Partial<Project>) => {
    setState(prev => ({ ...prev, projects: { ...prev.projects, [id]: { ...prev.projects[id], ...updates } } }));
  };

  const updateStepData = (stepId: string, data: { notes: string; isComplete: boolean }) => {
     if (!activeProject) return;
     setState(prev => {
         const p = prev.projects[activeProject.id];
         const newSteps = { ...p.steps, [stepId]: { ...p.steps[stepId], ...data } };
         return { ...prev, projects: { ...prev.projects, [p.id]: { ...p, steps: newSteps, history: [{ timestamp: new Date().toISOString(), notes: p.notes, stepData: newSteps }, ...(p.history || [])].slice(0, 3) } } };
     });
  };

  const duplicateProject = (id: string) => {
    const source = state.projects[id];
    if(!source) return;
    const newId = uid();
    setState(prev => ({ projects: { ...prev.projects, [newId]: { ...source, id: newId, title: `${source.title} (Copy)`, createdAt: new Date().toISOString() } }, activeProjectId: newId }));
  };

  const handleAssetUpload = async (file: File) => {
    if (!activeProject) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const asset: Asset = { name: file.name, type: file.type, dataURL: e.target?.result as string, createdAt: new Date().toISOString(), size: file.size, stepId: activeProject.currentStepId || 'problem' };
      setState(prev => {
        const p = prev.projects[activeProject.id];
        return { ...prev, projects: { ...prev.projects, [p.id]: { ...p, assets: [...p.assets, asset] } } };
      });
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col font-sans">
      <header className="h-14 border-b border-slate-200 bg-white/80 backdrop-blur-md flex items-center px-4 sticky top-0 z-40 shrink-0">
        <div onClick={() => { if(devClickCount + 1 === 5) setIsDevMode(true); setDevClickCount(prev => prev + 1); }} className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center font-black text-white mr-3 shadow-md select-none cursor-pointer active:scale-95">UX</div>
        <h1 className="font-extrabold text-sm tracking-tight">UXMate</h1>
        {isDevMode && <button onClick={() => setIsDebugOpen(true)} className="ml-auto p-1.5 rounded bg-red-50 text-red-500"><IconBug className="w-4 h-4" /></button>}
      </header>

      <div className="flex-1 flex flex-col md:flex-row overflow-hidden max-w-[1600px] mx-auto w-full md:p-6 md:gap-6 relative">
        <Sidebar 
          state={state} activeProject={activeProject}
          onOpenCreateModal={() => setIsCreateModalOpen(true)}
          switchProject={(id) => { setState(prev => ({ ...prev, activeProjectId: id })); setShowMobileProjects(false); }}
          deleteProject={deleteProject} duplicateProject={duplicateProject}
          onExport={setExportProject}
          mobileOpen={showMobileProjects} onCloseMobile={() => setShowMobileProjects(false)}
          currentStepId={activeProject?.currentStepId || 'problem'}
          onStepSelect={(id) => { if(activeProject) updateProject(activeProject.id, { currentStepId: id }); setShowMobileProjects(false); }}
        />

        <Workspace 
          project={activeProject} updateProject={updateProject} updateStepData={updateStepData}
          restoreProjectVersion={(v) => { if(activeProject) updateProject(activeProject.id, { notes: v.notes, steps: v.stepData || activeProject.steps }); setToast({ message: 'Restored!', type: 'success' }); }}
          deleteAsset={(idx) => { if(activeProject) { const a = [...activeProject.assets]; a.splice(idx, 1); updateProject(activeProject.id, { assets: a }); } }}
          onReplaceAsset={() => {}} openTemplates={() => setIsTemplatesOpen(true)}
          onExport={setExportProject} onUploadAsset={handleAssetUpload}
          currentStepId={activeProject?.currentStepId || 'problem'}
          onStepSelect={(id) => { if(activeProject) updateProject(activeProject.id, { currentStepId: id }); }}
        />
      </div>

      {/* Modern Mobile Navigation Bar */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 h-20 glass-nav border-t border-slate-200 flex items-center justify-around px-6 pb-safe z-50">
        <NavButton active={showMobileProjects} icon={IconMenu} label="Process" onClick={() => setShowMobileProjects(!showMobileProjects)} />
        <button onClick={() => setIsCreateModalOpen(true)} className="w-14 h-14 -mt-10 bg-blue-600 rounded-full text-white shadow-fab flex items-center justify-center active:scale-90 transition-transform"><IconPlus className="w-7 h-7" /></button>
        <NavButton active={isTemplatesOpen} icon={IconLayout} label="Templates" onClick={() => setIsTemplatesOpen(true)} />
      </nav>

      <Tour />
      <TemplatesModal isOpen={isTemplatesOpen} onClose={() => setIsTemplatesOpen(false)} onInsert={(content) => { if(activeProject) { const sid = activeProject.currentStepId || 'problem'; updateStepData(sid, { notes: (activeProject.steps[sid].notes + "\n\n" + content), isComplete: activeProject.steps[sid].isComplete }); } }} />
      <CreateProjectModal isOpen={isCreateModalOpen} onClose={() => setIsCreateModalOpen(false)} onCreate={handleCreateProject} />
      <ExportModal project={exportProject} isOpen={!!exportProject} onClose={() => setExportProject(null)} />
      <ConfirmModal isOpen={confirmConfig.isOpen} title={confirmConfig.title} message={confirmConfig.message} onConfirm={confirmConfig.onConfirm} onClose={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} />
      {toast && <Toast message={toast.message} type={toast.type} onUndo={toast.onUndo} onClose={() => setToast(null)} />}

      {isDebugOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4">
           <div className="bg-white rounded-2xl w-full max-w-lg h-[60vh] flex flex-col overflow-hidden shadow-2xl">
              <div className="p-4 border-b flex justify-between items-center"><h2 className="font-bold">Debug</h2><button onClick={() => setIsDebugOpen(false)}><IconClose className="w-5 h-5"/></button></div>
              <pre className="flex-1 overflow-auto bg-slate-900 text-green-400 p-4 text-[10px]">{JSON.stringify(state, null, 2)}</pre>
           </div>
        </div>
      )}
    </div>
  );
};

const NavButton = ({ active, icon: Icon, label, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-colors active:scale-95 ${active ? 'text-blue-600' : 'text-slate-400'}`}>
    <Icon className="w-5 h-5" />
    <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
import { IconDownload, IconTrash, IconFile, IconReplace, IconHistory, IconCheck, IconArrowRight, IconLayout } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
import { AssetCard } from './ui/AssetCard';
import { ContextMenu } from './ui/ContextMenu';
import { HistoryModal } from './HistoryModal';
import { generateFullHtml } from '../utils/exporter';

interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  openTemplates: () => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  openTemplates,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editTitleVal, setEditTitleVal] = useState('');
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  useEffect(() => {
    if (project) {
      const stepData = project.steps?.[currentStepId] || { notes: '', isComplete: false };
      let initialNotes = stepData.notes;
      if (currentStepId === 'problem' && !initialNotes && project.notes) {
        initialNotes = project.notes;
      }
      setNotes(initialNotes);
      notesRef.current = initialNotes;
    }
  }, [project?.id, currentStepId]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps?.[currentStepId]?.isComplete || false;

    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project) return;
    const isComplete = project.steps?.[currentStepId]?.isComplete || false;
    updateStepData(currentStepId, { notes, isComplete: !isComplete });
  };

  const saveTitle = () => {
    if (project && editTitleVal.trim() && editTitleVal !== project.title) {
      updateProject(project.id, { title: editTitleVal });
    }
    setIsEditingTitle(false);
  };

  if (!project) {
    return (
      <div className={`flex-1 flex flex-col items-center justify-center p-10 text-center ${className}`}>
        <IconFile className="w-12 h-12 text-slate-200 mb-4" />
        <h2 className="text-lg font-semibold text-slate-900 mb-2">Select a Project</h2>
        <p className="text-slate-500 max-w-xs text-sm">Choose or create a project to start documenting your design process.</p>
      </div>
    );
  }

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100);
  const stepAssets = project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) || [];

  if (currentStepId === 'casestudy') {
    const previewHtml = generateFullHtml(project, true);
    return (
      <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`}>
         <div className="bg-white border-b md:border md:border-slate-200 md:rounded-2xl p-4 md:p-6 shadow-soft flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div>
                <h1 className="text-xl md:text-2xl font-bold text-slate-900">Portfolio Preview</h1>
                <p className="text-slate-500 text-xs md:text-sm mt-0.5">Automated case study based on your process.</p>
            </div>
            <Button onClick={() => onExport(project)} className="bg-blue-600 text-white w-full md:w-auto shadow-lg shadow-blue-500/20">
                <IconDownload className="w-4 h-4 mr-2" /> Export Document
            </Button>
         </div>
         <div className="flex-1 bg-white md:rounded-2xl overflow-hidden relative border-y md:border border-slate-200 shadow-inner">
            <iframe srcDoc={previewHtml} title="Preview" className="w-full h-full border-0 bg-white" sandbox="allow-same-origin" />
         </div>
         <div className="px-4 md:px-0 pb-24 md:pb-0">
            <Button variant="outline" onClick={() => onStepSelect(prevStep.id)} className="w-full md:w-auto">Back to Editor</Button>
         </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`} role="main">
      {/* 1. Optimized Header */}
      <div className="bg-white border-b md:border md:border-slate-200 md:rounded-2xl p-4 md:p-6 shadow-soft flex flex-col gap-3 md:gap-4 shrink-0">
        <div className="flex justify-between items-start">
          <div className="min-w-0 pr-4">
            <div className="text-[10px] md:text-xs font-bold text-blue-600 uppercase tracking-widest mb-1">Step {currentStepIndex + 1}</div>
            <h1 className="text-lg md:text-2xl font-extrabold text-slate-900 truncate leading-tight">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <ProgressRing progress={progress} radius={window.innerWidth < 768 ? 20 : 24} className="text-blue-600 shrink-0" />
        </div>

        <div className="flex items-center gap-2 pt-3 border-t border-slate-50 overflow-hidden">
             {isEditingTitle ? (
                 <input autoFocus type="text" className="text-xs font-bold text-slate-900 bg-blue-50 border-b-2 border-blue-500 outline-none flex-1 px-1 py-0.5 rounded" value={editTitleVal} onChange={e => setEditTitleVal(e.target.value)} onBlur={saveTitle} onKeyDown={e => e.key === 'Enter' && saveTitle()} />
               ) : (
                 <span className="text-xs font-bold text-slate-500 truncate cursor-pointer hover:text-blue-600 transition-colors" onClick={() => {setEditTitleVal(project.title); setIsEditingTitle(true);}}>{project.title}</span>
            )}
             <button onClick={() => setIsHistoryOpen(true)} className="ml-auto text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-md active:scale-95">
                <IconHistory className="w-3 h-3 mr-1 inline" /> History
             </button>
        </div>
      </div>

      {/* 2. Focused Content Area */}
      <div className="flex-1 flex flex-col lg:grid lg:grid-cols-3 gap-4 md:gap-6 overflow-hidden px-4 md:px-0">
        <div className="lg:col-span-2 flex flex-col min-h-0 flex-1">
          <div className="bg-white border border-slate-200 rounded-2xl shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex items-center justify-between px-4 py-2 border-b border-slate-50 bg-slate-50/30">
               <button onClick={openTemplates} className="text-blue-600 text-[10px] font-black uppercase tracking-wider flex items-center h-8 active:scale-95">
                  <IconLayout className="w-4 h-4 mr-1.5" /> Insert Template
               </button>
               <div className={`text-[10px] font-bold uppercase ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                   {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Saved' : ''}
               </div>
            </div>
            <textarea
              value={notes}
              onChange={handleNotesChange}
              onBlur={handleSave} 
              placeholder={`Document your ${currentStage.label.toLowerCase().replace(/^\d+\.\s/, '')}...`}
              className="w-full flex-1 bg-white p-5 md:p-8 resize-none focus:outline-none text-slate-800 leading-relaxed text-base md:text-lg font-sans"
            />
          </div>
        </div>

        <div className="hidden lg:flex flex-col gap-6 w-full max-w-sm">
           <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-soft">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Milestone Control</h3>
              <button 
                onClick={toggleStepCompletion}
                className={`w-full flex items-center gap-3 p-4 rounded-xl border-2 transition-all ${isStepComplete ? 'bg-emerald-50 border-emerald-500 text-emerald-700' : 'bg-white border-slate-100 text-slate-500 hover:border-blue-200'}`}
              >
                 <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 ${isStepComplete ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-white border-slate-300'}`}>
                    {isStepComplete && <IconCheck className="w-4 h-4" />}
                 </div>
                 <span className="text-sm font-bold">{isStepComplete ? 'Completed Stage' : 'Mark as Done'}</span>
              </button>
           </div>

           <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-soft flex flex-col flex-1 min-h-0 overflow-hidden">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Evidence Gallery</h3>
                <label className="cursor-pointer active:scale-95 transition-transform">
                   <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                   <div className="px-3 py-1 bg-blue-600 text-white rounded-lg text-xs font-bold shadow-sm">Upload</div>
                </label>
              </div>

              <div className="flex-1 overflow-y-auto pr-1 space-y-3">
                {stepAssets.length === 0 ? (
                  <div className="h-32 flex flex-col items-center justify-center text-center border-2 border-dashed border-slate-100 rounded-xl text-slate-300 text-xs px-6">
                     No assets added for this step.
                  </div>
                ) : (
                  [...stepAssets].reverse().map((asset, i) => (
                    <AssetCard key={i} asset={asset} onClick={() => { const url = asset.url || asset.dataURL; if(url) window.open(url, '_blank'); }} onContextMenu={(e) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, assetIndex: project.assets.indexOf(asset) })} onMoreClick={(e) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, assetIndex: project.assets.indexOf(asset) })} />
                  ))
                )}
              </div>
           </div>
        </div>
      </div>

      {/* 3. Mobile Navigation Controls */}
      <div className="sticky bottom-0 md:static bg-white/95 md:bg-transparent backdrop-blur-xl p-4 md:p-0 border-t md:border-0 border-slate-200 flex justify-between items-center z-40 pb-safe">
         <Button variant="ghost" onClick={() => prevStep && onStepSelect(prevStep.id)} className={`px-2 ${!prevStep && 'invisible'}`}>Back</Button>
         <div className="flex gap-2">
            <button 
                onClick={toggleStepCompletion} 
                className={`p-3 rounded-full border transition-all active:scale-90 ${isStepComplete ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-slate-50 border-slate-200 text-slate-400'}`}
                title="Mark step complete"
            >
                <IconCheck className="w-6 h-6" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} className="bg-blue-600 px-8 shadow-xl shadow-blue-500/20 rounded-full font-black">
                {nextStep ? 'Continue' : 'Finalize'} <IconArrowRight className="w-4 h-4 ml-2" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Download', icon: <IconDownload className="w-4 h-4" />, onClick: () => { if(contextMenu) { const a = project.assets[contextMenu.assetIndex]; const url = a.url || a.dataURL; if(url) { const l = document.createElement('a'); l.href = url; l.download = a.name; l.click(); } } } },
          { label: 'Replace', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />
      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
    </main>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Project, AppState, Asset, ProjectVersion } from './types';
import { STAGES } from './constants';
import { Sidebar } from './components/Sidebar';
import { Workspace } from './components/Workspace';
import { CreateProjectModal } from './components/CreateProjectModal';
import { ConfirmModal } from './components/ConfirmModal';
import { ExportModal } from './components/ExportModal';
import { Toast, ToastProps } from './components/ui/Toast';
import { Tour } from './components/Tour';
import { Button } from './components/ui/Button';
import { IconMenu, IconLayout, IconPlus, IconBug, IconTrash, IconClose } from './components/ui/Icons';

function uid() {
  return 'p_' + Math.random().toString(36).slice(2, 9);
}

const STORAGE_KEY = 'uxmate_projects_v2';
const STORAGE_WARNING_THRESHOLD = 4.5 * 1024 * 1024; 

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    try {
      const local = localStorage.getItem(STORAGE_KEY);
      if (local) return JSON.parse(local);
    } catch (e) { console.error('Failed to load state', e); }
    return { projects: {}, activeProjectId: null };
  });

  const [isTemplatesOpen, setIsTemplatesOpen] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [exportProject, setExportProject] = useState<Project | null>(null);
  const [showMobileProjects, setShowMobileProjects] = useState(false);
  const [toast, setToast] = useState<Omit<ToastProps, 'onClose'> | null>(null);
  const [confirmConfig, setConfirmConfig] = useState<{isOpen: boolean; title: string; message: string; onConfirm: () => void;}>({ isOpen: false, title: '', message: '', onConfirm: () => {} });
  const [devClickCount, setDevClickCount] = useState(0);
  const [isDevMode, setIsDevMode] = useState(false);
  const [isDebugOpen, setIsDebugOpen] = useState(false);

  useEffect(() => {
    try {
      const json = JSON.stringify(state);
      localStorage.setItem(STORAGE_KEY, json);
      if (new Blob([json]).size > STORAGE_WARNING_THRESHOLD) setToast({ message: 'Storage critical!', type: 'error' });
    } catch (e) { setToast({ message: 'Storage full!', type: 'error' }); }
  }, [state]);

  useEffect(() => {
    if (Object.keys(state.projects).length === 0) {
      const id = uid();
      const example: Project = {
        id, title: 'Project: Grocery App', desc: 'Redesigning the cart experience', notes: '',
        stages: {}, steps: STAGES.reduce((acc, s) => ({ ...acc, [s.id]: { notes: '', isComplete: false } }), {}),
        assets: [], createdAt: new Date().toISOString(), currentStepId: 'problem'
      };
      setState({ projects: { [id]: example }, activeProjectId: id });
    }
  }, []);

  const activeProject = state.activeProjectId ? state.projects[state.activeProjectId] : null;

  const handleCreateProject = (title: string, desc: string) => {
    const id = uid();
    const newProj: Project = { id, title, desc, notes: '', stages: {}, steps: STAGES.reduce((acc, s) => ({ ...acc, [s.id]: { notes: '', isComplete: false } }), {}), assets: [], createdAt: new Date().toISOString(), currentStepId: 'problem' };
    setState(prev => ({ projects: { ...prev.projects, [id]: newProj }, activeProjectId: id }));
    setShowMobileProjects(false);
  };

  const deleteProject = (id: string) => {
    setState(prev => {
      const nextProjects = { ...prev.projects };
      delete nextProjects[id];
      return { projects: nextProjects, activeProjectId: prev.activeProjectId === id ? (Object.keys(nextProjects)[0] || null) : prev.activeProjectId };
    });
  };

  const updateProject = (id: string, updates: Partial<Project>) => {
    setState(prev => ({ ...prev, projects: { ...prev.projects, [id]: { ...prev.projects[id], ...updates } } }));
  };

  const updateStepData = useCallback((stepId: string, data: { notes: string; isComplete: boolean }) => {
     if (!state.activeProjectId) return;
     setState(prev => {
         const p = prev.projects[prev.activeProjectId!];
         if (!p) return prev;
         const newSteps = { ...p.steps, [stepId]: { ...p.steps[stepId], ...data } };
         return { ...prev, projects: { ...prev.projects, [p.id]: { ...p, steps: newSteps, history: [{ timestamp: new Date().toISOString(), notes: p.notes, stepData: newSteps }, ...(p.history || [])].slice(0, 3) } } };
     });
  }, [state.activeProjectId]);

  const duplicateProject = (id: string) => {
    const source = state.projects[id];
    if(!source) return;
    const newId = uid();
    setState(prev => ({ projects: { ...prev.projects, [newId]: { ...source, id: newId, title: `${source.title} (Copy)`, createdAt: new Date().toISOString() } }, activeProjectId: newId }));
  };

  const handleAssetUpload = async (file: File) => {
    if (!activeProject) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const asset: Asset = { name: file.name, type: file.type, dataURL: e.target?.result as string, createdAt: new Date().toISOString(), size: file.size, stepId: activeProject.currentStepId || 'problem' };
      setState(prev => {
        const p = prev.projects[activeProject.id];
        return { ...prev, projects: { ...prev.projects, [p.id]: { ...p, assets: [...p.assets, asset] } } };
      });
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col font-sans">
      <header className="h-14 border-b border-slate-200 bg-white/80 backdrop-blur-md flex items-center px-4 sticky top-0 z-40 shrink-0">
        <div onClick={() => { if(devClickCount + 1 === 5) setIsDevMode(true); setDevClickCount(prev => prev + 1); }} className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center font-black text-white mr-3 shadow-md select-none cursor-pointer active:scale-95">UX</div>
        <h1 className="font-extrabold text-sm tracking-tight">UXMate</h1>
        {isDevMode && <button onClick={() => setIsDebugOpen(true)} className="ml-auto p-1.5 rounded bg-red-50 text-red-500"><IconBug className="w-4 h-4" /></button>}
      </header>

      <div className="flex-1 flex flex-col md:flex-row overflow-hidden max-w-[1600px] mx-auto w-full md:p-6 md:gap-6 relative">
        <Sidebar 
          state={state} activeProject={activeProject}
          onOpenCreateModal={() => setIsCreateModalOpen(true)}
          switchProject={(id) => { setState(prev => ({ ...prev, activeProjectId: id })); setShowMobileProjects(false); }}
          deleteProject={deleteProject} duplicateProject={duplicateProject}
          onExport={setExportProject}
          mobileOpen={showMobileProjects} onCloseMobile={() => setShowMobileProjects(false)}
          currentStepId={activeProject?.currentStepId || 'problem'}
          onStepSelect={(id) => { if(activeProject) updateProject(activeProject.id, { currentStepId: id }); setShowMobileProjects(false); }}
        />

        <Workspace 
          project={activeProject} 
          updateProject={updateProject} 
          updateStepData={updateStepData}
          restoreProjectVersion={(v) => { if(activeProject) updateProject(activeProject.id, { notes: v.notes, steps: v.stepData || activeProject.steps }); setToast({ message: 'Restored!', type: 'success' }); }}
          deleteAsset={(idx) => { if(activeProject) { const a = [...activeProject.assets]; a.splice(idx, 1); updateProject(activeProject.id, { assets: a }); } }}
          onReplaceAsset={() => {}} 
          isTemplatesOpen={isTemplatesOpen}
          setIsTemplatesOpen={setIsTemplatesOpen}
          onExport={setExportProject} 
          onUploadAsset={handleAssetUpload}
          currentStepId={activeProject?.currentStepId || 'problem'}
          onStepSelect={(id) => { if(activeProject) updateProject(activeProject.id, { currentStepId: id }); }}
        />
      </div>

      {/* Modern Mobile Navigation Bar */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 h-20 glass-nav border-t border-slate-200 flex items-center justify-around px-6 pb-safe z-50">
        <NavButton active={showMobileProjects} icon={IconMenu} label="Process" onClick={() => setShowMobileProjects(!showMobileProjects)} />
        <button onClick={() => setIsCreateModalOpen(true)} className="w-14 h-14 -mt-10 bg-blue-600 rounded-full text-white shadow-fab flex items-center justify-center active:scale-90 transition-transform"><IconPlus className="w-7 h-7" /></button>
        <NavButton active={isTemplatesOpen} icon={IconLayout} label="Templates" onClick={() => setIsTemplatesOpen(true)} />
      </nav>

      <Tour />
      <CreateProjectModal isOpen={isCreateModalOpen} onClose={() => setIsCreateModalOpen(false)} onCreate={handleCreateProject} />
      <ExportModal project={exportProject} isOpen={!!exportProject} onClose={() => setExportProject(null)} />
      <ConfirmModal isOpen={confirmConfig.isOpen} title={confirmConfig.title} message={confirmConfig.message} onConfirm={confirmConfig.onConfirm} onClose={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} />
      {toast && <Toast message={toast.message} type={toast.type} onUndo={toast.onUndo} onClose={() => setToast(null)} />}

      {isDebugOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4">
           <div className="bg-white rounded-2xl w-full max-w-lg h-[60vh] flex flex-col overflow-hidden shadow-2xl">
              <div className="p-4 border-b flex justify-between items-center"><h2 className="font-bold">Debug</h2><button onClick={() => setIsDebugOpen(false)}><IconClose className="w-5 h-5"/></button></div>
              <pre className="flex-1 overflow-auto bg-slate-900 text-green-400 p-4 text-[10px]">{JSON.stringify(state, null, 2)}</pre>
           </div>
        </div>
      )}
    </div>
  );
};

const NavButton = ({ active, icon: Icon, label, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-colors active:scale-95 ${active ? 'text-blue-600' : 'text-slate-400'}`}>
    <Icon className="w-5 h-5" />
    <span className="text-[10px] font-bold uppercase tracking-wider">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
import { IconDownload, IconTrash, IconFile, IconReplace, IconHistory, IconCheck, IconArrowRight, IconLayout } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
import { AssetCard } from './ui/AssetCard';
import { ContextMenu } from './ui/ContextMenu';
import { HistoryModal } from './HistoryModal';
import { TemplatesModal } from './TemplatesModal';
import { generateFullHtml } from '../utils/exporter';

interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  isTemplatesOpen: boolean;
  setIsTemplatesOpen: (open: boolean) => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  isTemplatesOpen,
  setIsTemplatesOpen,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editTitleVal, setEditTitleVal] = useState('');
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  // Sync with project data
  useEffect(() => {
    if (project && project.steps) {
      const stepData = project.steps[currentStepId] || { notes: '', isComplete: false };
      let externalNotes = stepData.notes;

      // Fallback for problem step
      if (currentStepId === 'problem' && !externalNotes && project.notes) {
        externalNotes = project.notes;
      }

      // Only update local notes if they differ from external source and we aren't "saving"
      // This prevents overwriting user input while preserving external insertions
      if (externalNotes !== notesRef.current) {
        setNotes(externalNotes);
        notesRef.current = externalNotes;
      }
    }
  }, [project?.id, currentStepId, project?.steps?.[currentStepId]?.notes]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project || !project.steps) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps[currentStepId]?.isComplete || false;

    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project || !project.steps) return;
    const isComplete = project.steps[currentStepId]?.isComplete || false;
    updateStepData(currentStepId, { notes, isComplete: !isComplete });
  };

  const handleTemplateInsert = (content: string) => {
    const newNotes = notes.trim() ? notes + "\n\n" + content : content;
    setNotes(newNotes);
    notesRef.current = newNotes;
    setSaveStatus('modified');
    handleSave(); // Immediate sync
  };

  const saveTitle = () => {
    if (project && editTitleVal.trim() && editTitleVal !== project.title) {
      updateProject(project.id, { title: editTitleVal });
    }
    setIsEditingTitle(false);
  };

  if (!project) {
    return (
      <div className={`flex-1 flex flex-col items-center justify-center p-10 text-center ${className}`}>
        <IconFile className="w-12 h-12 text-slate-200 mb-4" />
        <h2 className="text-lg font-semibold text-slate-900 mb-2">Select a Project</h2>
        <p className="text-slate-500 max-w-xs text-sm">Choose or create a project to start documenting your design process.</p>
      </div>
    );
  }

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = project.steps ? Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100) : 0;
  const stepAssets = project.assets ? project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) : [];

  if (currentStepId === 'casestudy') {
    const previewHtml = generateFullHtml(project, true);
    return (
      <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`}>
         <div className="bg-white border-b md:border md:border-slate-200 md:rounded-2xl p-4 md:p-6 shadow-soft flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div>
                <h1 className="text-xl md:text-2xl font-bold text-slate-900">Portfolio Preview</h1>
                <p className="text-slate-500 text-xs md:text-sm mt-0.5">Automated case study based on your process.</p>
            </div>
            <Button onClick={() => onExport(project)} className="bg-blue-600 text-white w-full md:w-auto shadow-lg shadow-blue-500/20">
                <IconDownload className="w-4 h-4 mr-2" /> Export Document
            </Button>
         </div>
         <div className="flex-1 bg-white md:rounded-2xl overflow-hidden relative border-y md:border border-slate-200 shadow-inner">
            <iframe srcDoc={previewHtml} title="Preview" className="w-full h-full border-0 bg-white" sandbox="allow-same-origin" />
         </div>
         <div className="px-4 md:px-0 pb-24 md:pb-0">
            <Button variant="outline" onClick={() => onStepSelect(prevStep.id)} className="w-full md:w-auto">Back to Editor</Button>
         </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`} role="main">
      <div className="bg-white border-b md:border md:border-slate-200 md:rounded-2xl p-4 md:p-6 shadow-soft flex flex-col gap-3 md:gap-4 shrink-0">
        <div className="flex justify-between items-start">
          <div className="min-w-0 pr-4">
            <div className="text-[10px] md:text-xs font-bold text-blue-600 uppercase tracking-widest mb-1">Step {currentStepIndex + 1}</div>
            <h1 className="text-lg md:text-2xl font-extrabold text-slate-900 truncate leading-tight">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <ProgressRing progress={progress} radius={window.innerWidth < 768 ? 20 : 24} className="text-blue-600 shrink-0" />
        </div>

        <div className="flex items-center gap-2 pt-3 border-t border-slate-50 overflow-hidden">
             {isEditingTitle ? (
                 <input autoFocus type="text" className="text-xs font-bold text-slate-900 bg-blue-50 border-b-2 border-blue-500 outline-none flex-1 px-1 py-0.5 rounded" value={editTitleVal} onChange={e => setEditTitleVal(e.target.value)} onBlur={saveTitle} onKeyDown={e => e.key === 'Enter' && saveTitle()} />
               ) : (
                 <span className="text-xs font-bold text-slate-500 truncate cursor-pointer hover:text-blue-600 transition-colors" onClick={() => {setEditTitleVal(project.title); setIsEditingTitle(true);}}>{project.title}</span>
            )}
             <button onClick={() => setIsHistoryOpen(true)} className="ml-auto text-[10px] font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded-md active:scale-95">
                <IconHistory className="w-3 h-3 mr-1 inline" /> History
             </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col lg:grid lg:grid-cols-3 gap-4 md:gap-6 overflow-hidden px-4 md:px-0">
        <div className="lg:col-span-2 flex flex-col min-h-0 flex-1">
          <div className="bg-white border border-slate-200 rounded-2xl shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex items-center justify-between px-4 py-2 border-b border-slate-50 bg-slate-50/30">
               <button onClick={() => setIsTemplatesOpen(true)} className="text-blue-600 text-[10px] font-black uppercase tracking-wider flex items-center h-8 active:scale-95">
                  <IconLayout className="w-4 h-4 mr-1.5" /> Insert Template
               </button>
               <div className={`text-[10px] font-bold uppercase ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                   {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Saved' : ''}
               </div>
            </div>
            <textarea
              value={notes}
              onChange={handleNotesChange}
              onBlur={handleSave} 
              placeholder={`Document your ${currentStage.label.toLowerCase().replace(/^\d+\.\s/, '')}...`}
              className="w-full flex-1 bg-white p-5 md:p-8 resize-none focus:outline-none text-slate-800 leading-relaxed text-base md:text-lg font-sans"
            />
          </div>
        </div>

        <div className="hidden lg:flex flex-col gap-6 w-full max-w-sm">
           <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-soft">
              <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-4">Milestone Control</h3>
              <button 
                onClick={toggleStepCompletion}
                className={`w-full flex items-center gap-3 p-4 rounded-xl border-2 transition-all ${isStepComplete ? 'bg-emerald-50 border-emerald-500 text-emerald-700' : 'bg-white border-slate-100 text-slate-500 hover:border-blue-200'}`}
              >
                 <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0 ${isStepComplete ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-white border-slate-300'}`}>
                    {isStepComplete && <IconCheck className="w-4 h-4" />}
                 </div>
                 <span className="text-sm font-bold">{isStepComplete ? 'Completed Stage' : 'Mark as Done'}</span>
              </button>
           </div>

           <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-soft flex flex-col flex-1 min-h-0 overflow-hidden">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Evidence Gallery</h3>
                <label className="cursor-pointer active:scale-95 transition-transform">
                   <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                   <div className="px-3 py-1 bg-blue-600 text-white rounded-lg text-xs font-bold shadow-sm">Upload</div>
                </label>
              </div>

              <div className="flex-1 overflow-y-auto pr-1 space-y-3">
                {stepAssets.length === 0 ? (
                  <div className="h-32 flex flex-col items-center justify-center text-center border-2 border-dashed border-slate-100 rounded-xl text-slate-300 text-xs px-6">
                     No assets added for this step.
                  </div>
                ) : (
                  [...stepAssets].reverse().map((asset, i) => (
                    <AssetCard key={i} asset={asset} onClick={() => { const url = asset.url || asset.dataURL; if(url) window.open(url, '_blank'); }} onContextMenu={(e) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, assetIndex: project.assets.indexOf(asset) })} onMoreClick={(e) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, assetIndex: project.assets.indexOf(asset) })} />
                  ))
                )}
              </div>
           </div>
        </div>
      </div>

      <div className="sticky bottom-0 md:static bg-white/95 md:bg-transparent backdrop-blur-xl p-4 md:p-0 border-t md:border-0 border-slate-200 flex justify-between items-center z-40 pb-safe">
         <Button variant="ghost" onClick={() => prevStep && onStepSelect(prevStep.id)} className={`px-2 ${!prevStep && 'invisible'}`}>Back</Button>
         <div className="flex gap-2">
            <button 
                onClick={toggleStepCompletion} 
                className={`p-3 rounded-full border transition-all active:scale-90 ${isStepComplete ? 'bg-emerald-500 border-emerald-500 text-white' : 'bg-slate-50 border-slate-200 text-slate-400'}`}
                title="Mark step complete"
            >
                <IconCheck className="w-6 h-6" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} className="bg-blue-600 px-8 shadow-xl shadow-blue-500/20 rounded-full font-black">
                {nextStep ? 'Continue' : 'Finalize'} <IconArrowRight className="w-4 h-4 ml-2" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Download', icon: <IconDownload className="w-4 h-4" />, onClick: () => { if(contextMenu) { const a = project.assets[contextMenu.assetIndex]; const url = a.url || a.dataURL; if(url) { const l = document.createElement('a'); l.href = url; l.download = a.name; l.click(); } } } },
          { label: 'Replace', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />
      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />

      <TemplatesModal 
        isOpen={isTemplatesOpen} 
        onClose={() => setIsTemplatesOpen(false)} 
        onInsert={handleTemplateInsert} 
      />
    </main>
  );
};

