          <Button onClick={() => onExport(project)} className="bg-blue-600">
            <IconDownload className="w-4 h-4 mr-2" /> Download Document
          </Button>
        </div>

        <div className="flex-1 flex flex-col lg:grid lg:grid-cols-4 gap-6 overflow-hidden">
          <div className="lg:col-span-1 bg-white border border-slate-200 rounded-2xl p-6 shadow-soft flex flex-col gap-6 overflow-y-auto">
             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Identity</h3>
                <div className="space-y-3">
                   <input type="text" placeholder="Design Lead Name" className="w-full text-xs font-bold p-2 bg-slate-50 border rounded-lg" value={config.designerName} onChange={e => updateExportConfig({ designerName: e.target.value })} />
                   <input type="text" placeholder="Your Role" className="w-full text-xs p-2 bg-slate-50 border rounded-lg" value={config.designerRole} onChange={e => updateExportConfig({ designerRole: e.target.value })} />
                </div>
             </section>

             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Theme & Style</h3>
                <div className="grid grid-cols-3 gap-2 mb-3">
                   {['modern', 'classic', 'minimal'].map(t => (
                     <button key={t} onClick={() => updateExportConfig({ theme: t as any })} className={`p-2 text-[10px] font-bold rounded-lg border capitalize ${config.theme === t ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-50 text-slate-500'}`}>{t}</button>
                   ))}
                </div>
                <div className="flex items-center gap-3">
