                </div>
             </section>

             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Structure</h3>
                <div className="space-y-2">
                   {[
                     { label: 'Cover Page', key: 'showCover' },
                     { label: 'Process Map', key: 'showTOC' },
                     { label: 'Evidence Gallery', key: 'showAssets' }
                   ].map(opt => (
                     <label key={opt.key} className="flex items-center justify-between p-2 bg-slate-50 rounded-lg cursor-pointer">
                        <span className="text-xs font-bold text-slate-600">{opt.label}</span>
                        <input type="checkbox" checked={(config as any)[opt.key]} onChange={e => updateExportConfig({ [opt.key]: e.target.checked })} />
                     </label>
                   ))}
                </div>
             </section>

             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Visible Phases</h3>
                <div className="space-y-1 max-h-48 overflow-y-auto pr-1">
                   {STAGES.filter(s => s.id !== 'casestudy').map(s => (
                     <label key={s.id} className="flex items-center gap-2 p-1.5 hover:bg-slate-50 rounded text-[10px] cursor-pointer">
                        <input type="checkbox" checked={!config.excludedSteps.includes(s.id)} onChange={e => {
                           const excluded = e.target.checked ? config.excludedSteps.filter(id => id !== s.id) : [...config.excludedSteps, s.id];
                           updateExportConfig({ excludedSteps: excluded });
                        }} />
                        <span className="truncate">{s.label.split('. ')[1]}</span>
                     </label>
                   ))}
                </div>
             </section>
          </div>

          <div className="lg:col-span-3 bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-inner relative">
             <iframe srcDoc={previewHtml} className="w-full h-full border-0" sandbox="allow-same-origin" />
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col gap-4 md:gap-6 min-w-0 ${className}`} role="main">
      <div className="bg-white border-b md:border md:border-slate-200 md:rounded-2xl p-4 md:p-6 shadow-soft flex flex-col gap-3 md:gap-4 shrink-0">
        <div className="flex justify-between items-start">
          <div className="min-w-0 pr-4">
