import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, AppState } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
// Fix: Added missing IconFile import
import { IconPlus, IconCheck, IconTrash, IconCopy, IconDownload, IconChevronDown, IconSearch, IconArrowRight, IconClose, IconFile } from './ui/Icons';

interface SidebarProps {
  state: AppState;
  onOpenCreateModal: () => void;
  switchProject: (id: string) => void;
  deleteProject: (id: string) => void;
  duplicateProject: (id: string) => void;
  onExport: (project: Project) => void;
  activeProject: Project | null;
  onStepSelect: (stepId: string) => void;
  currentStepId: string;
  className?: string;
  mobileOpen?: boolean;
  onCloseMobile?: () => void;
}

const PROJECT_ROW_HEIGHT = 80;

export const Sidebar: React.FC<SidebarProps> = ({
  state,
  onOpenCreateModal,
  switchProject,
  deleteProject,
  duplicateProject,
  activeProject,
  onStepSelect,
  currentStepId,
  className = '',
  mobileOpen = false,
  onCloseMobile
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const listRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(400);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setScrollTop(0);
    }, 200);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  useEffect(() => {
    if (listRef.current) {
      setViewportHeight(listRef.current.clientHeight);
      const ro = new ResizeObserver(() => setViewportHeight(listRef.current?.clientHeight || 400));
      ro.observe(listRef.current);
      return () => ro.disconnect();
    }
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => setScrollTop(e.currentTarget.scrollTop);

  const filteredProjects = useMemo(() => {
    const all = Object.values(state.projects) as Project[];
    const sorted = all.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    if (!debouncedSearch.trim()) return sorted;
    const lower = debouncedSearch.toLowerCase();
    return sorted.filter(p => p.title.toLowerCase().includes(lower));
  }, [state.projects, debouncedSearch]);

  const totalCount = filteredProjects.length;
  const startIndex = Math.max(0, Math.floor(scrollTop / PROJECT_ROW_HEIGHT) - 1);
  const endIndex = Math.min(totalCount, Math.ceil((scrollTop + viewportHeight) / PROJECT_ROW_HEIGHT) + 1);
  const visibleProjects = filteredProjects.slice(startIndex, endIndex);

  return (
    <aside 
      className={`
        fixed inset-0 z-[100] bg-white flex flex-col transition-transform duration-500 ease-in-out md:relative md:translate-y-0 md:inset-auto md:z-0 md:bg-transparent md:w-80 lg:w-96 md:gap-6
        ${mobileOpen ? 'translate-y-0' : 'translate-y-full md:translate-y-0'}
        ${className}
      `}
      role="complementary"
    >
        {/* Mobile Header Dashboard Style */}
        <div className="md:hidden pt-safe shrink-0 bg-slate-900 text-white p-6 rounded-b-[3rem] shadow-2xl">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h2 className="text-2xl font-black tracking-tight">Process Map</h2>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Milestones & Flow</p>
            </div>
            <button onClick={onCloseMobile} className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center active:scale-90 transition-transform">
              <IconClose className="w-6 h-6 text-white" />
            </button>
          </div>

          <div className="flex gap-4 mb-2 overflow-x-auto hide-scrollbar">
             {/* Stats summary for mobile dashboard */}
             <div className="bg-white/5 border border-white/10 rounded-3xl p-4 min-w-[140px]">
                <div className="text-[10px] font-black text-slate-500 uppercase">Step Success</div>
                <div className="text-xl font-black mt-1 text-emerald-400">
                  {activeProject ? STAGES.filter(s => activeProject.steps?.[s.id]?.isComplete).length : 0} / 12
                </div>
             </div>
             <div className="bg-white/5 border border-white/10 rounded-3xl p-4 min-w-[140px]">
                <div className="text-[10px] font-black text-slate-500 uppercase">Phase</div>
                <div className="text-xl font-black mt-1 text-blue-400">
                  {STAGES.findIndex(s => s.id === currentStepId) + 1}
                </div>
             </div>
          </div>
        </div>

        {/* Project Selector (Compressed for mobile flow) */}
        <div className="md:bg-white md:border md:border-slate-200 md:rounded-3xl p-4 md:shadow-soft flex flex-col h-[25vh] md:h-auto md:max-h-[40vh] overflow-hidden">
          <div className="flex items-center justify-between mb-3 px-2">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Workspace</h3>
            <Button size="sm" variant="ghost" onClick={onOpenCreateModal} className="h-8 px-3 text-blue-600 font-black">
              <IconPlus className="w-3.5 h-3.5 mr-1" /> Add
            </Button>
          </div>

          <div ref={listRef} onScroll={handleScroll} className="flex-1 overflow-y-auto pr-1 space-y-2 px-2">
            {totalCount === 0 ? (
              <div className="text-center py-6 text-slate-400 text-xs italic">No projects active</div>
            ) : (
              <div style={{ paddingTop: `${startIndex * PROJECT_ROW_HEIGHT}px`, paddingBottom: `${(totalCount - endIndex) * PROJECT_ROW_HEIGHT}px` }}>
                {visibleProjects.map(p => {
                  const isActive = activeProject?.id === p.id;
                  const completedCount = STAGES.filter(s => p.steps?.[s.id]?.isComplete).length;
                  return (
                    <div key={p.id} style={{ height: `${PROJECT_ROW_HEIGHT}px` }} className="pb-2">
                      <div 
                        className={`p-4 h-full rounded-2xl transition-all cursor-pointer border flex justify-between items-center ${isActive ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`} 
                        onClick={() => { switchProject(p.id); }}
                      >
                        <div className="min-w-0 pr-4">
                          <div className={`text-sm font-black truncate ${isActive ? 'text-white' : 'text-slate-900'}`}>{p.title}</div>
                          <div className={`text-[10px] font-bold mt-0.5 ${isActive ? 'text-blue-100' : 'text-slate-400'}`}>{completedCount}/{STAGES.length} Complete</div>
                        </div>
                        <div className="flex gap-2 shrink-0">
                          <button className={`p-2 rounded-xl transition-colors ${isActive ? 'bg-white/10 hover:bg-white/20' : 'text-slate-400 hover:bg-slate-200'}`} onClick={(e) => { e.stopPropagation(); duplicateProject(p.id); }}><IconCopy className="w-4 h-4" /></button>
                          <button className={`p-2 rounded-xl transition-colors ${isActive ? 'bg-white/10 hover:bg-red-400/30 text-white' : 'text-slate-400 hover:text-red-500 hover:bg-red-50'}`} onClick={(e) => { e.stopPropagation(); deleteProject(p.id); }}><IconTrash className="w-4 h-4" /></button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Process Steps (Main Interaction Area) */}
        <div className="flex-1 bg-white md:border md:border-slate-200 md:rounded-3xl p-6 md:shadow-soft flex flex-col overflow-hidden mb-20 md:mb-0">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Phase Selection</h3>
          <div className="overflow-y-auto flex-1 pr-2 space-y-3 pb-20">
            {activeProject ? (
              STAGES.map((stage, idx) => {
                const isDone = activeProject.steps?.[stage.id]?.isComplete;
                const isActive = currentStepId === stage.id;
                return (
                  <button 
                    key={stage.id} 
                    onClick={() => { onStepSelect(stage.id); }} 
                    className={`w-full text-left rounded-2xl transition-all border flex items-center gap-4 p-4 active:scale-[0.97] ${isActive ? 'bg-blue-50 border-blue-200 shadow-md ring-4 ring-blue-50/50' : 'bg-white border-slate-100 hover:border-slate-300'}`}
                  >
                      <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-xs font-black border-2 shrink-0 transition-all ${isActive ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : isDone ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-slate-50 border-slate-200 text-slate-300'}`}>
                        {isDone && !isActive ? <IconCheck className="w-5 h-5" /> : (idx + 1)}
                      </div>
                      <div className="flex-1 min-w-0">
                         <div className={`text-sm font-black tracking-tight ${isActive ? 'text-blue-900' : isDone ? 'text-emerald-900' : 'text-slate-600'}`}>{stage.label.split('. ')[1]}</div>
                         <div className={`text-[10px] font-bold ${isActive ? 'text-blue-400' : isDone ? 'text-emerald-400' : 'text-slate-300'}`}>
                           {isActive ? 'Active Workspace' : isDone ? 'Milestone Reached' : 'Locked Phase'}
                         </div>
                      </div>
                      {isActive && <IconArrowRight className="w-5 h-5 text-blue-300" />}
                  </button>
                );
              })
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4 opacity-50">
                 <IconFile className="w-12 h-12" />
                 <span className="text-xs font-bold uppercase tracking-widest">Select Project</span>
              </div>
            )}
          </div>
        </div>
    </aside>
  );
};

import { Project, Asset, ExportConfig } from "../types";
import { STAGES } from "../constants";

function escapeHtml(s: string) {
  return (s || '').toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/**
 * A simple but effective Markdown parser for the export engine.
 * Handles: Headers (###), Bold (**), Lists (- or *), and Line Breaks.
 */
export function parseMarkdown(text: string): string {
  if (!text) return '';

  let html = escapeHtml(text);

  // Headers: ### Title -> <h3>Title</h3>
  html = html.replace(/^### (.*$)/gim, '<h3 style="margin-top: 24px; margin-bottom: 8px; font-weight: 800; color: #0f172a; font-size: 18px;">$1</h3>');
  html = html.replace(/^## (.*$)/gim, '<h2 style="margin-top: 32px; margin-bottom: 12px; font-weight: 800; color: #0f172a; font-size: 22px; border-bottom: 1px solid #eee; padding-bottom: 8px;">$1</h2>');

  // Bold: **text** -> <strong>text</strong>
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #111827; font-weight: 700;">$1</strong>');

  // Lists: - item or * item -> <li>item</li>
  const lines = html.split('\n');
  let inList = false;
  const processedLines = lines.map(line => {
    const listMatch = line.match(/^[-*] (.*)/);
    if (listMatch) {
      const content = listMatch[1];
      if (!inList) {
        inList = true;
        return `<ul style="margin-bottom: 16px; padding-left: 20px; list-style-type: disc;"><li style="margin-bottom: 4px;">${content}</li>`;
      }
      return `<li style="margin-bottom: 4px;">${content}</li>`;
    } else {
      if (inList) {
        inList = false;
        return `</ul>${line}<br>`;
      }
      return line + '<br>';
    }
  });

  html = processedLines.join('');

  return html;
}

function getAssetHtml(assets: Asset[], showAssets: boolean) {
  if (!showAssets || !assets || assets.length === 0) return '';

  return `
    <div class="assets-grid" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; margin: 24px 0;">
      ${assets.map(a => {
         const displayUrl = a.url || a.dataURL;
         if (!a.type.startsWith('image') || !displayUrl) return '';
         return `
           <div class="asset-item" style="border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; background: #fff; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.05); page-break-inside: avoid;">
             <img src="${displayUrl}" style="max-width: 100%; height: auto; display: block; object-fit: contain; background: #f8fafc; margin: 0 auto;" />
             <div class="asset-caption" style="padding: 16px; font-size: 13px; color: #64748b; text-align: center; border-top: 1px solid #f1f5f9; font-weight: 500; line-height: 1.5;">
               ${escapeHtml(a.caption || a.name)}
             </div>
           </div>
         `;
      }).join('')}
    </div>
  `;
}

export function generateCaseStudyHtml(project: Project): string {
  const config: ExportConfig = project.exportConfig || {
    theme: 'modern',
    primaryColor: '#3B82F6',
    fontFamily: 'Inter',
    showCover: true,
    showTOC: true,
    showAssets: true,
    designerName: '',
    designerRole: 'UX Designer',
    excludedSteps: []
  };

  const stepsHtml = STAGES.filter(s => s.id !== 'casestudy' && !config.excludedSteps.includes(s.id)).map((stage, index) => {
    const stepData = project.steps?.[stage.id] || { notes: '', isComplete: false };
    const content = stepData.notes || (stage.id === 'problem' ? project.notes : '');
    const stepAssets = project.assets.filter(a => (a.stepId === stage.id) || (stage.id === 'problem' && !a.stepId));

    if (!content && stepAssets.length === 0) return '';

    return `
      <section class="step-section" style="margin-bottom: 80px; page-break-inside: avoid;">
        <div class="step-header" style="display: flex; align-items: center; gap: 16px; margin-bottom: 24px;">
          <span class="step-num" style="background: ${config.primaryColor}; color: white; width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; border-radius: 10px; font-size: 15px; font-weight: 800;">${index + 1}</span>
          <h2 class="step-title" style="font-size: 32px; margin: 0; font-weight: 800; color: #0f172a; letter-spacing: -0.03em;">${escapeHtml(stage.label.replace(/^\d+\.\s/, ''))}</h2>
        </div>
        <div class="step-content">
          ${content ? `<div class="step-notes" style="font-size: 18px; color: #374151; line-height: 1.8; margin-bottom: 40px;">${parseMarkdown(content)}</div>` : ''}
          ${getAssetHtml(stepAssets, config.showAssets)}
        </div>
      </section>
    `;
  }).join('');

  const fontStack = config.fontFamily === 'Serif' ? 'Georgia, serif' : config.fontFamily === 'Mono' ? 'monospace' : "'Inter', sans-serif";

  return `
  <!DOCTYPE html>
  <html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${escapeHtml(project.title)}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

      * { box-sizing: border-box; }

      body {
        font-family: ${fontStack};
        color: #111827;
        line-height: 1.6;
        margin: 0;
        background: ${config.theme === 'minimal' ? '#fff' : '#f8fafc'};
        -webkit-print-color-adjust: exact;
      }

      img {
        max-width: 100%;
        height: auto;
      }

      .document-wrapper {
        max-width: 1000px;
        margin: 0 auto;
        padding: 80px 40px;
        background: white;
        box-shadow: 0 0 60px rgba(0,0,0,0.04);
      }

      @media (max-width: 768px) {
        .document-wrapper { padding: 40px 20px; box-shadow: none; }
        .cover h1 { font-size: 48px !important; }
      }

      @media print {
        .document-wrapper { padding: 0; max-width: 100%; box-shadow: none; }
        body { background: white; }
        .step-section { page-break-inside: avoid; }
      }

      .cover {
        min-height: 80vh;
        display: ${config.showCover ? 'flex' : 'none'};
        flex-direction: column;
        justify-content: center;
        border-left: 20px solid ${config.primaryColor};
        padding-left: 60px;
        margin-bottom: 120px;
        background: linear-gradient(to right, #fafbfc, #fff);
      }
      .cover h1 { font-size: 72px; margin: 0; color: #0f172a; font-weight: 800; letter-spacing: -0.05em; line-height: 1.1; }
      .cover p { font-size: 26px; color: #64748b; margin-top: 24px; max-width: 700px; font-weight: 400; }
      .designer-info { margin-top: 80px; }
      .designer-name { font-size: 22px; font-weight: 700; color: #0f172a; }
      .designer-role { font-size: 15px; font-weight: 600; color: ${config.primaryColor}; text-transform: uppercase; letter-spacing: 0.15em; margin-top: 4px; }

      .toc { display: ${config.showTOC ? 'block' : 'none'}; margin-bottom: 100px; page-break-after: always; }
      .toc h2 { color: ${config.primaryColor}; text-transform: uppercase; font-size: 13px; letter-spacing: 4px; font-weight: 800; border-bottom: 2px solid #f1f5f9; padding-bottom: 16px; margin-bottom: 32px; }
      .toc-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; }
      .toc-item { font-size: 15px; font-weight: 600; color: #475569; display: flex; align-items: center; gap: 10px; }
      .toc-item span { color: ${config.primaryColor}; opacity: 0.4; font-size: 11px; font-weight: 800; }

      .step-section { border-bottom: 1px solid #f1f5f9; padding-bottom: 60px; }
      .step-section:last-child { border-bottom: none; }

      ul, li { margin: 0; padding: 0; }
    </style>
  </head>
  <body>
    <div class="document-wrapper">
      <div class="cover">
        <div style="font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.3em; color: ${config.primaryColor}; margin-bottom: 24px;">Case Study Overview</div>
        <h1>${escapeHtml(project.title)}</h1>
        <p>${escapeHtml(project.desc)}</p>
        <div class="designer-info">
          <div class="designer-name">${escapeHtml(config.designerName || 'UX Lead')}</div>
          <div class="designer-role">${escapeHtml(config.designerRole)}</div>
        </div>
      </div>

      <div class="toc">
        <h2>Process Journey</h2>
        <div class="toc-grid">
          ${STAGES.filter(s => s.id !== 'casestudy' && !config.excludedSteps.includes(s.id)).map((s, i) => `
            <div class="toc-item">
              <span>${String(i + 1).padStart(2, '0')}</span>
              ${escapeHtml(s.label.split('. ')[1])}
            </div>
          `).join('')}
        </div>
      </div>

      <div class="content">
        ${stepsHtml}
      </div>
    </div>
  </body>
  </html>
  `;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion, ExportConfig, Asset } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
import { IconDownload, IconTrash, IconFile, IconReplace, IconHistory, IconCheck, IconArrowRight, IconLayout, IconMoreVertical, IconPlus, IconEye } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
import { AssetCard } from './ui/AssetCard';
import { ContextMenu } from './ui/ContextMenu';
import { HistoryModal } from './HistoryModal';
import { GuideModal } from './GuideModal';
import { generateFullHtml } from '../utils/exporter';
import { parseMarkdown } from '../utils/pdfTemplate';

interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  isGuideOpen: boolean;
  setIsGuideOpen: (open: boolean) => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  isGuideOpen,
  setIsGuideOpen,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [activeMobileTab, setActiveMobileTab] = useState<'strategy' | 'evidence'>('strategy');
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [editTitleVal, setEditTitleVal] = useState('');
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  useEffect(() => {
    if (project && project.steps) {
      const stepData = project.steps[currentStepId] || { notes: '', isComplete: false };
      let externalNotes = stepData.notes;
      if (currentStepId === 'problem' && !externalNotes && project.notes) {
        externalNotes = project.notes;
      }
      if (externalNotes !== notesRef.current) {
        setNotes(externalNotes);
        notesRef.current = externalNotes;
      }
    }
  }, [project?.id, currentStepId, project?.steps?.[currentStepId]?.notes]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project || !project.steps) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps[currentStepId]?.isComplete || false;
    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project || !project.steps) return;
    const isComplete = project.steps[currentStepId]?.isComplete || false;
    updateStepData(currentStepId, { notes, isComplete: !isComplete });
  };

  const handleInsert = (content: string) => {
    const newNotes = notes.trim() ? notes + "\n\n" + content : content;
    setNotes(newNotes);
    notesRef.current = newNotes;
    setSaveStatus('modified');
    handleSave();
  };

  const updateExportConfig = (updates: Partial<ExportConfig>) => {
    if (!project) return;
    const current = project.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: []
    };
    updateProject(project.id, { exportConfig: { ...current, ...updates } });
  };

  const saveTitle = () => {
    if (project && editTitleVal.trim() && editTitleVal !== project.title) {
      updateProject(project.id, { title: editTitleVal });
    }
    setIsEditingTitle(false);
  };

  const handleAssetCaptionChange = (index: number, caption: string) => {
    if (!project) return;
    const updatedAssets = [...project.assets];
    updatedAssets[index] = { ...updatedAssets[index], caption };
    updateProject(project.id, { assets: updatedAssets });
  };

  if (!project) return (
    <div className={`flex-1 flex flex-col items-center justify-center p-10 text-center ${className}`}>
      <IconFile className="w-12 h-12 text-slate-200 mb-4" />
      <h2 className="text-lg font-semibold text-slate-900 mb-2">Portfolio Empty</h2>
      <p className="text-slate-500 max-w-xs text-sm">Create a project using the button below to start your design journey.</p>
    </div>
  );

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = project.steps ? Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100) : 0;
  const stepAssets = project.assets ? project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) : [];

  if (currentStepId === 'casestudy') {
    const previewHtml = generateFullHtml(project, true);
    const config = project.exportConfig || { theme: 'modern', primaryColor: '#3B82F6', fontFamily: 'Inter', showCover: true, showTOC: true, showAssets: true, designerName: '', designerRole: 'UX Designer', excludedSteps: [] };

    return (
      <main className={`flex-1 flex flex-col gap-4 min-w-0 h-full overflow-hidden ${className}`}>
        <div className="bg-white border-b border-slate-200 p-4 flex justify-between items-center shrink-0 pt-safe">
          <div className="flex items-center gap-3">
            <button onClick={() => onStepSelect(STAGES[STAGES.length - 2].id)} className="p-2 -ml-2 text-slate-400 active:scale-95 transition-transform"><IconArrowRight className="w-5 h-5 rotate-180" /></button>
            <h1 className="text-lg font-black text-slate-900 leading-none">Export Studio</h1>
          </div>
          <Button onClick={() => onExport(project)} size="sm" className="bg-blue-600 rounded-full px-5 shadow-glow active:scale-95">
            <IconDownload className="w-4 h-4 mr-2" /> Download
          </Button>
        </div>

        <div className="flex-1 flex flex-col lg:grid lg:grid-cols-12 gap-0 lg:gap-6 overflow-hidden">
          <div className="lg:col-span-4 bg-white border-b lg:border lg:border-slate-200 lg:rounded-3xl p-6 shadow-sm flex flex-col gap-8 overflow-y-auto max-h-[40vh] lg:max-h-full">
             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4">Designer Branding</h3>
                <div className="space-y-4">
                   <div className="relative group">
                      <input type="text" placeholder="Full Name" className="w-full text-base md:text-sm font-bold p-3 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500" value={config.designerName} onChange={e => updateExportConfig({ designerName: e.target.value })} />
                   </div>
                   <div className="relative group">
                      <input type="text" placeholder="Your Professional Title" className="w-full text-base md:text-sm p-3 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500" value={config.designerRole} onChange={e => updateExportConfig({ designerRole: e.target.value })} />
                   </div>
                </div>
             </section>

             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4">Style Engine</h3>
                <div className="flex gap-2 mb-4">
                   {['modern', 'classic', 'minimal'].map(t => (
                     <button key={t} onClick={() => updateExportConfig({ theme: t as any })} className={`flex-1 p-3 text-[10px] font-black rounded-2xl border transition-all uppercase tracking-tighter active:scale-95 ${config.theme === t ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>{t}</button>
                   ))}
                </div>
                <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                   <span className="text-xs font-bold text-slate-600">Theme Color</span>
                   <input type="color" className="w-8 h-8 rounded-xl cursor-pointer bg-transparent border-0" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                </div>
             </section>

             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4">Section Toggles</h3>
                <div className="grid grid-cols-1 gap-2">
                   {[
                     { label: 'Dynamic Cover Page', key: 'showCover' },
                     { label: 'Interactive Table of Contents', key: 'showTOC' },
                     { label: 'Full Asset Gallery', key: 'showAssets' }
                   ].map(opt => (
                     <label key={opt.key} className="flex items-center justify-between p-4 bg-slate-50 hover:bg-white border border-slate-100 rounded-2xl cursor-pointer transition-colors active:scale-95">
                        <span className="text-xs font-bold text-slate-600">{opt.label}</span>
                        <div className={`w-10 h-6 rounded-full p-1 transition-colors ${config[opt.key as keyof ExportConfig] ? 'bg-blue-600' : 'bg-slate-200'}`}>
                           <div className={`bg-white w-4 h-4 rounded-full transition-transform ${config[opt.key as keyof ExportConfig] ? 'translate-x-4' : ''}`} />
                        </div>
                        <input type="checkbox" className="hidden" checked={config[opt.key as keyof ExportConfig] as boolean} onChange={e => updateExportConfig({ [opt.key]: e.target.checked })} />
                     </label>
                   ))}
                </div>
             </section>
          </div>

          <div className="lg:col-span-8 bg-slate-100 flex-1 flex flex-col p-4 lg:p-8 overflow-hidden relative">
             <div className="w-full h-full bg-white shadow-2xl rounded-3xl overflow-hidden border border-slate-200">
                <iframe srcDoc={previewHtml} className="w-full h-full border-0" sandbox="allow-same-origin" />
             </div>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${className}`} role="main">
      <div className="bg-white border-b border-slate-200 p-4 md:p-6 shadow-sm flex flex-col gap-3 shrink-0 pt-safe">
        <div className="flex justify-between items-center">
          <div className="min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <span className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Phase {currentStepIndex + 1}</span>
              {isStepComplete && <span className="bg-emerald-100 text-emerald-700 text-[9px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter flex items-center gap-1"><IconCheck className="w-2.5 h-2.5" /> Verified</span>}
            </div>
            <h1 className="text-lg md:text-2xl font-black text-slate-900 truncate leading-tight tracking-tight">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setIsPreviewMode(!isPreviewMode)} className={`p-2 rounded-xl border transition-all active:scale-90 ${isPreviewMode ? 'bg-blue-600 text-white border-blue-600 shadow-glow' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>
                <IconEye className="w-5 h-5" />
             </button>
             <ProgressRing progress={progress} radius={22} stroke={3} className="text-blue-600" />
          </div>
        </div>

        <div className="md:hidden flex bg-slate-100 p-1 rounded-2xl">
          <button 
            onClick={() => setActiveMobileTab('strategy')} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all active:scale-95 ${activeMobileTab === 'strategy' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
          >
            <IconFile className="w-4 h-4" /> Strategy
          </button>
          <button 
            onClick={() => setActiveMobileTab('evidence')} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all active:scale-95 ${activeMobileTab === 'evidence' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
          >
            <IconLayout className="w-4 h-4" /> Proof <span className="bg-slate-200 text-slate-500 w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold">{stepAssets.length}</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col md:grid md:grid-cols-2 gap-0 md:gap-6 overflow-hidden">
        <div className={`flex flex-col min-h-0 flex-1 h-full bg-white md:bg-transparent transition-all duration-300 ${activeMobileTab === 'strategy' ? 'translate-x-0' : '-translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-3xl shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex items-center justify-between px-6 py-4 border-b border-slate-50 bg-slate-50/20">
               <button onClick={() => setIsGuideOpen(true)} className="bg-blue-600 text-white rounded-full px-5 py-2 text-[10px] font-black uppercase tracking-widest flex items-center shadow-glow active:scale-95 transition-all">
                  <IconLayout className="w-4 h-4 mr-2" /> Designer toolkit
               </button>
               <div className={`text-[10px] font-black uppercase tracking-tighter ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                   {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Saved' : ''}
               </div>
            </div>

            <div className="flex-1 relative overflow-hidden">
              {isPreviewMode ? (
                <div className="absolute inset-0 p-6 md:p-10 overflow-y-auto prose prose-slate max-w-none bg-white font-sans selection:bg-blue-100">
                  <div className="text-slate-800 leading-[1.8]" dangerouslySetInnerHTML={{ __html: parseMarkdown(notes) }} />
                  {notes.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-300 italic"><IconFile className="w-12 h-12 mb-4 opacity-10" /> Document your phase Strategy here.</div>}
                </div>
              ) : (
                <textarea
                  value={notes}
                  onChange={handleNotesChange}
                  onBlur={handleSave} 
                  placeholder={`Phase Guide: ${currentStage.help}\n\nStart writing your design rationale. Use headers like "Goal" or "Success Metrics"...`}
                  className="w-full h-full bg-white p-6 md:p-10 resize-none focus:outline-none text-slate-800 leading-relaxed text-base md:text-lg font-sans placeholder:text-slate-300"
                />
              )}
            </div>
          </div>
        </div>

        <div className={`flex flex-col flex-1 min-h-0 h-full bg-slate-50 md:bg-transparent transition-all duration-300 ${activeMobileTab === 'evidence' ? 'translate-x-0' : 'translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-3xl shadow-soft flex-1 flex flex-col overflow-hidden">
            <div className="flex items-center justify-between px-6 py-4 border-b border-slate-50 bg-slate-50/20">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Evidence Vault</h3>
               <label className="cursor-pointer active:scale-95 transition-transform">
                  <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                  <div className="px-5 py-2 bg-slate-900 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center">
                    <IconPlus className="w-4 h-4 mr-2" /> Upload Proof
                  </div>
               </label>
            </div>

            <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50/40">
              {stepAssets.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-10">
                   <div className="w-24 h-24 rounded-3xl bg-white border border-slate-100 shadow-sm flex items-center justify-center mb-6">
                     <IconFile className="w-10 h-10 text-slate-200" />
                   </div>
                   <h4 className="text-slate-900 font-black mb-2 uppercase tracking-tight">No Artifacts Yet</h4>
                   <p className="text-xs text-slate-500 max-w-[200px] leading-relaxed">Proof of work is essential for a professional case study.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-6">
                  {[...stepAssets].reverse().map((asset, i) => {
                    const originalIdx = project.assets.indexOf(asset);
                    return (
                      <div key={i} className="bg-white border border-slate-200 rounded-3xl p-4 shadow-sm group animate-in slide-in-from-bottom-4 duration-300">
                        <div className="relative aspect-video bg-slate-50 rounded-2xl overflow-hidden mb-4 border border-slate-100">
                          <img src={asset.url || asset.dataURL} className="w-full h-full object-contain" alt={asset.name} />
                          <div className="absolute top-3 right-3 flex gap-2">
                             <button onClick={() => window.open(asset.url || asset.dataURL, '_blank')} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-slate-900 active:scale-90"><IconEye className="w-4 h-4" /></button>
                             <button onClick={() => deleteAsset(originalIdx)} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-red-500 active:scale-90"><IconTrash className="w-4 h-4" /></button>
                          </div>
                        </div>
                        <div className="px-2 space-y-4">
                          <div className="flex justify-between items-center">
                            <h5 className="text-xs font-black text-slate-900 truncate uppercase tracking-tight">{asset.name}</h5>
                            <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">{new Date(asset.createdAt).toLocaleDateString()}</span>
                          </div>
                          <textarea 
                            placeholder="Add a meaningful description..." 
                            className="w-full text-base md:text-xs p-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500 transition-all resize-none h-24 text-slate-600 leading-relaxed"
                            value={asset.caption || ''}
                            onChange={(e) => handleAssetCaptionChange(originalIdx, e.target.value)}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="sticky bottom-0 md:static bg-white p-4 md:p-6 flex justify-between items-center z-40 pb-safe shadow-sheet">
         <button onClick={() => prevStep && onStepSelect(prevStep.id)} className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-slate-400 p-3 active:scale-95 ${!prevStep && 'invisible'}`}>
           <IconArrowRight className="w-4 h-4 rotate-180" /> Back
         </button>

         <div className="flex gap-4">
            <button 
                onClick={toggleStepCompletion} 
                className={`w-14 h-14 rounded-full flex items-center justify-center transition-all active:scale-90 border-4 ${isStepComplete ? 'bg-emerald-500 border-emerald-100 text-white shadow-lg shadow-emerald-500/20' : 'bg-white border-slate-100 text-slate-300'}`}
            >
                <IconCheck className="w-7 h-7" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} className="bg-blue-600 px-10 rounded-full shadow-fab font-black tracking-[0.1em] uppercase text-xs h-14 active:scale-95">
                {nextStep ? 'Next Phase' : 'Finalize'} <IconArrowRight className="w-4 h-4 ml-2" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Replace Image', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete Asset', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />

      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
      <GuideModal isOpen={isGuideOpen} onClose={() => setIsGuideOpen(false)} onInsert={handleInsert} currentStepId={currentStepId} />
    </main>
  );
};

import { Project, Asset, ExportConfig } from "../types";
