import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, AppState } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
import { IconPlus, IconCheck, IconTrash, IconCopy, IconChevronDown, IconSearch, IconArrowRight, IconClose, IconFile, IconLayout } from './ui/Icons';

interface SidebarProps {
  state: AppState;
  onOpenCreateModal: () => void;
  switchProject: (id: string) => void;
  deleteProject: (id: string) => void;
  duplicateProject: (id: string) => void;
  onExport: (project: Project) => void;
  activeProject: Project | null;
  onStepSelect: (stepId: string) => void;
  currentStepId: string;
  className?: string;
  mobileOpen?: boolean;
  onCloseMobile?: () => void;
}

const PROJECT_ROW_HEIGHT = 80;

export const Sidebar: React.FC<SidebarProps> = ({
  state,
  onOpenCreateModal,
  switchProject,
  deleteProject,
  duplicateProject,
  activeProject,
  onStepSelect,
  currentStepId,
  className = '',
  mobileOpen = false,
  onCloseMobile
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const listRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(400);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setScrollTop(0);
    }, 200);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  useEffect(() => {
    if (listRef.current) {
      setViewportHeight(listRef.current.clientHeight);
      const ro = new ResizeObserver(() => setViewportHeight(listRef.current?.clientHeight || 400));
      ro.observe(listRef.current);
      return () => ro.disconnect();
    }
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => setScrollTop(e.currentTarget.scrollTop);

  const filteredProjects = useMemo(() => {
    const all = Object.values(state.projects) as Project[];
    const sorted = all.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    if (!debouncedSearch.trim()) return sorted;
    const lower = debouncedSearch.toLowerCase();
    return sorted.filter(p => p.title.toLowerCase().includes(lower));
  }, [state.projects, debouncedSearch]);

  const totalCount = filteredProjects.length;
  const startIndex = Math.max(0, Math.floor(scrollTop / PROJECT_ROW_HEIGHT) - 1);
  const endIndex = Math.min(totalCount, Math.ceil((scrollTop + viewportHeight) / PROJECT_ROW_HEIGHT) + 1);
  const visibleProjects = filteredProjects.slice(startIndex, endIndex);

  return (
    <aside 
      className={`
        fixed inset-0 z-[100] bg-white flex flex-col transition-transform duration-500 ease-in-out md:relative md:translate-y-0 md:inset-auto md:z-0 md:bg-transparent md:w-80 lg:w-96 md:gap-6
        ${mobileOpen ? 'translate-y-0' : 'translate-y-full md:translate-y-0'}
        ${className}
      `}
      role="complementary"
    >
        {/* Mobile Header Dashboard Style */}
        <div className="md:hidden pt-safe shrink-0 bg-slate-900 text-white p-6 rounded-b-[3rem] shadow-2xl">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h2 className="text-2xl font-black tracking-tight">Process Map</h2>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Milestones & Flow</p>
            </div>
            <button onClick={onCloseMobile} className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center active:scale-90 transition-transform">
              <IconClose className="w-6 h-6 text-white" />
            </button>
          </div>

          <div className="flex gap-4 mb-2 overflow-x-auto hide-scrollbar">
             <div className="bg-white/5 border border-white/10 rounded-3xl p-4 min-w-[140px]">
                <div className="text-[10px] font-black text-slate-500 uppercase">Step Success</div>
                <div className="text-xl font-black mt-1 text-emerald-400">
                  {activeProject ? STAGES.filter(s => activeProject.steps?.[s.id]?.isComplete).length : 0} / 12
                </div>
             </div>
             <div className="bg-white/5 border border-white/10 rounded-3xl p-4 min-w-[140px]">
                <div className="text-[10px] font-black text-slate-500 uppercase">Current Phase</div>
                <div className="text-xl font-black mt-1 text-blue-400">
                  {STAGES.findIndex(s => s.id === currentStepId) + 1}
                </div>
             </div>
          </div>
        </div>

        {/* Project Selector */}
        <div className="md:bg-white md:border md:border-slate-200 md:rounded-3xl p-4 md:shadow-soft flex flex-col h-[20vh] md:h-auto md:max-h-[35vh] overflow-hidden">
          <div className="flex items-center justify-between mb-3 px-2">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Workspace</h3>
            <Button size="sm" variant="ghost" onClick={onOpenCreateModal} className="h-8 px-3 text-blue-600 font-black">
              <IconPlus className="w-3.5 h-3.5 mr-1" /> Add
            </Button>
          </div>

          <div ref={listRef} onScroll={handleScroll} className="flex-1 overflow-y-auto pr-1 space-y-2 px-2">
            {totalCount === 0 ? (
              <div className="text-center py-6 text-slate-400 text-xs italic">No projects active</div>
            ) : (
              <div style={{ paddingTop: `${startIndex * PROJECT_ROW_HEIGHT}px`, paddingBottom: `${(totalCount - endIndex) * PROJECT_ROW_HEIGHT}px` }}>
                {visibleProjects.map(p => {
                  const isActive = activeProject?.id === p.id;
                  const completedCount = STAGES.filter(s => p.steps?.[s.id]?.isComplete).length;
                  return (
                    <div key={p.id} style={{ height: `${PROJECT_ROW_HEIGHT}px` }} className="pb-2">
                      <div 
                        className={`p-4 h-full rounded-2xl transition-all cursor-pointer border flex justify-between items-center ${isActive ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`} 
                        onClick={() => { switchProject(p.id); }}
                      >
                        <div className="min-w-0 pr-4">
                          <div className={`text-sm font-black truncate ${isActive ? 'text-white' : 'text-slate-900'}`}>{p.title}</div>
                          <div className={`text-[10px] font-bold mt-0.5 ${isActive ? 'text-blue-100' : 'text-slate-400'}`}>{completedCount}/{STAGES.length} Complete</div>
                        </div>
                        <div className="flex gap-2 shrink-0">
                          <button className={`p-2 rounded-xl transition-colors ${isActive ? 'bg-white/10 hover:bg-white/20' : 'text-slate-400 hover:bg-slate-200'}`} onClick={(e) => { e.stopPropagation(); duplicateProject(p.id); }}><IconCopy className="w-4 h-4" /></button>
                          <button className={`p-2 rounded-xl transition-colors ${isActive ? 'bg-white/10 hover:bg-red-400/30 text-white' : 'text-slate-400 hover:text-red-500 hover:bg-red-50'}`} onClick={(e) => { e.stopPropagation(); deleteProject(p.id); }}><IconTrash className="w-4 h-4" /></button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Process Steps / Process Map */}
        <div className="flex-1 bg-white md:border md:border-slate-200 md:rounded-3xl p-6 md:shadow-soft flex flex-col overflow-hidden mb-20 md:mb-0">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Process Flow</h3>
            <div className="flex bg-slate-100 p-0.5 rounded-lg">
               <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}><IconFile className="w-3.5 h-3.5" /></button>
               <button onClick={() => setViewMode('map')} className={`p-1.5 rounded-md transition-all ${viewMode === 'map' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}><IconLayout className="w-3.5 h-3.5" /></button>
            </div>
          </div>

          <div className="overflow-y-auto flex-1 pr-2 pb-20">
            {activeProject ? (
              viewMode === 'list' ? (
                <div className="space-y-3">
                  {STAGES.map((stage, idx) => {
                    const isDone = activeProject.steps?.[stage.id]?.isComplete;
                    const isActive = currentStepId === stage.id;
                    return (
                      <button 
                        key={stage.id} 
                        onClick={() => { onStepSelect(stage.id); }} 
                        className={`w-full text-left rounded-2xl transition-all border flex items-center gap-4 p-4 active:scale-[0.97] ${isActive ? 'bg-blue-50 border-blue-200 shadow-md ring-4 ring-blue-50/50' : 'bg-white border-slate-100 hover:border-slate-300'}`}
                      >
                          <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-xs font-black border-2 shrink-0 transition-all ${isActive ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : isDone ? 'bg-emerald-500 border-emerald-500 text-white shadow-md' : 'bg-slate-50 border-slate-200 text-slate-300'}`}>
                            {isDone && !isActive ? <IconCheck className="w-5 h-5" /> : (idx + 1)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className={`text-sm font-black tracking-tight ${isActive ? 'text-blue-900' : isDone ? 'text-emerald-900' : 'text-slate-600'}`}>{stage.label.split('. ')[1]}</div>
                          </div>
                          {isActive && <IconArrowRight className="w-5 h-5 text-blue-300" />}
                      </button>
                    );
                  })}
                </div>
              ) : (
                <div className="grid grid-cols-3 gap-3">
                  {STAGES.map((stage, idx) => {
                    const isDone = activeProject.steps?.[stage.id]?.isComplete;
                    const isActive = currentStepId === stage.id;
                    return (
                      <button 
                        key={stage.id} 
                        onClick={() => { onStepSelect(stage.id); }} 
                        title={stage.label}
                        className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-all active:scale-90 ${isActive ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : isDone ? 'bg-emerald-50 text-emerald-100 border-emerald-200' : 'bg-slate-50 border-slate-100'}`}
                      >
                        <span className="text-xl mb-1">{stage.icon || '📦'}</span>
                        <span className={`text-[10px] font-black ${isActive ? 'text-white' : isDone ? 'text-emerald-600' : 'text-slate-400'}`}>{idx + 1}</span>
                        {isDone && !isActive && <div className="absolute top-1 right-1 w-2 h-2 bg-emerald-500 rounded-full" />}
                      </button>
                    );
                  })}
                </div>
              )
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4 opacity-50">
                 <IconFile className="w-12 h-12" />
                 <span className="text-xs font-bold uppercase tracking-widest">Select Project</span>
              </div>
            )}
          </div>
        </div>
    </aside>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion, ExportConfig, Asset } from '../types';
import { STAGES, TEMPLATES } from '../constants';
import { Button } from './ui/Button';
import { IconDownload, IconTrash, IconFile, IconReplace, IconCheck, IconArrowRight, IconLayout, IconPlus, IconEye } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
import { ContextMenu } from './ui/ContextMenu';
import { HistoryModal } from './HistoryModal';
import { GuideModal } from './GuideModal';
import { generateFullHtml } from '../utils/exporter';
import { parseMarkdown } from '../utils/pdfTemplate';

interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  isGuideOpen: boolean;
  setIsGuideOpen: (open: boolean) => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  isGuideOpen,
  setIsGuideOpen,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [activeMobileTab, setActiveMobileTab] = useState<'strategy' | 'evidence'>('strategy');
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [showCelebration, setShowCelebration] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  // Contextual templates for the quick bar
  const phaseTemplates = TEMPLATES.filter(t => t.category === currentStage.templateCategory || t.key === currentStage.id);

  useEffect(() => {
    if (project && project.steps) {
      const stepData = project.steps[currentStepId] || { notes: '', isComplete: false };
      let externalNotes = stepData.notes;
      if (currentStepId === 'problem' && !externalNotes && project.notes) {
        externalNotes = project.notes;
      }
      if (externalNotes !== notesRef.current) {
        setNotes(externalNotes);
        notesRef.current = externalNotes;
      }
    }
  }, [project?.id, currentStepId, project?.steps?.[currentStepId]?.notes]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project || !project.steps) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps[currentStepId]?.isComplete || false;
    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project || !project.steps) return;
    const isCurrentlyComplete = project.steps[currentStepId]?.isComplete || false;
    const nextCompleteState = !isCurrentlyComplete;

    if (nextCompleteState) {
      setShowCelebration(true);
      setTimeout(() => setShowCelebration(false), 3000);
    }

    updateStepData(currentStepId, { notes, isComplete: nextCompleteState });
  };

  const handleInsert = (content: string) => {
    const newNotes = notes.trim() ? notes + "\n\n" + content : content;
    setNotes(newNotes);
    notesRef.current = newNotes;
    setSaveStatus('modified');
    handleSave();
  };

  const updateExportConfig = (updates: Partial<ExportConfig>) => {
    if (!project) return;
    const current = project.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: []
    };
    updateProject(project.id, { exportConfig: { ...current, ...updates } });
  };

  const handleAssetCaptionChange = (index: number, caption: string) => {
    if (!project) return;
    const updatedAssets = [...project.assets];
    updatedAssets[index] = { ...updatedAssets[index], caption };
    updateProject(project.id, { assets: updatedAssets });
  };

  if (!project) return (
    <div className={`flex-1 flex flex-col items-center justify-center p-10 text-center ${className}`}>
      <IconFile className="w-12 h-12 text-slate-200 mb-4" />
      <h2 className="text-lg font-semibold text-slate-900 mb-2">Portfolio Empty</h2>
      <p className="text-slate-500 max-w-xs text-sm">Create a project using the button below to start your design journey.</p>
    </div>
  );

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = project.steps ? Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100) : 0;
  const stepAssets = project.assets ? project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) : [];

  if (currentStepId === 'casestudy') {
    const previewHtml = generateFullHtml(project, true);
    const config = project.exportConfig || { theme: 'modern', primaryColor: '#3B82F6', fontFamily: 'Inter', showCover: true, showTOC: true, showAssets: true, designerName: '', designerRole: 'UX Designer', excludedSteps: [] };

