             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4">Style Engine</h3>
                <div className="flex gap-2 mb-4">
                   {['modern', 'classic', 'minimal'].map(t => (
