                      <div key={i} className="bg-white border border-slate-200 rounded-3xl p-4 shadow-sm group animate-in slide-in-from-bottom-4 duration-300">
                        <div className="relative aspect-video bg-slate-50 rounded-2xl overflow-hidden mb-4 border border-slate-100">
                          <img src={asset.url || asset.dataURL} className="w-full h-full object-contain" alt={asset.name} />
                          <div className="absolute top-3 right-3 flex gap-2">
                             <button onClick={() => window.open(asset.url || asset.dataURL, '_blank')} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-slate-900 active:scale-90"><IconEye className="w-4 h-4" /></button>
                             <button onClick={() => deleteAsset(originalIdx)} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-red-500 active:scale-90"><IconTrash className="w-4 h-4" /></button>
