function escapeHtml(s: string) {
  return (s || '').toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

export function parseMarkdown(text: string): string {
  if (!text) return '';
  let html = escapeHtml(text);
  html = html.replace(/^### (.*$)/gim, '<h3 style="margin-top: 24px; margin-bottom: 8px; font-weight: 800; color: #0f172a; font-size: 18px;">$1</h3>');
  html = html.replace(/^## (.*$)/gim, '<h2 style="margin-top: 32px; margin-bottom: 12px; font-weight: 800; color: #0f172a; font-size: 22px; border-bottom: 1px solid #eee; padding-bottom: 8px;">$1</h2>');
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #111827; font-weight: 700;">$1</strong>');
  const lines = html.split('\n');
  let inList = false;
  const processedLines = lines.map(line => {
    const listMatch = line.match(/^[-*] (.*)/);
    if (listMatch) {
      const content = listMatch[1];
      if (!inList) {
        inList = true;
        return `<ul style="margin-bottom: 16px; padding-left: 20px; list-style-type: disc;"><li style="margin-bottom: 4px;">${content}</li>`;
      }
      return `<li style="margin-bottom: 4px;">${content}</li>`;
    } else {
      if (inList) {
        inList = false;
        return `</ul>${line}<br>`;
      }
      return line + '<br>';
    }
  });
  html = processedLines.join('');
  return html;
}

function getAssetHtml(assets: Asset[], showAssets: boolean) {
  if (!showAssets || !assets || assets.length === 0) return '';
  return `
    <div class="assets-grid">
      ${assets.map(a => {
         const displayUrl = a.url || a.dataURL;
         if (!a.type.startsWith('image') || !displayUrl) return '';
         return `
           <div class="asset-item">
             <div class="asset-image-container">
               <img src="${displayUrl}" alt="${escapeHtml(a.name)}" />
             </div>
             ${a.caption ? `<div class="asset-caption">${escapeHtml(a.caption)}</div>` : ''}
           </div>
         `;
      }).join('')}
    </div>
  `;
}

export function generateCaseStudyHtml(project: Project): string {
  const config: ExportConfig = project.exportConfig || {
    theme: 'modern',
    primaryColor: '#3B82F6',
    fontFamily: 'Inter',
    showCover: true,
    showTOC: true,
    showAssets: true,
    designerName: '',
    designerRole: 'UX Designer',
    excludedSteps: []
  };

  // Build the sequence of sections based on user preferences
  const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
  const customSections = config.customSections || [];

  const sectionsHtml = order.map((id, index) => {
    // Is it a standard stage?
    const stage = STAGES.find(s => s.id === id);
    if (stage) {
      if (config.excludedSteps.includes(id)) return '';
      const stepData = project.steps?.[id] || { notes: '', isComplete: false };
      const rawContent = config.customOverrides?.[id] || stepData.notes || (id === 'problem' ? project.notes : '');
      const stepAssets = project.assets.filter(a => (a.stepId === id) || (id === 'problem' && !a.stepId));
      if (!rawContent && stepAssets.length === 0) return '';
      return `
        <section class="step-section" id="section-${id}">
          <div class="step-header">
            <span class="step-num" style="background: ${config.primaryColor};">${index + 1}</span>
            <h2 class="step-title">${escapeHtml(stage.label.replace(/^\d+\.\s/, ''))}</h2>
          </div>
          <div class="step-content">
            ${rawContent ? `<div class="step-notes">${parseMarkdown(rawContent)}</div>` : ''}
            ${getAssetHtml(stepAssets, config.showAssets)}
          </div>
        </section>
      `;
    }
    // Is it a custom section?
    const custom = customSections.find(cs => cs.id === id);
    if (custom) {
      return `
        <section class="step-section" id="section-${custom.id}">
          <div class="step-header">
            <span class="step-num" style="background: ${config.primaryColor};">${index + 1}</span>
            <h2 class="step-title">${escapeHtml(custom.title)}</h2>
          </div>
          <div class="step-content">
            <div class="step-notes">${parseMarkdown(custom.content)}</div>
          </div>
        </section>
      `;
    }
    return '';
  }).join('');

  const fontStack = config.fontFamily === 'Serif' ? 'Georgia, serif' : config.fontFamily === 'Mono' ? 'monospace' : "'Inter', sans-serif";

  return `
  <!DOCTYPE html>
  <html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${escapeHtml(project.title)}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');
      * { box-sizing: border-box; }
      body {
        font-family: ${fontStack};
        color: #1e293b;
        line-height: 1.6;
        margin: 0;
        background: ${config.theme === 'minimal' ? '#ffffff' : '#f8fafc'};
        -webkit-print-color-adjust: exact;
      }
      .document-wrapper {
        max-width: 1100px;
        margin: 0 auto;
        padding: 80px 40px;
        background: white;
      }
      .assets-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(400px, 1fr));
        gap: 32px;
        margin: 40px 0;
      }
      .asset-item {
        background: #ffffff;
        border: 1px solid #f1f5f9;
        border-radius: 24px;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        break-inside: avoid;
      }
      .asset-image-container {
        background: #f8fafc;
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: 300px;
      }
      .asset-item img {
        width: 100%;
        max-height: 600px;
        object-fit: contain;
      }
      .asset-caption {
        padding: 24px;
        font-size: 14px;
        color: #64748b;
        border-top: 1px solid #f1f5f9;
      }
      .step-section {
        margin-bottom: 120px;
        page-break-inside: avoid;
      }
      .step-header {
        display: flex;
        align-items: center;
        gap: 20px;
        margin-bottom: 32px;
      }
      .step-num {
        color: white;
        width: 44px;
        height: 44px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 14px;
        font-size: 18px;
        font-weight: 800;
      }
      .step-title {
        font-size: 38px;
        margin: 0;
        font-weight: 800;
        color: #0f172a;
      }
      .step-notes {
        font-size: 19px;
        color: #334155;
        line-height: 1.8;
      }
      .cover {
        min-height: 75vh;
        display: ${config.showCover ? 'flex' : 'none'};
        flex-direction: column;
        justify-content: center;
        border-left: 20px solid ${config.primaryColor};
        padding-left: 64px;
        margin-bottom: 140px;
      }
      .cover h1 {
        font-size: 84px;
        margin: 0;
        font-weight: 900;
        line-height: 1.05;
      }
      .cover p {
        font-size: 28px;
        color: #64748b;
        margin-top: 24px;
        max-width: 760px;
      }
      .designer-info { margin-top: 80px; }
      .designer-name { font-size: 26px; font-weight: 800; }
      .designer-role { font-size: 15px; font-weight: 700; color: ${config.primaryColor}; text-transform: uppercase; letter-spacing: 0.25em; margin-top: 8px; }
      @media print {
        .document-wrapper { padding: 0; max-width: 100%; }
        .cover { min-height: 90vh; }
      }
    </style>
  </head>
  <body>
    <div class="document-wrapper">
      <div class="cover">
        <div style="font-size: 14px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.4em; color: ${config.primaryColor}; margin-bottom: 24px;">UX Case Study Portfolio</div>
        <h1>${escapeHtml(project.title)}</h1>
        <p>${escapeHtml(project.desc)}</p>
        <div class="designer-info">
          <div class="designer-name">${escapeHtml(config.designerName || 'UX Designer')}</div>
          <div class="designer-role">${escapeHtml(config.designerRole || 'Lead Researcher')}</div>
        </div>
      </div>
      <div class="content">
        ${sectionsHtml}
      </div>
    </div>
  </body>
  </html>
  `;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion, ExportConfig, Asset, CustomSection } from '../types';
import { STAGES, TEMPLATES } from '../constants';
import { Button } from './ui/Button';
import { IconDownload, IconTrash, IconFile, IconReplace, IconCheck, IconArrowRight, IconLayout, IconPlus, IconEye, IconEdit, IconChevronDown } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
import { ContextMenu } from './ui/ContextMenu';
import { HistoryModal } from './HistoryModal';
import { GuideModal } from './GuideModal';
import { generateFullHtml } from '../utils/exporter';
import { parseMarkdown } from '../utils/pdfTemplate';

interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  isGuideOpen: boolean;
  setIsGuideOpen: (open: boolean) => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  isGuideOpen,
  setIsGuideOpen,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [activeMobileTab, setActiveMobileTab] = useState<'strategy' | 'evidence'>('strategy');
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [showCelebration, setShowCelebration] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [exportEditMode, setExportEditMode] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  const phaseTemplates = TEMPLATES.filter(t => t.category === currentStage.templateCategory || t.key === currentStage.id);

  useEffect(() => {
    if (project && project.steps) {
      const stepData = project.steps[currentStepId] || { notes: '', isComplete: false };
      let externalNotes = stepData.notes;
      if (currentStepId === 'problem' && !externalNotes && project.notes) {
        externalNotes = project.notes;
      }
      if (externalNotes !== notesRef.current) {
        setNotes(externalNotes);
        notesRef.current = externalNotes;
      }
    }
  }, [project?.id, currentStepId, project?.steps?.[currentStepId]?.notes]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project || !project.steps) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps[currentStepId]?.isComplete || false;
    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project || !project.steps) return;
    const isCurrentlyComplete = project.steps[currentStepId]?.isComplete || false;
    const nextCompleteState = !isCurrentlyComplete;
    if (nextCompleteState) {
      setShowCelebration(true);
      setTimeout(() => setShowCelebration(false), 3000);
    }
    updateStepData(currentStepId, { notes, isComplete: nextCompleteState });
  };

  const handleInsert = (content: string) => {
    const newNotes = notes.trim() ? notes + "\n\n" + content : content;
    setNotes(newNotes);
    notesRef.current = newNotes;
    setSaveStatus('modified');
    handleSave();
  };

  const updateExportConfig = (updates: Partial<ExportConfig>) => {
    if (!project) return;
    const current = project.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: [],
      sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id),
      customSections: []
    };
    updateProject(project.id, { exportConfig: { ...current, ...updates } });
  };

  const toggleSectionExcluded = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.excludedSteps || [];
    const next = current.includes(id) ? current.filter(x => x !== id) : [...current, id];
    updateExportConfig({ excludedSteps: next });
  };

  const moveSection = (id: string, direction: 'up' | 'down') => {
    if (!project) return;
    const order = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    const index = order.indexOf(id);
    if (index === -1) return;
    const newOrder = [...order];
    if (direction === 'up' && index > 0) {
      [newOrder[index], newOrder[index - 1]] = [newOrder[index - 1], newOrder[index]];
    } else if (direction === 'down' && index < newOrder.length - 1) {
      [newOrder[index], newOrder[index + 1]] = [newOrder[index + 1], newOrder[index]];
    }
    updateExportConfig({ sectionOrder: newOrder });
  };

  const updateOverride = (id: string, content: string) => {
    if (!project) return;
    const currentOverrides = project.exportConfig?.customOverrides || {};
    updateExportConfig({ customOverrides: { ...currentOverrides, [id]: content } });
  };

  const addCustomSection = () => {
    if (!project) return;
    const id = 'custom_' + Date.now();
    const newSection: CustomSection = { id, title: 'New Custom Section', content: '', showAssets: false };
    const currentSections = project.exportConfig?.customSections || [];
    const currentOrder = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    updateExportConfig({ 
      customSections: [...currentSections, newSection],
      sectionOrder: [...currentOrder, id]
    });
  };

  const updateCustomSection = (id: string, updates: Partial<CustomSection>) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const next = current.map(s => s.id === id ? { ...s, ...updates } : s);
    updateExportConfig({ customSections: next });
  };

  const removeCustomSection = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const nextSections = current.filter(s => s.id !== id);
    const currentOrder = project.exportConfig?.sectionOrder || [];
    const nextOrder = currentOrder.filter(oid => oid !== id);
    updateExportConfig({ customSections: nextSections, sectionOrder: nextOrder });
  };

  const handleAssetCaptionChange = (index: number, caption: string) => {
    if (!project) return;
    const updatedAssets = [...project.assets];
    updatedAssets[index] = { ...updatedAssets[index], caption };
    updateProject(project.id, { assets: updatedAssets });
  };

  if (!project) return null;

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = project.steps ? Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100) : 0;
  const stepAssets = project.assets ? project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) : [];

  if (currentStepId === 'casestudy') {
    const config = project.exportConfig || { theme: 'modern', primaryColor: '#3B82F6', fontFamily: 'Inter', showCover: true, showTOC: true, showAssets: true, designerName: '', designerRole: 'UX Designer', excludedSteps: [], sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id), customSections: [] };
    const previewHtml = generateFullHtml(project, true);
    const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);

    return (
      <main className={`flex-1 flex flex-col gap-4 min-w-0 h-full overflow-hidden ${className}`}>
        <div className="bg-white border-b border-slate-200 p-4 flex justify-between items-center shrink-0 pt-safe">
          <div className="flex items-center gap-3">
            <button onClick={() => onStepSelect(STAGES[STAGES.length - 2].id)} className="p-2 -ml-2 text-slate-400 active:scale-95 transition-transform"><IconArrowRight className="w-5 h-5 rotate-180" /></button>
            <h1 className="text-lg font-black text-slate-900 leading-none">Export Studio & Page Builder</h1>
          </div>
          <div className="flex gap-2">
            <Button onClick={() => setExportEditMode(!exportEditMode)} variant={exportEditMode ? "primary" : "outline"} size="sm" className="rounded-full px-4">
              <IconEdit className="w-4 h-4 mr-2" /> {exportEditMode ? "View Document" : "Build Content"}
            </Button>
            <Button onClick={() => onExport(project)} size="sm" className="bg-blue-600 rounded-full px-5 shadow-glow active:scale-95">
              <IconDownload className="w-4 h-4 mr-2" /> Download Case Study
            </Button>
          </div>
        </div>

        <div className="flex-1 flex flex-col lg:grid lg:grid-cols-12 gap-0 lg:gap-6 overflow-hidden">
          {/* Controls Sidebar */}
          <div className="lg:col-span-4 bg-white border-b lg:border lg:border-slate-200 lg:rounded-3xl p-6 shadow-sm flex flex-col gap-8 overflow-y-auto max-h-[30vh] lg:max-h-full">
             <section>
                <div className="flex items-center justify-between mb-4">
                   <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Section Management</h3>
                   <Button size="sm" variant="ghost" onClick={addCustomSection} className="h-6 text-[10px] text-blue-600 font-black">+ Custom</Button>
                </div>
                <div className="space-y-2">
                   {order.map((oid, idx) => {
                     const stage = STAGES.find(s => s.id === oid);
                     const custom = config.customSections?.find(cs => cs.id === oid);
                     const isExcluded = config.excludedSteps.includes(oid);
                     if (!stage && !custom) return null;
                     return (
                       <div key={oid} className={`group relative flex items-center justify-between p-3 rounded-2xl border transition-all ${isExcluded ? 'bg-slate-50 text-slate-300 border-slate-100' : 'bg-white border-slate-200 text-slate-900 shadow-sm'}`}>
                          <div className="flex items-center gap-3 truncate">
                             <div className="flex flex-col gap-1">
                                <button onClick={() => moveSection(oid, 'up')} className="p-0.5 hover:text-blue-500"><IconChevronDown className="w-3 h-3 rotate-180" /></button>
                                <button onClick={() => moveSection(oid, 'down')} className="p-0.5 hover:text-blue-500"><IconChevronDown className="w-3 h-3" /></button>
                             </div>
                             <span className="text-lg">{stage?.icon || '📦'}</span>
                             <span className="text-xs font-bold truncate">{stage?.label.split('. ')[1] || custom?.title}</span>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                             {custom && <button onClick={() => removeCustomSection(oid)} className="p-2 text-red-400 hover:bg-red-50 rounded-xl"><IconTrash className="w-3.5 h-3.5" /></button>}
                             <button onClick={() => toggleSectionExcluded(oid)} className={`p-2 rounded-xl ${isExcluded ? 'text-emerald-500' : 'text-slate-300 hover:text-red-400'}`}>
                                {isExcluded ? <IconPlus className="w-3.5 h-3.5" /> : <IconClose className="w-3.5 h-3.5" />}
                             </button>
                          </div>
                       </div>
                     );
                   })}
                </div>
             </section>

             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4">Branding & Layout</h3>
                <div className="space-y-4">
                   <div className="flex flex-col gap-1">
                      <label className="text-[9px] font-black text-slate-400 uppercase ml-1">Primary Color</label>
                      <div className="flex gap-3 items-center">
                         <input type="color" className="w-10 h-10 rounded-xl cursor-pointer bg-transparent border-0" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                         <input type="text" className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-3 py-2 text-xs font-mono uppercase" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                      </div>
                   </div>
                   <div className="flex flex-col gap-1">
                      <label className="text-[9px] font-black text-slate-400 uppercase ml-1">Font Family</label>
                      <select 
                        className="w-full text-xs p-3 bg-slate-50 border border-slate-100 rounded-2xl outline-none" 
                        value={config.fontFamily} 
                        onChange={e => updateExportConfig({ fontFamily: e.target.value as any })}
                      >
                         <option value="Inter">Sans Serif (Inter)</option>
                         <option value="Serif">Serif (Classic)</option>
                         <option value="Mono">Monospace (Code)</option>
                      </select>
                   </div>
                </div>
             </section>
          </div>

          {/* Designer Preview Area */}
          <div className="lg:col-span-8 bg-slate-100 flex-1 flex flex-col p-4 lg:p-8 overflow-hidden relative">
             <div className="w-full h-full bg-white shadow-2xl rounded-3xl overflow-hidden border border-slate-200 flex flex-col">
                {exportEditMode ? (
                  <div className="flex-1 overflow-y-auto p-12 bg-white flex flex-col gap-12 max-w-4xl mx-auto w-full font-sans selection:bg-blue-100">
                    {/* EDITABLE COVER */}
                    <div className="border-l-[20px] pl-16 py-16 flex flex-col gap-8 group relative" style={{ borderColor: config.primaryColor }}>
                       <div className="text-sm font-black uppercase tracking-[0.4em]" style={{ color: config.primaryColor }}>UX Case Study Portfolio</div>
                       <input 
                         className="text-7xl font-black text-slate-900 border-none outline-none p-0 bg-transparent w-full"
                         value={project.title}
                         onChange={(e) => updateProject(project.id, { title: e.target.value })}
                       />
                       <textarea 
                         className="text-2xl text-slate-400 leading-relaxed border-none outline-none p-0 bg-transparent w-full resize-none"
                         rows={2}
                         value={project.desc}
                         onChange={(e) => updateProject(project.id, { desc: e.target.value })}
                       />
                       <div className="flex flex-col gap-2 mt-12">
                         <input 
                            className="text-3xl font-black text-slate-900 border-none outline-none p-0 bg-transparent w-full"
                            value={config.designerName}
                            placeholder="Your Name"
                            onChange={(e) => updateExportConfig({ designerName: e.target.value })}
                         />
                         <input 
                            className="text-base font-bold uppercase tracking-widest border-none outline-none p-0 bg-transparent w-full"
                            style={{ color: config.primaryColor }}
                            value={config.designerRole}
                            placeholder="Your Role"
                            onChange={(e) => updateExportConfig({ designerRole: e.target.value })}
                         />
                       </div>
                    </div>

                    {/* EDITABLE SECTIONS */}
                    {order.map((oid) => {
                       const stage = STAGES.find(s => s.id === oid);
                       const custom = config.customSections?.find(cs => cs.id === oid);
                       if (config.excludedSteps.includes(oid)) return null;

                       const content = custom ? custom.content : (config.customOverrides?.[oid] || project.steps[oid]?.notes || (oid === 'problem' ? project.notes : ''));

                       return (
                         <div key={oid} className="flex flex-col gap-6 p-8 rounded-[2rem] bg-slate-50/50 border border-slate-100 hover:border-blue-200 transition-all group relative">
                            <div className="flex items-center gap-5">
                               <div className="w-12 h-12 rounded-2xl bg-blue-600 text-white flex items-center justify-center font-black text-xl shadow-lg" style={{ backgroundColor: config.primaryColor }}>
                                  {order.indexOf(oid) + 1}
                               </div>
                               {custom ? (
                                  <input 
                                    className="text-4xl font-black text-slate-900 bg-transparent border-none outline-none p-0 flex-1"
                                    value={custom.title}
                                    onChange={(e) => updateCustomSection(oid, { title: e.target.value })}
                                  />
                               ) : (
                                  <h2 className="text-4xl font-black text-slate-900">{stage?.label.split('. ')[1]}</h2>
                               )}
                            </div>
                            <textarea 
                               className="w-full min-h-[150px] bg-white border border-slate-200 rounded-2xl p-8 text-slate-800 leading-relaxed text-lg focus:ring-4 focus:ring-blue-500/10 outline-none transition-all shadow-sm"
                               value={content}
                               placeholder={`Type content here... Use **bold** or - lists.`}
                               onChange={(e) => custom ? updateCustomSection(oid, { content: e.target.value }) : updateOverride(oid, e.target.value)}
                            />
                            <div className="absolute top-8 right-8 text-[10px] font-black text-slate-300 uppercase tracking-widest opacity-0 group-hover:opacity-100">Click to Edit Section</div>
                         </div>
                       );
                    })}

                    <div className="py-20 flex justify-center">
                       <Button onClick={addCustomSection} variant="outline" className="rounded-full border-dashed border-2 px-10 py-6 text-slate-400 hover:border-blue-500 hover:text-blue-500">
                          <IconPlus className="w-5 h-5 mr-2" /> Add a new section to your Case Study
                       </Button>
                    </div>
                  </div>
                ) : (
                  <iframe srcDoc={previewHtml} className="w-full h-full border-0" sandbox="allow-same-origin" />
                )}
             </div>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${className}`} role="main">
      {showCelebration && (
        <div className="fixed inset-0 pointer-events-none z-[100] flex items-center justify-center animate-out fade-out duration-1000 delay-2000">
           <div className="bg-white/80 backdrop-blur-xl px-12 py-6 rounded-3xl shadow-2xl border border-blue-200 flex flex-col items-center animate-in zoom-in-95 duration-500">
              <span className="text-6xl mb-4">🚀</span>
              <h3 className="text-2xl font-black text-slate-900 leading-none">Phase Complete!</h3>
              <p className="text-slate-500 font-bold text-sm mt-2">Milestone verified successfully.</p>
           </div>
        </div>
      )}

      <div className="bg-white border-b border-slate-200 p-4 md:p-6 shadow-sm flex flex-col gap-3 shrink-0 pt-safe">
        <div className="flex justify-between items-center">
          <div className="min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <span className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Phase {currentStepIndex + 1}</span>
              {isStepComplete && <span className="bg-emerald-100 text-emerald-700 text-[9px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter flex items-center gap-1"><IconCheck className="w-2.5 h-2.5" /> Verified</span>}
            </div>
            <h1 className="text-lg md:text-2xl font-black text-slate-900 truncate leading-tight tracking-tight">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setIsPreviewMode(!isPreviewMode)} className={`p-2 rounded-xl border transition-all active:scale-90 ${isPreviewMode ? 'bg-blue-600 text-white border-blue-600 shadow-glow' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>
                <IconEye className="w-5 h-5" />
             </button>
             <ProgressRing progress={progress} radius={22} stroke={3} className="text-blue-600" />
          </div>
        </div>

        <div className="md:hidden flex bg-slate-100 p-1 rounded-2xl">
          <button 
            onClick={() => setActiveMobileTab('strategy')} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all active:scale-95 ${activeMobileTab === 'strategy' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
          >
            <IconFile className="w-4 h-4" /> Strategy
          </button>
          <button 
            onClick={() => setActiveMobileTab('evidence')} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all active:scale-95 ${activeMobileTab === 'evidence' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
          >
            <IconLayout className="w-4 h-4" /> Proof <span className="bg-slate-200 text-slate-500 w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold">{stepAssets.length}</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col md:grid md:grid-cols-2 gap-0 md:gap-6 overflow-hidden">
        <div className={`flex flex-col min-h-0 flex-1 h-full bg-white md:bg-transparent transition-all duration-300 ${activeMobileTab === 'strategy' ? 'translate-x-0' : '-translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-3xl shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex flex-col border-b border-slate-50 bg-slate-50/20">
              <div className="flex items-center justify-between px-6 py-4">
                 <button id="tour-templates" onClick={() => setIsGuideOpen(true)} className="bg-blue-600 text-white rounded-full px-5 py-2 text-[10px] font-black uppercase tracking-widest flex items-center shadow-glow active:scale-95 transition-all">
                    <IconLayout className="w-4 h-4 mr-2" /> Designer toolkit
                 </button>
                 <div className={`text-[10px] font-black uppercase tracking-tighter ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                     {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Saved' : ''}
                 </div>
              </div>

              {phaseTemplates.length > 0 && !isPreviewMode && (
                <div className="px-6 pb-4 flex gap-2 overflow-x-auto hide-scrollbar">
                   <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-2 shrink-0">Suggestions:</span>
                   {phaseTemplates.map(t => (
                     <button 
                       key={t.key} 
                       onClick={() => handleInsert(t.content)}
                       className="px-4 py-1.5 bg-white border border-slate-200 rounded-full text-[10px] font-bold text-slate-600 hover:border-blue-500 hover:text-blue-600 transition-all whitespace-nowrap active:scale-95"
                     >
                        + {t.label}
                     </button>
                   ))}
                </div>
              )}
            </div>

            <div className="flex-1 relative overflow-hidden">
              {isPreviewMode ? (
                <div className="absolute inset-0 p-6 md:p-10 overflow-y-auto prose prose-slate max-w-none bg-white font-sans selection:bg-blue-100">
                  <div className="text-slate-800 leading-[1.8]" dangerouslySetInnerHTML={{ __html: parseMarkdown(notes) }} />
                  {notes.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-300 italic"><IconFile className="w-12 h-12 mb-4 opacity-10" /> Document your phase Strategy here.</div>}
                </div>
              ) : (
                <textarea
                  value={notes}
                  onChange={handleNotesChange}
                  onBlur={handleSave} 
                  placeholder={`Phase Guide: ${currentStage.help}\n\nStart writing your design rationale. Use headers like "Goal" or "Success Metrics"...`}
                  className="w-full h-full bg-white p-6 md:p-10 resize-none focus:outline-none text-slate-800 leading-relaxed text-base md:text-lg font-sans placeholder:text-slate-300"
                />
              )}
            </div>
          </div>
        </div>

        <div className={`flex flex-col flex-1 min-h-0 h-full bg-slate-50 md:bg-transparent transition-all duration-300 ${activeMobileTab === 'evidence' ? 'translate-x-0' : 'translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-3xl shadow-soft flex-1 flex flex-col overflow-hidden">
            <div className="flex items-center justify-between px-6 py-4 border-b border-slate-50 bg-slate-50/20">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Evidence Vault</h3>
               <label className="cursor-pointer active:scale-95 transition-transform">
                  <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                  <div className="px-5 py-2 bg-slate-900 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center">
                    <IconPlus className="w-4 h-4 mr-2" /> Upload Proof
                  </div>
               </label>
            </div>

            <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50/40">
              {stepAssets.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-10">
                   <div className="w-24 h-24 rounded-3xl bg-white border border-slate-100 shadow-sm flex items-center justify-center mb-6">
                     <IconFile className="w-10 h-10 text-slate-200" />
                   </div>
                   <h4 className="text-slate-900 font-black mb-2 uppercase tracking-tight">No Artifacts Yet</h4>
                   <p className="text-xs text-slate-500 max-w-[200px] leading-relaxed">Proof of work is essential for a professional case study.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-6">
                  {[...stepAssets].reverse().map((asset, i) => {
                    const originalIdx = project.assets.indexOf(asset);
                    return (
                      <div key={i} className="bg-white border border-slate-200 rounded-3xl p-4 shadow-sm group animate-in slide-in-from-bottom-4 duration-300">
                        <div className="relative aspect-video bg-slate-50 rounded-2xl overflow-hidden mb-4 border border-slate-100">
                          <img src={asset.url || asset.dataURL} className="w-full h-full object-contain" alt={asset.name} />
                          <div className="absolute top-3 right-3 flex gap-2">
                             <button onClick={() => window.open(asset.url || asset.dataURL, '_blank')} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-slate-900 active:scale-90"><IconEye className="w-4 h-4" /></button>
                             <button onClick={() => deleteAsset(originalIdx)} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-red-500 active:scale-90"><IconTrash className="w-4 h-4" /></button>
                          </div>
                        </div>
                        <div className="px-2 space-y-4">
                          <div className="flex justify-between items-center">
                            <h5 className="text-xs font-black text-slate-900 truncate uppercase tracking-tight">{asset.name}</h5>
                            <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">{new Date(asset.createdAt).toLocaleDateString()}</span>
                          </div>
                          <textarea 
                            placeholder="Add a meaningful description..." 
                            className="w-full text-base md:text-xs p-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500 transition-all resize-none h-24 text-slate-600 leading-relaxed"
                            value={asset.caption || ''}
                            onChange={(e) => handleAssetCaptionChange(originalIdx, e.target.value)}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="sticky bottom-0 md:static bg-white p-4 md:p-6 flex justify-between items-center z-40 pb-safe shadow-sheet">
         <button onClick={() => prevStep && onStepSelect(prevStep.id)} className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-slate-400 p-3 active:scale-95 ${!prevStep && 'invisible'}`}>
           <IconArrowRight className="w-4 h-4 rotate-180" /> Back
         </button>

         <div className="flex gap-4">
            <button 
                onClick={toggleStepCompletion} 
                className={`w-14 h-14 rounded-full flex items-center justify-center transition-all active:scale-90 border-4 ${isStepComplete ? 'bg-emerald-500 border-emerald-100 text-white shadow-lg shadow-emerald-500/20' : 'bg-white border-slate-100 text-slate-300'}`}
            >
                <IconCheck className="w-7 h-7" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} className="bg-blue-600 px-10 rounded-full shadow-fab font-black tracking-[0.1em] uppercase text-xs h-14 active:scale-95">
                {nextStep ? 'Next Phase' : 'Finalize'} <IconArrowRight className="w-4 h-4 ml-2" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Replace Image', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete Asset', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />

      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
      <GuideModal isOpen={isGuideOpen} onClose={() => setIsGuideOpen(false)} onInsert={handleInsert} currentStepId={currentStepId} />
    </main>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion, ExportConfig, Asset, CustomSection } from '../types';
import { STAGES, TEMPLATES } from '../constants';
import { Button } from './ui/Button';
// Added IconClose to imports
import { IconDownload, IconTrash, IconFile, IconReplace, IconCheck, IconArrowRight, IconLayout, IconPlus, IconEye, IconEdit, IconChevronDown, IconClose } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
import { ContextMenu } from './ui/ContextMenu';
import { HistoryModal } from './HistoryModal';
import { GuideModal } from './GuideModal';
import { generateFullHtml } from '../utils/exporter';
import { parseMarkdown } from '../utils/pdfTemplate';

interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  isGuideOpen: boolean;
  setIsGuideOpen: (open: boolean) => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  isGuideOpen,
  setIsGuideOpen,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [activeMobileTab, setActiveMobileTab] = useState<'strategy' | 'evidence'>('strategy');
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [showCelebration, setShowCelebration] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [exportEditMode, setExportEditMode] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  const phaseTemplates = TEMPLATES.filter(t => t.category === currentStage.templateCategory || t.key === currentStage.id);

  useEffect(() => {
    if (project && project.steps) {
      const stepData = project.steps[currentStepId] || { notes: '', isComplete: false };
      let externalNotes = stepData.notes;
      if (currentStepId === 'problem' && !externalNotes && project.notes) {
        externalNotes = project.notes;
      }
      if (externalNotes !== notesRef.current) {
        setNotes(externalNotes);
        notesRef.current = externalNotes;
      }
    }
  }, [project?.id, currentStepId, project?.steps?.[currentStepId]?.notes]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project || !project.steps) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps[currentStepId]?.isComplete || false;
    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project || !project.steps) return;
    const isCurrentlyComplete = project.steps[currentStepId]?.isComplete || false;
    const nextCompleteState = !isCurrentlyComplete;
    if (nextCompleteState) {
      setShowCelebration(true);
      setTimeout(() => setShowCelebration(false), 3000);
    }
    updateStepData(currentStepId, { notes, isComplete: nextCompleteState });
  };

  const handleInsert = (content: string) => {
    const newNotes = notes.trim() ? notes + "\n\n" + content : content;
    setNotes(newNotes);
    notesRef.current = newNotes;
    setSaveStatus('modified');
    handleSave();
  };

  const updateExportConfig = (updates: Partial<ExportConfig>) => {
    if (!project) return;
    const current = project.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: [],
      sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id),
      customSections: []
    };
    updateProject(project.id, { exportConfig: { ...current, ...updates } });
  };

  const toggleSectionExcluded = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.excludedSteps || [];
    const next = current.includes(id) ? current.filter(x => x !== id) : [...current, id];
    updateExportConfig({ excludedSteps: next });
  };

  const moveSection = (id: string, direction: 'up' | 'down') => {
    if (!project) return;
    const order = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    const index = order.indexOf(id);
    if (index === -1) return;
    const newOrder = [...order];
    if (direction === 'up' && index > 0) {
      [newOrder[index], newOrder[index - 1]] = [newOrder[index - 1], newOrder[index]];
    } else if (direction === 'down' && index < newOrder.length - 1) {
      [newOrder[index], newOrder[index + 1]] = [newOrder[index + 1], newOrder[index]];
    }
    updateExportConfig({ sectionOrder: newOrder });
  };

  const updateOverride = (id: string, content: string) => {
    if (!project) return;
    const currentOverrides = project.exportConfig?.customOverrides || {};
    updateExportConfig({ customOverrides: { ...currentOverrides, [id]: content } });
  };

  const addCustomSection = () => {
    if (!project) return;
    const id = 'custom_' + Date.now();
    const newSection: CustomSection = { id, title: 'New Custom Section', content: '', showAssets: false };
    const currentSections = project.exportConfig?.customSections || [];
    const currentOrder = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    updateExportConfig({ 
      customSections: [...currentSections, newSection],
      sectionOrder: [...currentOrder, id]
    });
  };

  const updateCustomSection = (id: string, updates: Partial<CustomSection>) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const next = current.map(s => s.id === id ? { ...s, ...updates } : s);
    updateExportConfig({ customSections: next });
  };

  const removeCustomSection = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const nextSections = current.filter(s => s.id !== id);
    const currentOrder = project.exportConfig?.sectionOrder || [];
    const nextOrder = currentOrder.filter(oid => oid !== id);
    updateExportConfig({ customSections: nextSections, sectionOrder: nextOrder });
  };

  const handleAssetCaptionChange = (index: number, caption: string) => {
    if (!project) return;
    const updatedAssets = [...project.assets];
    updatedAssets[index] = { ...updatedAssets[index], caption };
    updateProject(project.id, { assets: updatedAssets });
  };

  if (!project) return null;

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = project.steps ? Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100) : 0;
  const stepAssets = project.assets ? project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) : [];

  if (currentStepId === 'casestudy') {
    const config = project.exportConfig || { theme: 'modern', primaryColor: '#3B82F6', fontFamily: 'Inter', showCover: true, shadowTOC: true, showAssets: true, designerName: '', designerRole: 'UX Designer', excludedSteps: [], sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id), customSections: [] };
    const previewHtml = generateFullHtml(project, true);
    const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);

    return (
      <main className={`flex-1 flex flex-col gap-4 min-w-0 h-full overflow-hidden ${className}`}>
        <div className="bg-white border-b border-slate-200 p-4 flex justify-between items-center shrink-0 pt-safe">
          <div className="flex items-center gap-3">
            <button onClick={() => onStepSelect(STAGES[STAGES.length - 2].id)} className="p-2 -ml-2 text-slate-400 active:scale-95 transition-transform"><IconArrowRight className="w-5 h-5 rotate-180" /></button>
            <h1 className="text-lg font-black text-slate-900 leading-none">Export Studio & Page Builder</h1>
          </div>
          <div className="flex gap-2">
            <Button onClick={() => setExportEditMode(!exportEditMode)} variant={exportEditMode ? "primary" : "outline"} size="sm" className="rounded-full px-4">
              <IconEdit className="w-4 h-4 mr-2" /> {exportEditMode ? "View Document" : "Build Content"}
            </Button>
            <Button onClick={() => onExport(project)} size="sm" className="bg-blue-600 rounded-full px-5 shadow-glow active:scale-95">
              <IconDownload className="w-4 h-4 mr-2" /> Download Case Study
            </Button>
          </div>
        </div>

        <div className="flex-1 flex flex-col lg:grid lg:grid-cols-12 gap-0 lg:gap-6 overflow-hidden">
          {/* Controls Sidebar */}
          <div className="lg:col-span-4 bg-white border-b lg:border lg:border-slate-200 lg:rounded-3xl p-6 shadow-sm flex flex-col gap-8 overflow-y-auto max-h-[30vh] lg:max-h-full">
             <section>
                <div className="flex items-center justify-between mb-4">
                   <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em]">Section Management</h3>
                   <Button size="sm" variant="ghost" onClick={addCustomSection} className="h-6 text-[10px] text-blue-600 font-black">+ Custom</Button>
                </div>
                <div className="space-y-2">
                   {order.map((oid, idx) => {
                     const stage = STAGES.find(s => s.id === oid);
                     const custom = config.customSections?.find(cs => cs.id === oid);
                     const isExcluded = config.excludedSteps.includes(oid);
                     if (!stage && !custom) return null;
                     return (
                       <div key={oid} className={`group relative flex items-center justify-between p-3 rounded-2xl border transition-all ${isExcluded ? 'bg-slate-50 text-slate-300 border-slate-100' : 'bg-white border-slate-200 text-slate-900 shadow-sm'}`}>
                          <div className="flex items-center gap-3 truncate">
                             <div className="flex flex-col gap-1">
                                <button onClick={() => moveSection(oid, 'up')} className="p-0.5 hover:text-blue-500"><IconChevronDown className="w-3 h-3 rotate-180" /></button>
                                <button onClick={() => moveSection(oid, 'down')} className="p-0.5 hover:text-blue-500"><IconChevronDown className="w-3 h-3" /></button>
                             </div>
                             <span className="text-lg">{stage?.icon || '📦'}</span>
                             <span className="text-xs font-bold truncate">{stage?.label.split('. ')[1] || custom?.title}</span>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                             {custom && <button onClick={() => removeCustomSection(oid)} className="p-2 text-red-400 hover:bg-red-50 rounded-xl"><IconTrash className="w-3.5 h-3.5" /></button>}
                             <button onClick={() => toggleSectionExcluded(oid)} className={`p-2 rounded-xl ${isExcluded ? 'text-emerald-500' : 'text-slate-300 hover:text-red-400'}`}>
                                {isExcluded ? <IconPlus className="w-3.5 h-3.5" /> : <IconClose className="w-3.5 h-3.5" />}
                             </button>
                          </div>
                       </div>
                     );
                   })}
                </div>
             </section>

             <section>
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] mb-4">Branding & Layout</h3>
                <div className="space-y-4">
                   <div className="flex flex-col gap-1">
                      <label className="text-[9px] font-black text-slate-400 uppercase ml-1">Primary Color</label>
                      <div className="flex gap-3 items-center">
                         <input type="color" className="w-10 h-10 rounded-xl cursor-pointer bg-transparent border-0" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                         <input type="text" className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-3 py-2 text-xs font-mono uppercase" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                      </div>
                   </div>
                   <div className="flex flex-col gap-1">
                      <label className="text-[9px] font-black text-slate-400 uppercase ml-1">Font Family</label>
                      <select 
                        className="w-full text-xs p-3 bg-slate-50 border border-slate-100 rounded-2xl outline-none" 
                        value={config.fontFamily} 
                        onChange={e => updateExportConfig({ fontFamily: e.target.value as any })}
                      >
                         <option value="Inter">Sans Serif (Inter)</option>
                         <option value="Serif">Serif (Classic)</option>
                         <option value="Mono">Monospace (Code)</option>
                      </select>
                   </div>
                </div>
             </section>
          </div>

          {/* Designer Preview Area */}
          <div className="lg:col-span-8 bg-slate-100 flex-1 flex flex-col p-4 lg:p-8 overflow-hidden relative">
             <div className="w-full h-full bg-white shadow-2xl rounded-3xl overflow-hidden border border-slate-200 flex flex-col">
                {exportEditMode ? (
                  <div className="flex-1 overflow-y-auto p-12 bg-white flex flex-col gap-12 max-w-4xl mx-auto w-full font-sans selection:bg-blue-100">
                    {/* EDITABLE COVER */}
                    <div className="border-l-[20px] pl-16 py-16 flex flex-col gap-8 group relative" style={{ borderColor: config.primaryColor }}>
                       <div className="text-sm font-black uppercase tracking-[0.4em]" style={{ color: config.primaryColor }}>UX Case Study Portfolio</div>
                       <input 
                         className="text-7xl font-black text-slate-900 border-none outline-none p-0 bg-transparent w-full"
                         value={project.title}
                         onChange={(e) => updateProject(project.id, { title: e.target.value })}
                       />
                       <textarea 
                         className="text-2xl text-slate-400 leading-relaxed border-none outline-none p-0 bg-transparent w-full resize-none"
                         rows={2}
                         value={project.desc}
                         onChange={(e) => updateProject(project.id, { desc: e.target.value })}
                       />
                       <div className="flex flex-col gap-2 mt-12">
                         <input 
                            className="text-3xl font-black text-slate-900 border-none outline-none p-0 bg-transparent w-full"
                            value={config.designerName}
                            placeholder="Your Name"
                            onChange={(e) => updateExportConfig({ designerName: e.target.value })}
                         />
                         <input 
                            className="text-base font-bold uppercase tracking-widest border-none outline-none p-0 bg-transparent w-full"
                            style={{ color: config.primaryColor }}
                            value={config.designerRole}
                            placeholder="Your Role"
                            onChange={(e) => updateExportConfig({ designerRole: e.target.value })}
                         />
                       </div>
                    </div>

                    {/* EDITABLE SECTIONS */}
                    {order.map((oid) => {
                       const stage = STAGES.find(s => s.id === oid);
                       const custom = config.customSections?.find(cs => cs.id === oid);
                       if (config.excludedSteps.includes(oid)) return null;

                       const content = custom ? custom.content : (config.customOverrides?.[oid] || project.steps[oid]?.notes || (oid === 'problem' ? project.notes : ''));

                       return (
                         <div key={oid} className="flex flex-col gap-6 p-8 rounded-[2rem] bg-slate-50/50 border border-slate-100 hover:border-blue-200 transition-all group relative">
                            <div className="flex items-center gap-5">
                               <div className="w-12 h-12 rounded-2xl bg-blue-600 text-white flex items-center justify-center font-black text-xl shadow-lg" style={{ backgroundColor: config.primaryColor }}>
                                  {order.indexOf(oid) + 1}
                               </div>
                               {custom ? (
                                  <input 
                                    className="text-4xl font-black text-slate-900 bg-transparent border-none outline-none p-0 flex-1"
                                    value={custom.title}
                                    onChange={(e) => updateCustomSection(oid, { title: e.target.value })}
                                  />
                               ) : (
                                  <h2 className="text-4xl font-black text-slate-900">{stage?.label.split('. ')[1]}</h2>
                               )}
                            </div>
                            <textarea 
                               className="w-full min-h-[150px] bg-white border border-slate-200 rounded-2xl p-8 text-slate-800 leading-relaxed text-lg focus:ring-4 focus:ring-blue-500/10 outline-none transition-all shadow-sm"
                               value={content}
                               placeholder={`Type content here... Use **bold** or - lists.`}
                               onChange={(e) => custom ? updateCustomSection(oid, { content: e.target.value }) : updateOverride(oid, e.target.value)}
                            />
                            <div className="absolute top-8 right-8 text-[10px] font-black text-slate-300 uppercase tracking-widest opacity-0 group-hover:opacity-100">Click to Edit Section</div>
                         </div>
                       );
                    })}

                    <div className="py-20 flex justify-center">
                       <Button onClick={addCustomSection} variant="outline" className="rounded-full border-dashed border-2 px-10 py-6 text-slate-400 hover:border-blue-500 hover:text-blue-500">
                          <IconPlus className="w-5 h-5 mr-2" /> Add a new section to your Case Study
                       </Button>
                    </div>
                  </div>
                ) : (
                  <iframe srcDoc={previewHtml} className="w-full h-full border-0" sandbox="allow-same-origin" />
                )}
             </div>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${className}`} role="main">
      {showCelebration && (
        <div className="fixed inset-0 pointer-events-none z-[100] flex items-center justify-center animate-out fade-out duration-1000 delay-2000">
           <div className="bg-white/80 backdrop-blur-xl px-12 py-6 rounded-3xl shadow-2xl border border-blue-200 flex flex-col items-center animate-in zoom-in-95 duration-500">
              <span className="text-6xl mb-4">🚀</span>
              <h3 className="text-2xl font-black text-slate-900 leading-none">Phase Complete!</h3>
              <p className="text-slate-500 font-bold text-sm mt-2">Milestone verified successfully.</p>
           </div>
        </div>
      )}

      <div className="bg-white border-b border-slate-200 p-4 md:p-6 shadow-sm flex flex-col gap-3 shrink-0 pt-safe">
        <div className="flex justify-between items-center">
          <div className="min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <span className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Phase {currentStepIndex + 1}</span>
              {isStepComplete && <span className="bg-emerald-100 text-emerald-700 text-[9px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter flex items-center gap-1"><IconCheck className="w-2.5 h-2.5" /> Verified</span>}
            </div>
            <h1 className="text-lg md:text-2xl font-black text-slate-900 truncate leading-tight tracking-tight">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <div className="flex items-center gap-3">
             <button onClick={() => setIsPreviewMode(!isPreviewMode)} className={`p-2 rounded-xl border transition-all active:scale-90 ${isPreviewMode ? 'bg-blue-600 text-white border-blue-600 shadow-glow' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>
                <IconEye className="w-5 h-5" />
             </button>
             <ProgressRing progress={progress} radius={22} stroke={3} className="text-blue-600" />
          </div>
        </div>

        <div className="md:hidden flex bg-slate-100 p-1 rounded-2xl">
          <button 
            onClick={() => setActiveMobileTab('strategy')} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all active:scale-95 ${activeMobileTab === 'strategy' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
          >
            <IconFile className="w-4 h-4" /> Strategy
          </button>
          <button 
            onClick={() => setActiveMobileTab('evidence')} 
            className={`flex-1 flex items-center justify-center gap-2 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all active:scale-95 ${activeMobileTab === 'evidence' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
          >
            <IconLayout className="w-4 h-4" /> Proof <span className="bg-slate-200 text-slate-500 w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold">{stepAssets.length}</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col md:grid md:grid-cols-2 gap-0 md:gap-6 overflow-hidden">
        <div className={`flex flex-col min-h-0 flex-1 h-full bg-white md:bg-transparent transition-all duration-300 ${activeMobileTab === 'strategy' ? 'translate-x-0' : '-translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-3xl shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex flex-col border-b border-slate-50 bg-slate-50/20">
              <div className="flex items-center justify-between px-6 py-4">
                 <button id="tour-templates" onClick={() => setIsGuideOpen(true)} className="bg-blue-600 text-white rounded-full px-5 py-2 text-[10px] font-black uppercase tracking-widest flex items-center shadow-glow active:scale-95 transition-all">
                    <IconLayout className="w-4 h-4 mr-2" /> Designer toolkit
                 </button>
                 <div className={`text-[10px] font-black uppercase tracking-tighter ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                     {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Saved' : ''}
                 </div>
              </div>

              {phaseTemplates.length > 0 && !isPreviewMode && (
                <div className="px-6 pb-4 flex gap-2 overflow-x-auto hide-scrollbar">
                   <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-2 shrink-0">Suggestions:</span>
                   {phaseTemplates.map(t => (
                     <button 
                       key={t.key} 
                       onClick={() => handleInsert(t.content)}
                       className="px-4 py-1.5 bg-white border border-slate-200 rounded-full text-[10px] font-bold text-slate-600 hover:border-blue-500 hover:text-blue-600 transition-all whitespace-nowrap active:scale-95"
                     >
                        + {t.label}
                     </button>
                   ))}
                </div>
              )}
            </div>

            <div className="flex-1 relative overflow-hidden">
              {isPreviewMode ? (
                <div className="absolute inset-0 p-6 md:p-10 overflow-y-auto prose prose-slate max-w-none bg-white font-sans selection:bg-blue-100">
                  <div className="text-slate-800 leading-[1.8]" dangerouslySetInnerHTML={{ __html: parseMarkdown(notes) }} />
                  {notes.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-300 italic"><IconFile className="w-12 h-12 mb-4 opacity-10" /> Document your phase Strategy here.</div>}
                </div>
              ) : (
                <textarea
                  value={notes}
                  onChange={handleNotesChange}
                  onBlur={handleSave} 
                  placeholder={`Phase Guide: ${currentStage.help}\n\nStart writing your design rationale. Use headers like "Goal" or "Success Metrics"...`}
                  className="w-full h-full bg-white p-6 md:p-10 resize-none focus:outline-none text-slate-800 leading-relaxed text-base md:text-lg font-sans placeholder:text-slate-300"
                />
              )}
            </div>
          </div>
        </div>

        <div className={`flex flex-col flex-1 min-h-0 h-full bg-slate-50 md:bg-transparent transition-all duration-300 ${activeMobileTab === 'evidence' ? 'translate-x-0' : 'translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-3xl shadow-soft flex-1 flex flex-col overflow-hidden">
            <div className="flex items-center justify-between px-6 py-4 border-b border-slate-50 bg-slate-50/20">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Evidence Vault</h3>
               <label className="cursor-pointer active:scale-95 transition-transform">
                  <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                  <div className="px-5 py-2 bg-slate-900 text-white rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center">
                    <IconPlus className="w-4 h-4 mr-2" /> Upload Proof
                  </div>
               </label>
            </div>

            <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50/40">
              {stepAssets.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-10">
                   <div className="w-24 h-24 rounded-3xl bg-white border border-slate-100 shadow-sm flex items-center justify-center mb-6">
                     <IconFile className="w-10 h-10 text-slate-200" />
                   </div>
                   <h4 className="text-slate-900 font-black mb-2 uppercase tracking-tight">No Artifacts Yet</h4>
                   <p className="text-xs text-slate-500 max-w-[200px] leading-relaxed">Proof of work is essential for a professional case study.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-6">
                  {[...stepAssets].reverse().map((asset, i) => {
                    const originalIdx = project.assets.indexOf(asset);
                    return (
                      <div key={i} className="bg-white border border-slate-200 rounded-3xl p-4 shadow-sm group animate-in slide-in-from-bottom-4 duration-300">
                        <div className="relative aspect-video bg-slate-50 rounded-2xl overflow-hidden mb-4 border border-slate-100">
                          <img src={asset.url || asset.dataURL} className="w-full h-full object-contain" alt={asset.name} />
                          <div className="absolute top-3 right-3 flex gap-2">
                             <button onClick={() => window.open(asset.url || asset.dataURL, '_blank')} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-slate-900 active:scale-90"><IconEye className="w-4 h-4" /></button>
                             <button onClick={() => deleteAsset(originalIdx)} className="p-3 bg-white/95 backdrop-blur-md rounded-xl shadow-md text-red-500 active:scale-90"><IconTrash className="w-4 h-4" /></button>
                          </div>
                        </div>
                        <div className="px-2 space-y-4">
                          <div className="flex justify-between items-center">
                            <h5 className="text-xs font-black text-slate-900 truncate uppercase tracking-tight">{asset.name}</h5>
                            <span className="text-[9px] font-bold text-slate-300 uppercase tracking-widest">{new Date(asset.createdAt).toLocaleDateString()}</span>
                          </div>
                          <textarea 
                            placeholder="Add a meaningful description..." 
                            className="w-full text-base md:text-xs p-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500 transition-all resize-none h-24 text-slate-600 leading-relaxed"
                            value={asset.caption || ''}
                            onChange={(e) => handleAssetCaptionChange(originalIdx, e.target.value)}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="sticky bottom-0 md:static bg-white p-4 md:p-6 flex justify-between items-center z-40 pb-safe shadow-sheet">
         <button onClick={() => prevStep && onStepSelect(prevStep.id)} className={`flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-slate-400 p-3 active:scale-95 ${!prevStep && 'invisible'}`}>
           <IconArrowRight className="w-4 h-4 rotate-180" /> Back
         </button>

         <div className="flex gap-4">
            <button 
                onClick={toggleStepCompletion} 
                className={`w-14 h-14 rounded-full flex items-center justify-center transition-all active:scale-90 border-4 ${isStepComplete ? 'bg-emerald-500 border-emerald-100 text-white shadow-lg shadow-emerald-500/20' : 'bg-white border-slate-100 text-slate-300'}`}
            >
                <IconCheck className="w-7 h-7" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} className="bg-blue-600 px-10 rounded-full shadow-fab font-black tracking-[0.1em] uppercase text-xs h-14 active:scale-95">
                {nextStep ? 'Next Phase' : 'Finalize'} <IconArrowRight className="w-4 h-4 ml-2" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Replace Image', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete Asset', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />

      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
      <GuideModal isOpen={isGuideOpen} onClose={() => setIsGuideOpen(false)} onInsert={handleInsert} currentStepId={currentStepId} />
    </main>
  );
};

import { Project, Asset, ExportConfig, CustomSection } from "../types";
import { STAGES } from "../constants";

function escapeHtml(s: string) {
  return (s || '').toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

export function parseMarkdown(text: string): string {
  if (!text) return '';
  let html = escapeHtml(text);
  html = html.replace(/^### (.*$)/gim, '<h3 style="margin-top: 24px; margin-bottom: 8px; font-weight: 800; color: #0f172a; font-size: 18px;">$1</h3>');
  html = html.replace(/^## (.*$)/gim, '<h2 style="margin-top: 32px; margin-bottom: 12px; font-weight: 800; color: #0f172a; font-size: 22px; border-bottom: 1px solid #eee; padding-bottom: 8px;">$1</h2>');
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #111827; font-weight: 700;">$1</strong>');
  const lines = html.split('\n');
  let inList = false;
  const processedLines = lines.map(line => {
    const listMatch = line.match(/^[-*] (.*)/);
    if (listMatch) {
      const content = listMatch[1];
      if (!inList) {
        inList = true;
        return `<ul style="margin-bottom: 16px; padding-left: 20px; list-style-type: disc;"><li style="margin-bottom: 4px;">${content}</li>`;
      }
      return `<li style="margin-bottom: 4px;">${content}</li>`;
    } else {
      if (inList) {
        inList = false;
        return `</ul>${line}<br>`;
      }
      return line + '<br>';
    }
  });
  html = processedLines.join('');
  return html;
}

function getAssetHtml(assets: Asset[], showAssets: boolean) {
  if (!showAssets || !assets || assets.length === 0) return '';
  return `
    <div class="assets-grid">
      ${assets.map(a => {
         const displayUrl = a.url || a.dataURL;
         if (!a.type.startsWith('image') || !displayUrl) return '';
         return `
           <div class="asset-item">
             <div class="asset-image-container">
               <img src="${displayUrl}" alt="${escapeHtml(a.name)}" />
             </div>
             ${a.caption ? `<div class="asset-caption">${escapeHtml(a.caption)}</div>` : ''}
           </div>
         `;
      }).join('')}
    </div>
  `;
}

function getTOCHtml(project: Project, config: ExportConfig) {
  if (!config.showTOC) return '';
  const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
  const customSections = config.customSections || [];

  const links = order.map(id => {
    const stage = STAGES.find(s => s.id === id);
    const custom = customSections.find(cs => cs.id === id);
    if (stage && !config.excludedSteps.includes(id)) {
      return `<li><a href="#section-${id}"><span>${escapeHtml(stage.label.replace(/^\d+\.\s/, ''))}</span><span class="dots"></span></a></li>`;
    }
    if (custom) {
      return `<li><a href="#section-${custom.id}"><span>${escapeHtml(custom.title)}</span><span class="dots"></span></a></li>`;
    }
    return '';
  }).filter(Boolean).join('');

  if (!links) return '';

  return `
    <nav class="toc-container" style="page-break-after: always; margin-bottom: 100px;">
      <h2 style="font-size: 28px; font-weight: 800; margin-bottom: 40px; border-bottom: 4px solid ${config.primaryColor}; display: inline-block;">Project Journey</h2>
      <ul class="toc-list">
        ${links}
      </ul>
    </nav>
    <style>
      .toc-list { list-style: none; padding: 0; margin: 0; }
      .toc-list li { margin-bottom: 16px; font-size: 18px; font-weight: 500; }
      .toc-list a { text-decoration: none; color: #475569; display: flex; align-items: center; transition: color 0.2s; }
      .toc-list a:hover { color: ${config.primaryColor}; }
      .toc-list .dots { flex: 1; border-bottom: 1px dotted #cbd5e1; margin: 0 10px; opacity: 0.5; }
    </style>
  `;
}

export function generateCaseStudyHtml(project: Project): string {
  const config: ExportConfig = project.exportConfig || {
    theme: 'modern',
    primaryColor: '#3B82F6',
    fontFamily: 'Inter',
    showCover: true,
    showTOC: true,
    showAssets: true,
    designerName: '',
    designerRole: 'UX Designer',
    excludedSteps: []
  };

  const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
  const customSections = config.customSections || [];

  const sectionsHtml = order.map((id, index) => {
    const stage = STAGES.find(s => s.id === id);
    if (stage) {
      if (config.excludedSteps.includes(id)) return '';
      const stepData = project.steps?.[id] || { notes: '', isComplete: false };
      const rawContent = config.customOverrides?.[id] || stepData.notes || (id === 'problem' ? project.notes : '');
      const stepAssets = project.assets.filter(a => (a.stepId === id) || (id === 'problem' && !a.stepId));
      if (!rawContent && stepAssets.length === 0) return '';
      return `
        <section class="step-section" id="section-${id}">
          <div class="step-header">
            <span class="step-num" style="background: ${config.primaryColor};">${index + 1}</span>
            <h2 class="step-title">${escapeHtml(stage.label.replace(/^\d+\.\s/, ''))}</h2>
          </div>
          <div class="step-content">
            ${rawContent ? `<div class="step-notes">${parseMarkdown(rawContent)}</div>` : ''}
            ${getAssetHtml(stepAssets, config.showAssets)}
          </div>
        </section>
      `;
    }
    const custom = customSections.find(cs => cs.id === id);
    if (custom) {
      return `
        <section class="step-section" id="section-${custom.id}">
          <div class="step-header">
            <span class="step-num" style="background: ${config.primaryColor};">${index + 1}</span>
            <h2 class="step-title">${escapeHtml(custom.title)}</h2>
          </div>
          <div class="step-content">
            <div class="step-notes">${parseMarkdown(custom.content)}</div>
          </div>
        </section>
      `;
    }
    return '';
  }).join('');

  const fontStack = config.fontFamily === 'Serif' ? 'Georgia, serif' : config.fontFamily === 'Mono' ? 'monospace' : "'Inter', sans-serif";
  const themeStyles = config.theme === 'minimal' 
    ? `.document-wrapper { padding: 40px; } .step-title { font-size: 32px; } .step-section { margin-bottom: 80px; }`
    : config.theme === 'classic'
    ? `.document-wrapper { border: 1px solid #e2e8f0; margin-top: 40px; margin-bottom: 40px; } .step-num { border-radius: 50%; }`
    : ``;

  return `
  <!DOCTYPE html>
  <html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${escapeHtml(project.title)}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');
      * { box-sizing: border-box; }
      body {
        font-family: ${fontStack};
        color: #1e293b;
        line-height: 1.6;
        margin: 0;
        background: ${config.theme === 'minimal' ? '#ffffff' : '#f8fafc'};
        -webkit-print-color-adjust: exact;
      }
      .document-wrapper {
        max-width: 1100px;
        margin: 0 auto;
        padding: 80px 40px;
        background: white;
      }
      .assets-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(400px, 1fr));
        gap: 32px;
        margin: 40px 0;
      }
      .asset-item {
        background: #ffffff;
        border: 1px solid #f1f5f9;
        border-radius: 24px;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        break-inside: avoid;
      }
      .asset-image-container {
        background: #f8fafc;
        display: flex;
        align-items: center;
        justify-content: center;
        min-height: 300px;
      }
      .asset-item img {
        width: 100%;
        max-height: 600px;
        object-fit: contain;
      }
      .asset-caption {
        padding: 24px;
        font-size: 14px;
        color: #64748b;
        border-top: 1px solid #f1f5f9;
      }
      .step-section {
        margin-bottom: 120px;
        page-break-inside: avoid;
      }
      .step-header {
        display: flex;
        align-items: center;
        gap: 20px;
        margin-bottom: 32px;
      }
      .step-num {
        color: white;
        width: 44px;
        height: 44px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 14px;
        font-size: 18px;
        font-weight: 800;
      }
      .step-title {
        font-size: 38px;
        margin: 0;
        font-weight: 800;
        color: #0f172a;
      }
      .step-notes {
        font-size: 19px;
        color: #334155;
        line-height: 1.8;
      }
      .cover {
        min-height: 75vh;
        display: ${config.showCover ? 'flex' : 'none'};
        flex-direction: column;
        justify-content: center;
        border-left: 20px solid ${config.primaryColor};
        padding-left: 64px;
        margin-bottom: 140px;
        page-break-after: always;
      }
      .cover h1 {
        font-size: 84px;
        margin: 0;
        font-weight: 900;
        line-height: 1.05;
      }
      .cover p {
        font-size: 28px;
        color: #64748b;
        margin-top: 24px;
        max-width: 760px;
      }
      .designer-info { margin-top: 80px; }
      .designer-name { font-size: 26px; font-weight: 800; }
      .designer-role { font-size: 15px; font-weight: 700; color: ${config.primaryColor}; text-transform: uppercase; letter-spacing: 0.25em; margin-top: 8px; }
      ${themeStyles}
      @media print {
        .document-wrapper { padding: 0; max-width: 100%; width: 100%; border: none; margin: 0; }
        .cover { min-height: 90vh; }
      }
    </style>
  </head>
  <body>
    <div class="document-wrapper">
      <div class="cover">
        <div style="font-size: 14px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.4em; color: ${config.primaryColor}; margin-bottom: 24px;">UX Case Study Portfolio</div>
        <h1>${escapeHtml(project.title)}</h1>
        <p>${escapeHtml(project.desc)}</p>
        <div class="designer-info">
          <div class="designer-name">${escapeHtml(config.designerName || 'UX Designer')}</div>
          <div class="designer-role">${escapeHtml(config.designerRole || 'Lead Researcher')}</div>
        </div>
      </div>
      ${getTOCHtml(project, config)}
      <div class="content">
        ${sectionsHtml}
      </div>
    </div>
  </body>
  </html>
  `;
}

import React, { useState, useEffect } from 'react';
import { Project, ExportConfig } from '../types';
import { generateFullHtml, downloadCaseStudy, exportToPrintable } from '../utils/exporter';
import { Button } from './ui/Button';
import { IconClose, IconDownload, IconFile, IconCheck, IconLayout, IconEye, IconEdit } from './ui/Icons';

interface ExportModalProps {
  project: Project | null;
  isOpen: boolean;
  onClose: () => void;
  onUpdateProject?: (id: string, updates: Partial<Project>) => void;
}

export const ExportModal: React.FC<ExportModalProps> = ({ project, isOpen, onClose, onUpdateProject }) => {
  const [format, setFormat] = useState<'html' | 'pdf'>('html');
  const [previewHtml, setPreviewHtml] = useState('');
  const [estimatedSize, setEstimatedSize] = useState<string>('Calculating...');

  const [isExporting, setIsExporting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');

  // Local config initialized from project or defaults
  const [config, setConfig] = useState<ExportConfig>(() => {
    return project?.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: []
    };
  });

  useEffect(() => {
    if (project && isOpen) {
      const mergedProject = { ...project, exportConfig: config };
      const html = generateFullHtml(mergedProject, config.showAssets);
      setPreviewHtml(html);

      const sizeBytes = new Blob([html]).size;
      const kb = Math.round(sizeBytes / 1024);

      if (format === 'html') {
        setEstimatedSize(`~${kb} KB`);
      } else {
        const pdfEst = Math.round(kb * 1.5 + 500); 
        setEstimatedSize(`~${pdfEst} KB`);
      }
    }
  }, [project, isOpen, format, config]);

  const updateConfig = (updates: Partial<ExportConfig>) => {
    const next = { ...config, ...updates };
    setConfig(next);
    // If we have an update callback, persist it
    if (onUpdateProject && project) {
      onUpdateProject(project.id, { exportConfig: next });
    }
  };

  if (!isOpen || !project) return null;

  const handleExport = async () => {
    setIsExporting(true);
    setProgress(0);

    // Create a virtual project with the current config tweaks
    const finalProject = { ...project, exportConfig: config };

    try {
      if (format === 'html') {
        setStatusText('Preparing HTML...');
        setProgress(50);
        await new Promise(r => setTimeout(r, 500)); 
        downloadCaseStudy(finalProject, config.showAssets);
        setProgress(100);
        setStatusText('Download started!');
        setTimeout(() => {
           setIsExporting(false);
           onClose();
        }, 1000);
      } else {
        setStatusText('Inlining images & preparing document...');
        setProgress(30);
        await new Promise(r => setTimeout(r, 300));

        const result = await exportToPrintable(finalProject, config.showAssets);

        setProgress(100);
        if (result.method === 'print') {
          setStatusText('Print dialog opened!');
        } else {
          setStatusText('Popup blocked: HTML downloaded.');
        }

        setTimeout(() => {
           setIsExporting(false);
           onClose();
        }, 1500);
      }
    } catch (e) {
      console.error(e);
      setStatusText('Export failed.');
      setIsExporting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white border border-slate-200 w-full max-w-6xl h-[90vh] rounded-3xl shadow-2xl flex flex-col overflow-hidden">

        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-100 bg-white shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-12 h-12 rounded-2xl bg-blue-600 flex items-center justify-center text-white shadow-lg">
                <IconDownload className="w-6 h-6" />
             </div>
             <div>
               <h2 className="text-xl font-black text-slate-900 leading-tight">Export Case Study</h2>
               <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-0.5">Project: {project.title}</p>
             </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-900 p-2 rounded-full hover:bg-slate-100 transition-colors">
            <IconClose className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 flex overflow-hidden">

          {/* Sidebar Controls */}
          <div className="w-full md:w-96 bg-slate-50 border-r border-slate-100 p-8 flex flex-col overflow-y-auto gap-8">

            {/* Format Selection */}
            <section>
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Export Mode</h3>
              <div className="grid grid-cols-2 gap-3">
                <button 
                  onClick={() => setFormat('html')}
                  className={`flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${format === 'html' ? 'bg-blue-600 text-white border-blue-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
                >
                  <IconLayout className="w-6 h-6" />
                  <span className="text-[10px] font-black uppercase">Web View</span>
                </button>
                <button 
                  onClick={() => setFormat('pdf')}
                  className={`flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${format === 'pdf' ? 'bg-blue-600 text-white border-blue-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
