const STORAGE_WARNING_THRESHOLD = 4.5 * 1024 * 1024; 

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    try {
      const local = localStorage.getItem(STORAGE_KEY);
      if (local) return JSON.parse(local);
    } catch (e) { console.error('Failed to load state', e); }
    return { projects: {}, activeProjectId: null };
  });

  const [isGuideOpen, setIsGuideOpen] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [exportProject, setExportProject] = useState<Project | null>(null);
  const [showMobileProjects, setShowMobileProjects] = useState(false);
  const [toast, setToast] = useState<Omit<ToastProps, 'onClose'> | null>(null);
  const [confirmConfig, setConfirmConfig] = useState<{isOpen: boolean; title: string; message: string; onConfirm: () => void;}>({ isOpen: false, title: '', message: '', onConfirm: () => {} });
  const [devClickCount, setDevClickCount] = useState(0);
  const [isDevMode, setIsDevMode] = useState(false);
  const [isDebugOpen, setIsDebugOpen] = useState(false);

  useEffect(() => {
    try {
      const json = JSON.stringify(state);
      localStorage.setItem(STORAGE_KEY, json);
      if (new Blob([json]).size > STORAGE_WARNING_THRESHOLD) setToast({ message: 'Storage critical!', type: 'error' });
    } catch (e) { setToast({ message: 'Storage full!', type: 'error' }); }
  }, [state]);

  useEffect(() => {
    if (Object.keys(state.projects).length === 0) {
      const id = uid();
      const example: Project = {
        id, title: 'Project: Grocery App', desc: 'Redesigning the cart experience', notes: '',
        stages: {}, steps: STAGES.reduce((acc, s) => ({ ...acc, [s.id]: { notes: '', isComplete: false } }), {}),
        assets: [], createdAt: new Date().toISOString(), currentStepId: 'problem'
      };
      setState({ projects: { [id]: example }, activeProjectId: id });
    }
  }, []);

  const activeProject = state.activeProjectId ? state.projects[state.activeProjectId] : null;

  const handleCreateProject = (title: string, desc: string) => {
    const id = uid();
    const newProj: Project = { id, title, desc, notes: '', stages: {}, steps: STAGES.reduce((acc, s) => ({ ...acc, [s.id]: { notes: '', isComplete: false } }), {}), assets: [], createdAt: new Date().toISOString(), currentStepId: 'problem' };
    setState(prev => ({ projects: { ...prev.projects, [id]: newProj }, activeProjectId: id }));
    setShowMobileProjects(false);
  };

  const deleteProject = (id: string) => {
    setState(prev => {
      const nextProjects = { ...prev.projects };
      delete nextProjects[id];
      return { projects: nextProjects, activeProjectId: prev.activeProjectId === id ? (Object.keys(nextProjects)[0] || null) : prev.activeProjectId };
    });
  };

  const updateProject = (id: string, updates: Partial<Project>) => {
    setState(prev => ({ ...prev, projects: { ...prev.projects, [id]: { ...prev.projects[id], ...updates } } }));
  };

  const updateStepData = useCallback((stepId: string, data: { notes: string; isComplete: boolean }) => {
     if (!state.activeProjectId) return;
     setState(prev => {
         const p = prev.projects[prev.activeProjectId!];
         if (!p) return prev;
         const newSteps = { ...p.steps, [stepId]: { ...p.steps[stepId], ...data } };
         return { ...prev, projects: { ...prev.projects, [p.id]: { ...p, steps: newSteps, history: [{ timestamp: new Date().toISOString(), notes: p.notes, stepData: newSteps }, ...(p.history || [])].slice(0, 3) } } };
     });
  }, [state.activeProjectId]);

  const duplicateProject = (id: string) => {
    const source = state.projects[id];
    if(!source) return;
    const newId = uid();
    setState(prev => ({ projects: { ...prev.projects, [newId]: { ...source, id: newId, title: `${source.title} (Copy)`, createdAt: new Date().toISOString() } }, activeProjectId: newId }));
  };

  const handleAssetUpload = async (file: File) => {
    if (!activeProject) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const asset: Asset = { name: file.name, type: file.type, dataURL: e.target?.result as string, createdAt: new Date().toISOString(), size: file.size, stepId: activeProject.currentStepId || 'problem' };
      setState(prev => {
        const p = prev.projects[activeProject.id];
        return { ...prev, projects: { ...prev.projects, [p.id]: { ...p, assets: [...p.assets, asset] } } };
      });
      setToast({ message: 'Evidence uploaded successfully!', type: 'success' });
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="h-full w-full bg-slate-50 text-slate-900 flex flex-col font-sans overflow-hidden">
      {/* Sleek Desktop-only Header */}
      <header className="hidden md:flex h-14 border-b border-slate-200 bg-white/80 backdrop-blur-md items-center px-6 sticky top-0 z-40 shrink-0">
        <div onClick={() => { if(devClickCount + 1 === 5) setIsDevMode(true); setDevClickCount(prev => prev + 1); }} className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center font-black text-white mr-3 shadow-md select-none cursor-pointer active:scale-95">UX</div>
        <h1 className="font-extrabold text-sm tracking-tight">UXMate Pro</h1>
        {isDevMode && <button onClick={() => setIsDebugOpen(true)} className="ml-auto p-1.5 rounded bg-red-50 text-red-500"><IconBug className="w-4 h-4" /></button>}
      </header>

      <div className="flex-1 flex flex-col md:flex-row overflow-hidden max-w-[1600px] mx-auto w-full md:p-6 md:gap-6 relative">
        <Sidebar 
          state={state} activeProject={activeProject}
          onOpenCreateModal={() => setIsCreateModalOpen(true)}
          switchProject={(id) => { setState(prev => ({ ...prev, activeProjectId: id })); setShowMobileProjects(false); }}
          deleteProject={deleteProject} duplicateProject={duplicateProject}
          onExport={setExportProject}
          mobileOpen={showMobileProjects} onCloseMobile={() => setShowMobileProjects(false)}
          currentStepId={activeProject?.currentStepId || 'problem'}
          onStepSelect={(id) => { if(activeProject) updateProject(activeProject.id, { currentStepId: id }); setShowMobileProjects(false); }}
        />

        <Workspace 
          project={activeProject} 
          updateProject={updateProject} 
          updateStepData={updateStepData}
          restoreProjectVersion={(v) => { if(activeProject) updateProject(activeProject.id, { notes: v.notes, steps: v.stepData || activeProject.steps }); setToast({ message: 'Restored history version!', type: 'success' }); }}
          deleteAsset={(idx) => { if(activeProject) { const a = [...activeProject.assets]; a.splice(idx, 1); updateProject(activeProject.id, { assets: a }); setToast({ message: 'Artifact removed', type: 'info' }); } }}
          onReplaceAsset={() => {}} 
          isGuideOpen={isGuideOpen}
          setIsGuideOpen={setIsGuideOpen}
          onExport={setExportProject} 
          onUploadAsset={handleAssetUpload}
          currentStepId={activeProject?.currentStepId || 'problem'}
          onStepSelect={(id) => { if(activeProject) updateProject(activeProject.id, { currentStepId: id }); }}
        />
      </div>

      {/* Thumb-Optimized Mobile Navigation Bar */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 h-[80px] glass-nav border-t border-slate-200 flex items-center justify-around px-8 pb-[env(safe-area-inset-bottom)] z-50 shadow-sheet">
        <NavButton active={showMobileProjects} icon={IconMenu} label="Stages" onClick={() => { setShowMobileProjects(!showMobileProjects); setIsGuideOpen(false); }} />

        {/* Central Ergonomic Action */}
        <button 
          onClick={() => setIsCreateModalOpen(true)} 
          className="w-16 h-16 -mt-12 bg-slate-900 rounded-3xl text-white shadow-fab flex items-center justify-center active:scale-90 transition-transform border-4 border-white"
        >
          <IconPlus className="w-8 h-8" />
        </button>

        <NavButton active={isGuideOpen} icon={IconLayout} label="Toolkit" onClick={() => { setIsGuideOpen(!isGuideOpen); setShowMobileProjects(false); }} />
      </nav>

      <Tour />
      <CreateProjectModal isOpen={isCreateModalOpen} onClose={() => setIsCreateModalOpen(false)} onCreate={handleCreateProject} />
      <ExportModal 
        project={exportProject} 
        isOpen={!!exportProject} 
        onClose={() => setExportProject(null)} 
        onUpdateProject={updateProject} 
      />
      <ConfirmModal isOpen={confirmConfig.isOpen} title={confirmConfig.title} message={confirmConfig.message} onConfirm={confirmConfig.onConfirm} onClose={() => setConfirmConfig(prev => ({ ...prev, isOpen: false }))} />
      {toast && <Toast message={toast.message} type={toast.type} onUndo={toast.onUndo} onClose={() => setToast(null)} />}

      {isDebugOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4">
           <div className="bg-white rounded-[2rem] w-full max-w-lg h-[60vh] flex flex-col overflow-hidden shadow-2xl">
              <div className="p-6 border-b flex justify-between items-center bg-slate-950 text-white">
                <h2 className="font-black text-sm uppercase tracking-widest">System Debug</h2>
                <button onClick={() => setIsDebugOpen(false)}><IconClose className="w-6 h-6"/></button>
              </div>
              <pre className="flex-1 overflow-auto bg-slate-900 text-emerald-400 p-6 text-[10px] font-mono leading-relaxed">{JSON.stringify(state, null, 2)}</pre>
           </div>
        </div>
      )}
    </div>
  );
};

const NavButton = ({ active, icon: Icon, label, onClick }: any) => (
  <button onClick={onClick} className={`flex flex-col items-center gap-1.5 transition-all active:scale-95 ${active ? 'text-blue-600' : 'text-slate-400'}`}>
    <div className={`p-2 rounded-2xl transition-colors ${active ? 'bg-blue-50' : ''}`}>
      <Icon className="w-5 h-5" />
    </div>
    <span className="text-[10px] font-black uppercase tracking-[0.1em]">{label}</span>
  </button>
);

export default App;

import { Project, Asset, ExportConfig, CustomSection } from "../types";
import { STAGES } from "../constants";

function escapeHtml(s: string) {
  return (s || '').toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

export function parseMarkdown(text: string): string {
  if (!text) return '';
  let html = escapeHtml(text);
  html = html.replace(/^### (.*$)/gim, '<h3 style="margin-top: 2rem; margin-bottom: 0.75rem; font-weight: 800; color: #0f172a; font-size: 1.25rem;">$1</h3>');
  html = html.replace(/^## (.*$)/gim, '<h2 style="margin-top: 3rem; margin-bottom: 1.25rem; font-weight: 900; color: #0f172a; font-size: 1.75rem; border-bottom: 2px solid #f1f5f9; padding-bottom: 0.75rem;">$1</h2>');
  html = html.replace(/\*\*(.*?)\*\*/g, '<strong style="color: #0f172a; font-weight: 700;">$1</strong>');

  const lines = html.split('\n');
  let inList = false;
  const processedLines = lines.map(line => {
    const listMatch = line.match(/^[-*] (.*)/);
    if (listMatch) {
      const content = listMatch[1];
      if (!inList) {
        inList = true;
        return `<ul style="margin-bottom: 2rem; padding-left: 1.5rem; list-style-type: disc;"><li style="margin-bottom: 0.5rem;">${content}</li>`;
      }
      return `<li style="margin-bottom: 0.5rem;">${content}</li>`;
    } else {
      if (inList) {
        inList = false;
        return `</ul>${line}<br>`;
      }
      return line + '<br>';
    }
  });

  html = processedLines.join('');
  return html;
}

function getAssetHtml(assets: Asset[], showAssets: boolean) {
  if (!showAssets || !assets || assets.length === 0) return '';
  return `
    <div class="assets-grid">
      ${assets.map(a => {
         const displayUrl = a.url || a.dataURL;
         if (!a.type.startsWith('image') || !displayUrl) return '';
         return `
           <div class="asset-item">
             <div class="asset-image-container">
               <img src="${displayUrl}" alt="${escapeHtml(a.name)}" />
             </div>
             ${a.caption ? `<div class="asset-caption">${escapeHtml(a.caption)}</div>` : ''}
           </div>
         `;
      }).join('')}
    </div>
  `;
}

function getTOCHtml(project: Project, config: ExportConfig) {
  if (!config.showTOC) return '';
  const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
  const customSections = config.customSections || [];

  const links = order.map(id => {
    const stage = STAGES.find(s => s.id === id);
    const custom = customSections.find(cs => cs.id === id);
    if (stage && !config.excludedSteps.includes(id)) {
      return `<li><a href="#section-${id}"><span>${escapeHtml(stage.label.replace(/^\d+\.\s/, ''))}</span><span class="dots"></span></a></li>`;
    }
    if (custom) {
      return `<li><a href="#section-${custom.id}"><span>${escapeHtml(custom.title)}</span><span class="dots"></span></a></li>`;
    }
    return '';
  }).filter(Boolean).join('');

  if (!links) return '';

  return `
    <nav class="toc-container">
      <h2 style="font-size: 2rem; font-weight: 900; margin-bottom: 3rem; color: #0f172a;">Project Milestones</h2>
      <ul class="toc-list">
        ${links}
      </ul>
    </nav>
  `;
}

export function generateCaseStudyHtml(project: Project): string {
  const config: ExportConfig = project.exportConfig || {
    theme: 'modern',
    primaryColor: '#3B82F6',
    fontFamily: 'Inter',
    showCover: true,
    showTOC: true,
    showAssets: true,
    designerName: '',
    designerRole: 'UX Designer',
    excludedSteps: []
  };

  const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
  const customSections = config.customSections || [];

  const sectionsHtml = order.map((id, index) => {
    const stage = STAGES.find(s => s.id === id);
    if (stage) {
      if (config.excludedSteps.includes(id)) return '';
      const stepData = project.steps?.[id] || { notes: '', isComplete: false };
      const rawContent = config.customOverrides?.[id] || stepData.notes || (id === 'problem' ? project.notes : '');
      const stepAssets = project.assets.filter(a => (a.stepId === id) || (id === 'problem' && !a.stepId));
      if (!rawContent && stepAssets.length === 0) return '';
      return `
        <section class="step-section" id="section-${id}">
          <div class="step-header">
            <span class="step-num" style="background: ${config.primaryColor};">${index + 1}</span>
            <h2 class="step-title">${escapeHtml(stage.label.replace(/^\d+\.\s/, ''))}</h2>
          </div>
          <div class="step-content">
            ${rawContent ? `<div class="step-notes">${parseMarkdown(rawContent)}</div>` : ''}
            ${getAssetHtml(stepAssets, config.showAssets)}
          </div>
        </section>
      `;
    }
    const custom = customSections.find(cs => cs.id === id);
    if (custom) {
      return `
        <section class="step-section" id="section-${custom.id}">
          <div class="step-header">
            <span class="step-num" style="background: ${config.primaryColor};">${index + 1}</span>
            <h2 class="step-title">${escapeHtml(custom.title)}</h2>
          </div>
          <div class="step-content">
            <div class="step-notes">${parseMarkdown(custom.content)}</div>
          </div>
        </section>
      `;
    }
    return '';
  }).join('');

  const fontStack = config.fontFamily === 'Serif' ? 'Georgia, serif' : config.fontFamily === 'Mono' ? 'monospace' : "'Inter', sans-serif";

  return `
  <!DOCTYPE html>
  <html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>${escapeHtml(project.title)}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

      * { box-sizing: border-box; }

      body {
        font-family: ${fontStack};
        color: #1e293b;
        line-height: 1.6;
        margin: 0;
        background: #ffffff;
        -webkit-print-color-adjust: exact;
      }

      .document-wrapper {
        max-width: 1000px;
        margin: 0 auto;
        padding: 100px 50px;
      }

      .cover {
        min-height: 85vh;
        display: ${config.showCover ? 'flex' : 'none'};
        flex-direction: column;
        justify-content: center;
        border-left: 24px solid ${config.primaryColor};
        padding-left: 80px;
        margin-bottom: 120px;
        page-break-after: always;
      }

      .cover h1 {
        font-size: clamp(4rem, 10vw, 7rem);
        margin: 0;
        font-weight: 900;
        line-height: 1;
        letter-spacing: -0.04em;
        color: #0f172a;
      }

      .cover p {
        font-size: 1.75rem;
        color: #64748b;
        margin-top: 2rem;
        max-width: 700px;
        font-weight: 500;
      }

      .toc-container {
        margin-bottom: 150px;
        page-break-after: always;
      }

      .toc-list { list-style: none; padding: 0; margin: 0; }
      .toc-list li { margin-bottom: 1.5rem; font-size: 1.25rem; font-weight: 600; }
      .toc-list a { text-decoration: none; color: #475569; display: flex; align-items: center; }
      .toc-list .dots { flex: 1; border-bottom: 2px dotted #e2e8f0; margin: 0 1.5rem; }

      .step-section {
        margin-bottom: 160px;
        page-break-inside: avoid;
      }

      .step-header {
        display: flex;
        align-items: center;
        gap: 2rem;
        margin-bottom: 3rem;
      }

      .step-num {
        color: white;
        width: 56px;
        height: 56px;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 18px;
        font-size: 1.25rem;
        font-weight: 900;
      }

      .step-title {
        font-size: 3rem;
        margin: 0;
        font-weight: 900;
        letter-spacing: -0.03em;
        color: #0f172a;
      }

      .step-notes {
        font-size: 1.25rem;
        color: #334155;
        line-height: 1.8;
      }

      .assets-grid {
        display: grid;
        grid-template-columns: 1fr;
        gap: 3rem;
        margin: 4rem 0;
      }

      .asset-item {
        border-radius: 32px;
        overflow: hidden;
        border: 1px solid #f1f5f9;
        background: #f8fafc;
      }

      .asset-image-container {
        padding: 40px;
        display: flex;
        justify-content: center;
        background: #f8fafc;
      }

      .asset-item img {
        max-width: 100%;
        border-radius: 12px;
        box-shadow: 0 20px 50px rgba(0,0,0,0.08);
      }

      .asset-caption {
        padding: 2rem;
        background: white;
        font-size: 1rem;
        color: #64748b;
        border-top: 1px solid #f1f5f9;
        font-style: italic;
      }

      .designer-info { margin-top: 100px; }
      .designer-name { font-size: 1.75rem; font-weight: 900; color: #0f172a; }
      .designer-role { 
        font-size: 1rem; 
        font-weight: 800; 
        color: ${config.primaryColor}; 
        text-transform: uppercase; 
        letter-spacing: 0.3em; 
        margin-top: 0.5rem; 
      }

      @media print {
        .document-wrapper { padding: 0; max-width: 100%; }
        .cover { min-height: 95vh; padding-left: 60px; }
      }
    </style>
  </head>
  <body>
    <div class="document-wrapper">
      <div class="cover">
        <div style="font-size: 0.875rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.4em; color: ${config.primaryColor}; margin-bottom: 2rem;">Professional UX Portfolio</div>
        <h1>${escapeHtml(project.title)}</h1>
        <p>${escapeHtml(project.desc)}</p>
        <div class="designer-info">
          <div class="designer-name">${escapeHtml(config.designerName || 'UX Designer')}</div>
          <div class="designer-role">${escapeHtml(config.designerRole || 'Senior Product Designer')}</div>
        </div>
      </div>

      ${getTOCHtml(project, config)}

      <div class="content">
        ${sectionsHtml}
      </div>
    </div>
  </body>
  </html>
  `;
}

import React, { ButtonHTMLAttributes, forwardRef } from 'react';

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'ghost' | 'danger' | 'outline';
  size?: 'sm' | 'md' | 'lg';
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}, ref) => {
  const baseStyles = "inline-flex items-center justify-center font-bold rounded-2xl transition-premium focus:outline-none focus-visible:ring-4 focus-visible:ring-blue-500/20 active:scale-95 touch-manipulation select-none";

  const variants = {
    primary: "bg-slate-900 text-white hover:bg-black shadow-lg shadow-slate-900/10",
    ghost: "bg-transparent text-slate-500 hover:bg-slate-100 hover:text-slate-900",
    outline: "bg-white border-2 border-slate-100 text-slate-700 hover:border-slate-300 hover:bg-slate-50",
    danger: "bg-red-50 text-red-600 hover:bg-red-600 hover:text-white border-2 border-red-100"
  };

  const sizes = {
    sm: "text-[10px] px-4 py-2 min-h-[40px] tracking-widest uppercase",
    md: "text-sm px-6 py-3 min-h-[48px]", 
    lg: "text-base px-10 py-4 min-h-[56px] shadow-fab"
  };

  return (
    <button 
      ref={ref}
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`} 
      {...props}
    >
      {children}
    </button>
  );
});

Button.displayName = 'Button';

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion, ExportConfig, Asset, CustomSection } from '../types';
import { STAGES, TEMPLATES } from '../constants';
import { Button } from './ui/Button';
import { IconDownload, IconTrash, IconFile, IconReplace, IconCheck, IconArrowRight, IconLayout, IconPlus, IconEye, IconEdit, IconChevronDown, IconClose } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
