interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  isGuideOpen: boolean;
  setIsGuideOpen: (open: boolean) => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  isGuideOpen,
  setIsGuideOpen,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [activeMobileTab, setActiveMobileTab] = useState<'strategy' | 'evidence'>('strategy');
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [showCelebration, setShowCelebration] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [exportEditMode, setExportEditMode] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  const phaseTemplates = TEMPLATES.filter(t => t.category === currentStage.templateCategory || t.key === currentStage.id);

  useEffect(() => {
    if (project && project.steps) {
      const stepData = project.steps[currentStepId] || { notes: '', isComplete: false };
      let externalNotes = stepData.notes;
      if (currentStepId === 'problem' && !externalNotes && project.notes) {
        externalNotes = project.notes;
      }
      if (externalNotes !== notesRef.current) {
        setNotes(externalNotes);
        notesRef.current = externalNotes;
      }
    }
  }, [project?.id, currentStepId, project?.steps?.[currentStepId]?.notes]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project || !project.steps) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps[currentStepId]?.isComplete || false;
    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project || !project.steps) return;
    const isCurrentlyComplete = project.steps[currentStepId]?.isComplete || false;
    const nextCompleteState = !isCurrentlyComplete;
    if (nextCompleteState) {
      setShowCelebration(true);
      setTimeout(() => setShowCelebration(false), 3000);
    }
    updateStepData(currentStepId, { notes, isComplete: nextCompleteState });
  };

  const handleInsert = (content: string) => {
    const newNotes = notes.trim() ? notes + "\n\n" + content : content;
    setNotes(newNotes);
    notesRef.current = newNotes;
    setSaveStatus('modified');
    handleSave();
  };

  const updateExportConfig = (updates: Partial<ExportConfig>) => {
    if (!project) return;
    const current = project.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: [],
      sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id),
      customSections: []
    };
    updateProject(project.id, { exportConfig: { ...current, ...updates } });
  };

  const toggleSectionExcluded = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.excludedSteps || [];
    const next = current.includes(id) ? current.filter(x => x !== id) : [...current, id];
    updateExportConfig({ excludedSteps: next });
  };

  const moveSection = (id: string, direction: 'up' | 'down') => {
    if (!project) return;
    const order = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    const index = order.indexOf(id);
    if (index === -1) return;
    const newOrder = [...order];
    if (direction === 'up' && index > 0) {
      [newOrder[index], newOrder[index - 1]] = [newOrder[index - 1], newOrder[index]];
    } else if (direction === 'down' && index < newOrder.length - 1) {
      [newOrder[index], newOrder[index + 1]] = [newOrder[index + 1], newOrder[index]];
    }
    updateExportConfig({ sectionOrder: newOrder });
  };

  const updateOverride = (id: string, content: string) => {
    if (!project) return;
    const currentOverrides = project.exportConfig?.customOverrides || {};
    updateExportConfig({ customOverrides: { ...currentOverrides, [id]: content } });
  };

  const addCustomSection = () => {
    if (!project) return;
    const id = 'custom_' + Date.now();
    const newSection: CustomSection = { id, title: 'New Custom Section', content: '', showAssets: false };
    const currentSections = project.exportConfig?.customSections || [];
    const currentOrder = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    updateExportConfig({ 
      customSections: [...currentSections, newSection],
      sectionOrder: [...currentOrder, id]
    });
  };

  const updateCustomSection = (id: string, updates: Partial<CustomSection>) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const next = current.map(s => s.id === id ? { ...s, ...updates } : s);
    updateExportConfig({ customSections: next });
  };

  const removeCustomSection = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const nextSections = current.filter(s => s.id !== id);
    const currentOrder = project.exportConfig?.sectionOrder || [];
    const nextOrder = currentOrder.filter(oid => oid !== id);
    updateExportConfig({ customSections: nextSections, sectionOrder: nextOrder });
  };

  const handleAssetCaptionChange = (index: number, caption: string) => {
    if (!project) return;
    const updatedAssets = [...project.assets];
    updatedAssets[index] = { ...updatedAssets[index], caption };
    updateProject(project.id, { assets: updatedAssets });
  };

  if (!project) return null;

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = project.steps ? Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100) : 0;
  const stepAssets = project.assets ? project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) : [];

  if (currentStepId === 'casestudy') {
    const config = project.exportConfig || { theme: 'modern', primaryColor: '#3B82F6', fontFamily: 'Inter', showCover: true, showTOC: true, showAssets: true, designerName: '', designerRole: 'UX Designer', excludedSteps: [], sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id), customSections: [] };
    const previewHtml = generateFullHtml(project, true);
    const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);

    return (
      <main className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${className}`}>
        {/* Export Studio Header */}
        <div className="bg-white border-b border-slate-200 p-6 md:px-10 flex justify-between items-center shrink-0 pt-safe">
          <div className="flex items-center gap-6">
            <button onClick={() => onStepSelect(STAGES[STAGES.length - 2].id)} className="p-3 -ml-4 text-slate-400 hover:text-slate-900 active:scale-95 transition-premium"><IconArrowRight className="w-6 h-6 rotate-180" /></button>
            <div className="flex flex-col">
               <span className="label-caps text-blue-600 mb-1">Final Phase</span>
               <h1 className="text-2xl font-black text-slate-900 leading-none">Export Studio</h1>
            </div>
          </div>
          <div className="flex gap-3">
            <Button onClick={() => setExportEditMode(!exportEditMode)} variant="outline" className="rounded-full">
              {exportEditMode ? <><IconEye className="w-4 h-4 mr-2" /> View</> : <><IconEdit className="w-4 h-4 mr-2" /> Build</>}
            </Button>
            <Button onClick={() => onExport(project)} size="md" className="bg-blue-600 hover:bg-blue-700 text-white rounded-full px-8 shadow-fab transition-premium">
              <IconDownload className="w-4 h-4 mr-2" /> Download Case Study
            </Button>
          </div>
        </div>

        <div className="flex-1 flex flex-col lg:grid lg:grid-cols-12 gap-0 lg:gap-8 overflow-hidden p-0 lg:p-8">
          {/* Controls Panel */}
          <div className="lg:col-span-4 bg-white lg:border lg:border-slate-200 lg:rounded-3xl p-8 shadow-soft flex flex-col gap-10 overflow-y-auto max-h-[35vh] lg:max-h-full">
             <section>
                <div className="flex items-center justify-between mb-6">
                   <h3 className="label-caps text-slate-400">Section Flow</h3>
                   <button onClick={addCustomSection} className="text-[10px] font-black uppercase text-blue-600 hover:underline tracking-widest">+ Custom</button>
                </div>
                <div className="space-y-3">
                   {order.map((oid) => {
                     const stage = STAGES.find(s => s.id === oid);
                     const custom = config.customSections?.find(cs => cs.id === oid);
                     const isExcluded = config.excludedSteps.includes(oid);
                     if (!stage && !custom) return null;
                     return (
                       <div key={oid} className={`group relative flex items-center justify-between p-4 rounded-2xl border transition-premium ${isExcluded ? 'bg-slate-50 text-slate-300 border-slate-100 opacity-60' : 'bg-white border-slate-200 text-slate-900 hover:border-blue-400'}`}>
                          <div className="flex items-center gap-4 truncate">
                             <div className="flex flex-col gap-1 shrink-0">
                                <button onClick={() => moveSection(oid, 'up')} className="p-1 hover:text-blue-500 transition-colors"><IconChevronDown className="w-3.5 h-3.5 rotate-180" /></button>
                                <button onClick={() => moveSection(oid, 'down')} className="p-1 hover:text-blue-500 transition-colors"><IconChevronDown className="w-3.5 h-3.5" /></button>
                             </div>
                             <span className="text-xl shrink-0">{stage?.icon || '📄'}</span>
                             <span className="text-xs font-black truncate">{stage?.label.split('. ')[1] || custom?.title}</span>
                          </div>
                          <div className="flex items-center gap-2">
                             <button onClick={() => toggleSectionExcluded(oid)} className={`p-2 rounded-xl transition-colors ${isExcluded ? 'text-emerald-500 hover:bg-emerald-50' : 'text-slate-300 hover:text-red-500 hover:bg-red-50'}`}>
                                {isExcluded ? <IconPlus className="w-4 h-4" /> : <IconClose className="w-4 h-4" />}
                             </button>
                          </div>
                       </div>
                     );
                   })}
                </div>
             </section>

             <section>
                <h3 className="label-caps text-slate-400 mb-6">Branding System</h3>
                <div className="space-y-6">
                   <div className="flex flex-col gap-2">
                      <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Accent Color</label>
                      <div className="flex gap-4 items-center">
                         <input type="color" className="w-12 h-12 rounded-2xl cursor-pointer bg-white border-4 border-slate-100 shadow-sm" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                         <input type="text" className="flex-1 bg-slate-50 border border-slate-100 rounded-xl px-4 py-3 text-xs font-mono uppercase font-bold text-slate-600 focus:ring-4 focus:ring-blue-500/10 outline-none" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                      </div>
                   </div>
                   <div className="flex flex-col gap-2">
                      <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Typography</label>
                      <select 
                        className="w-full text-xs font-bold p-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/10 appearance-none" 
                        value={config.fontFamily} 
                        onChange={e => updateExportConfig({ fontFamily: e.target.value as any })}
                      >
                         <option value="Inter">Modern Sans (Inter)</option>
                         <option value="Serif">Classic Serif (Georgia)</option>
                         <option value="Mono">Clean Monospace</option>
                      </select>
                   </div>
                </div>
             </section>
          </div>

          {/* Builder Canvas Area */}
          <div className="lg:col-span-8 bg-slate-100 flex-1 flex flex-col p-4 lg:p-0 overflow-hidden relative">
             <div className="w-full h-full bg-white shadow-2xl lg:rounded-3xl overflow-hidden border border-slate-200 flex flex-col relative">
                {exportEditMode ? (
                  <div className="flex-1 overflow-y-auto p-12 lg:p-20 bg-white flex flex-col gap-20 max-w-5xl mx-auto w-full selection:bg-blue-100">
                    {/* WYSIWYG COVER */}
                    <div className="border-l-[24px] pl-20 py-20 flex flex-col gap-10 group relative" style={{ borderColor: config.primaryColor }}>
                       <div className="text-sm font-black uppercase tracking-[0.4em]" style={{ color: config.primaryColor }}>UX Case Study Portfolio</div>
                       <input 
                         className="text-7xl font-black text-slate-900 border-none outline-none p-0 bg-transparent w-full tracking-tightest leading-none focus:ring-0"
                         value={project.title}
                         onChange={(e) => updateProject(project.id, { title: e.target.value })}
                       />
                       <textarea 
                         className="text-2xl text-slate-400 leading-relaxed border-none outline-none p-0 bg-transparent w-full resize-none font-medium focus:ring-0"
                         rows={2}
                         value={project.desc}
                         onChange={(e) => updateProject(project.id, { desc: e.target.value })}
                       />
                       <div className="flex flex-col gap-2 mt-20">
                         <input 
                            className="text-3xl font-black text-slate-900 border-none outline-none p-0 bg-transparent w-full focus:ring-0"
                            value={config.designerName}
                            placeholder="Your Name"
                            onChange={(e) => updateExportConfig({ designerName: e.target.value })}
                         />
                         <input 
                            className="text-sm font-black uppercase tracking-[0.3em] border-none outline-none p-0 bg-transparent w-full focus:ring-0"
                            style={{ color: config.primaryColor }}
                            value={config.designerRole}
                            placeholder="Your Role"
                            onChange={(e) => updateExportConfig({ designerRole: e.target.value })}
                         />
                       </div>
                    </div>

                    {/* WYSIWYG SECTIONS */}
                    {order.map((oid) => {
                       const stage = STAGES.find(s => s.id === oid);
                       const custom = config.customSections?.find(cs => cs.id === oid);
                       if (config.excludedSteps.includes(oid)) return null;
                       const content = custom ? custom.content : (config.customOverrides?.[oid] || project.steps[oid]?.notes || (oid === 'problem' ? project.notes : ''));

                       return (
                         <div key={oid} className="flex flex-col gap-8 p-10 rounded-[3rem] bg-slate-50/40 border border-slate-100 hover:border-blue-200 transition-premium group relative">
                            <div className="flex items-center gap-6">
                               <div className="w-14 h-14 rounded-2xl bg-blue-600 text-white flex items-center justify-center font-black text-2xl shadow-lg" style={{ backgroundColor: config.primaryColor }}>
                                  {order.indexOf(oid) + 1}
                               </div>
                               {custom ? (
                                  <input 
                                    className="text-4xl font-black text-slate-900 bg-transparent border-none outline-none p-0 flex-1 focus:ring-0 tracking-tightest"
                                    value={custom.title}
                                    onChange={(e) => updateCustomSection(oid, { title: e.target.value })}
                                  />
                               ) : (
                                  <h2 className="text-4xl font-black text-slate-900 tracking-tightest">{stage?.label.split('. ')[1]}</h2>
                               )}
                            </div>
                            <textarea 
                               className="w-full min-h-[250px] bg-white border border-slate-200 rounded-[2rem] p-10 text-slate-800 leading-relaxed text-xl focus:ring-8 focus:ring-blue-500/5 outline-none transition-premium shadow-soft font-sans"
                               value={content}
                               placeholder={`Type content here... Use **bold** or - lists.`}
                               onChange={(e) => custom ? updateCustomSection(oid, { content: e.target.value }) : updateOverride(oid, e.target.value)}
                            />
                            <div className="absolute top-10 right-10 text-[9px] font-black text-slate-300 uppercase tracking-widest opacity-0 group-hover:opacity-100">Live Editor</div>
                         </div>
                       );
                    })}

                    <div className="py-24 flex justify-center">
                       <Button onClick={addCustomSection} variant="outline" className="rounded-full border-dashed border-2 px-12 py-8 text-slate-400 hover:border-blue-500 hover:text-blue-500 hover:bg-blue-50/50">
                          <IconPlus className="w-6 h-6 mr-3" /> Add Custom Project Section
                       </Button>
                    </div>
                  </div>
                ) : (
                  <iframe srcDoc={previewHtml} className="w-full h-full border-0" sandbox="allow-same-origin" />
                )}
             </div>
          </div>
        </div>
      </main>
    );
  }

  // STANDARD WORKSPACE (PHASES)
  return (
    <main className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${className}`} role="main">
      {/* Verification Celebration */}
      {showCelebration && (
        <div className="fixed inset-0 pointer-events-none z-[110] flex items-center justify-center animate-out fade-out duration-1000 delay-2000">
           <div className="bg-white/95 backdrop-blur-2xl p-12 rounded-[3rem] shadow-fab border border-blue-100 flex flex-col items-center animate-in zoom-in-95 duration-500">
              <span className="text-7xl mb-6">🎯</span>
              <h3 className="text-3xl font-black text-slate-900 tracking-tightest">Milestone Secured</h3>
              <p className="text-slate-500 font-bold text-lg mt-2">Process successfully validated.</p>
           </div>
        </div>
      )}

      {/* Main Workspace Header */}
      <div className="bg-white border-b border-slate-200 p-6 md:px-10 shadow-sm flex flex-col gap-4 shrink-0 pt-safe">
        <div className="flex justify-between items-center">
          <div className="min-w-0">
            <div className="flex items-center gap-3 mb-2">
              <span className="label-caps text-blue-600 px-2 py-1 bg-blue-50 rounded-lg">Milestone {currentStepIndex + 1}</span>
              {isStepComplete && <span className="bg-emerald-50 text-emerald-600 text-[10px] font-black px-3 py-1 rounded-lg uppercase tracking-widest flex items-center gap-2"><IconCheck className="w-3 h-3" /> Verified</span>}
            </div>
            <h1 className="heading-section text-slate-900 truncate">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <div className="flex items-center gap-4">
             <button onClick={() => setIsPreviewMode(!isPreviewMode)} className={`p-3 rounded-2xl border transition-premium active:scale-90 ${isPreviewMode ? 'bg-slate-900 text-white border-slate-900 shadow-glow' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>
                <IconEye className="w-6 h-6" />
             </button>
             <ProgressRing progress={progress} radius={28} stroke={4} className="text-blue-600" />
          </div>
        </div>

        {/* Responsive Tab Switcher (Mobile Only) */}
        <div className="md:hidden flex bg-slate-100 p-1.5 rounded-[2rem]">
          <button onClick={() => setActiveMobileTab('strategy')} className={`flex-1 flex items-center justify-center gap-3 py-4 text-[10px] font-black uppercase tracking-widest rounded-2xl transition-premium active:scale-95 ${activeMobileTab === 'strategy' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}>
            <IconFile className="w-4 h-4" /> Strategy
          </button>
          <button onClick={() => setActiveMobileTab('evidence')} className={`flex-1 flex items-center justify-center gap-3 py-4 text-[10px] font-black uppercase tracking-widest rounded-2xl transition-premium active:scale-95 ${activeMobileTab === 'evidence' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}>
            <IconLayout className="w-4 h-4" /> Proof <span className="bg-slate-100 text-slate-600 w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold">{stepAssets.length}</span>
          </button>
        </div>
      </div>

      {/* Editor & Assets Content Grid */}
      <div className="flex-1 flex flex-col md:grid md:grid-cols-2 gap-0 md:gap-8 overflow-hidden p-0 md:p-8">
        {/* Strategy Editor Pane */}
        <div className={`flex flex-col min-h-0 flex-1 h-full bg-white md:bg-transparent transition-premium ${activeMobileTab === 'strategy' ? 'translate-x-0' : '-translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-[2.5rem] shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex flex-col border-b border-slate-100 bg-slate-50/30">
              <div className="flex items-center justify-between px-8 py-5">
                 <button onClick={() => setIsGuideOpen(true)} className="bg-slate-900 text-white rounded-full px-6 py-3 text-[10px] font-black uppercase tracking-widest flex items-center shadow-fab active:scale-95 transition-premium">
                    <IconLayout className="w-4 h-4 mr-3" /> Designer Toolkit
                 </button>
                 <div className={`label-caps ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                     {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Success' : ''}
                 </div>
              </div>

              {phaseTemplates.length > 0 && !isPreviewMode && (
                <div className="px-8 pb-5 flex gap-3 overflow-x-auto hide-scrollbar">
                   {phaseTemplates.map(t => (
                     <button key={t.key} onClick={() => handleInsert(t.content)} className="px-5 py-2.5 bg-white border border-slate-200 rounded-full text-[10px] font-black text-slate-600 hover:border-blue-500 hover:text-blue-600 transition-premium whitespace-nowrap active:scale-95 shadow-sm">+ {t.label}</button>
                   ))}
                </div>
              )}
            </div>

            <div className="flex-1 relative overflow-hidden">
              {isPreviewMode ? (
                <div className="absolute inset-0 p-10 overflow-y-auto prose prose-slate max-w-none bg-white font-sans selection:bg-blue-100">
                  <div className="text-slate-800 leading-[2]" dangerouslySetInnerHTML={{ __html: parseMarkdown(notes) }} />
                  {notes.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-200 italic"><IconFile className="w-16 h-16 mb-6 opacity-20" /> No strategy documented yet.</div>}
                </div>
              ) : (
                <textarea
                  value={notes}
                  onChange={handleNotesChange}
                  onBlur={handleSave} 
                  placeholder={`Phase Instruction: ${currentStage.help}\n\nStart typing your design rationale...`}
                  className="w-full h-full bg-white p-10 resize-none focus:outline-none text-slate-800 leading-[1.8] text-lg font-sans placeholder:text-slate-200"
                />
              )}
            </div>
          </div>
        </div>

        {/* Artifacts Pane */}
        <div className={`flex flex-col flex-1 min-h-0 h-full bg-slate-50 md:bg-transparent transition-premium ${activeMobileTab === 'evidence' ? 'translate-x-0' : 'translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:rounded-[2.5rem] shadow-soft flex-1 flex flex-col overflow-hidden">
            <div className="flex items-center justify-between px-8 py-5 border-b border-slate-100 bg-slate-50/30">
               <h3 className="label-caps text-slate-400">Project Proof</h3>
               <label className="cursor-pointer active:scale-95 transition-premium">
                  <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                  <div className="px-6 py-3 bg-white border-2 border-slate-900 text-slate-900 rounded-full text-[10px] font-black uppercase tracking-widest shadow-lg flex items-center hover:bg-slate-900 hover:text-white">
                    <IconPlus className="w-4 h-4 mr-3" /> Upload Artifact
                  </div>
               </label>
            </div>

            <div className="flex-1 overflow-y-auto p-6 md:p-10 bg-slate-50/30">
              {stepAssets.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-12">
                   <div className="w-28 h-28 rounded-[2.5rem] bg-white border border-slate-100 shadow-soft flex items-center justify-center mb-8">
                     <IconFile className="w-12 h-12 text-slate-100" />
                   </div>
                   <h4 className="text-slate-900 font-black mb-3 tracking-tightest text-xl uppercase">Vault Empty</h4>
                   <p className="text-sm text-slate-400 max-w-[240px] leading-relaxed">Visual proof makes your design rationale undeniable.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-10">
                  {[...stepAssets].reverse().map((asset, i) => {
                    const originalIdx = project.assets.indexOf(asset);
                    return (
                      <div key={i} className="bg-white border border-slate-200 rounded-[2.5rem] p-6 shadow-soft group animate-in slide-in-from-bottom-6 duration-500">
                        <div className="relative aspect-video bg-slate-50 rounded-[1.5rem] overflow-hidden mb-6 border border-slate-100 shadow-inner">
                          <img src={asset.url || asset.dataURL} className="w-full h-full object-contain" alt={asset.name} />
                          <div className="absolute top-4 right-4 flex gap-3 translate-y-2 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-premium">
                             <button onClick={() => window.open(asset.url || asset.dataURL, '_blank')} className="p-4 bg-white/95 backdrop-blur-xl rounded-2xl shadow-xl text-slate-900 active:scale-90"><IconEye className="w-5 h-5" /></button>
                             <button onClick={() => deleteAsset(originalIdx)} className="p-4 bg-white/95 backdrop-blur-xl rounded-2xl shadow-xl text-red-500 active:scale-90"><IconTrash className="w-5 h-5" /></button>
                          </div>
                        </div>
                        <div className="px-2">
                          <div className="flex justify-between items-center mb-4">
                            <h5 className="label-caps text-slate-900 truncate">{asset.name}</h5>
                            <span className="text-[10px] font-bold text-slate-300 uppercase">{new Date(asset.createdAt).toLocaleDateString()}</span>
                          </div>
                          <textarea 
                            placeholder="Add context to this artifact..." 
                            className="w-full text-base p-6 bg-slate-50 border border-slate-100 rounded-[1.5rem] outline-none focus:ring-8 focus:ring-blue-500/5 transition-premium resize-none h-32 text-slate-600 leading-relaxed font-sans"
                            value={asset.caption || ''}
                            onChange={(e) => handleAssetCaptionChange(originalIdx, e.target.value)}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Global Action Footer */}
      <div className="sticky bottom-0 md:static bg-white p-6 md:px-10 flex justify-between items-center z-50 pb-safe shadow-sheet">
         <button onClick={() => prevStep && onStepSelect(prevStep.id)} className={`flex items-center gap-3 label-caps text-slate-400 p-4 active:scale-95 transition-premium ${!prevStep && 'invisible'}`}>
           <IconArrowRight className="w-5 h-5 rotate-180" /> Back
         </button>

         <div className="flex gap-6">
            <button 
                onClick={toggleStepCompletion} 
                className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-premium active:scale-90 border-4 ${isStepComplete ? 'bg-emerald-500 border-emerald-100 text-white shadow-fab shadow-emerald-500/30' : 'bg-white border-slate-100 text-slate-200'}`}
            >
                <IconCheck className="w-8 h-8" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} size="lg" className="bg-slate-900 text-white px-12 rounded-full font-black tracking-widest uppercase text-xs active:scale-95 transition-premium">
                {nextStep ? 'Next Phase' : 'Finalize & Export'} <IconArrowRight className="w-5 h-5 ml-4" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Replace Image', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete Asset', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />

      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
      <GuideModal isOpen={isGuideOpen} onClose={() => setIsGuideOpen(false)} onInsert={handleInsert} currentStepId={currentStepId} />
    </main>
  );
};

import React, { ButtonHTMLAttributes, forwardRef } from 'react';

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'ghost' | 'danger' | 'outline';
  size?: 'sm' | 'md' | 'lg';
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  className = '', 
  ...props 
}, ref) => {
  const baseStyles = "inline-flex items-center justify-center font-black rounded-2xl transition-premium focus:outline-none focus-visible:ring-4 focus-visible:ring-blue-500/20 active:scale-95 touch-manipulation select-none";

  const variants = {
    primary: "bg-slate-900 text-white hover:bg-black shadow-lg shadow-slate-900/10",
    ghost: "bg-transparent text-slate-500 hover:bg-slate-100 hover:text-slate-900",
    outline: "bg-white border-2 border-slate-100 text-slate-700 hover:border-slate-300 hover:bg-slate-50",
    danger: "bg-red-50 text-red-600 hover:bg-red-600 hover:text-white border-2 border-red-100"
  };

  const sizes = {
    sm: "text-[10px] px-4 py-2 min-h-[40px] tracking-widest uppercase",
    md: "text-xs px-6 py-3 min-h-[48px] uppercase tracking-wider", 
    lg: "text-sm px-10 py-4 min-h-[56px] shadow-fab uppercase tracking-widest"
  };

  return (
    <button 
      ref={ref}
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${className}`} 
      {...props}
    >
      {children}
    </button>
  );
});

Button.displayName = 'Button';

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion, ExportConfig, Asset, CustomSection } from '../types';
import { STAGES, TEMPLATES } from '../constants';
import { Button } from './ui/Button';
import { IconDownload, IconTrash, IconFile, IconReplace, IconCheck, IconArrowRight, IconLayout, IconPlus, IconEye, IconEdit, IconChevronDown, IconClose } from './ui/Icons';
import { ProgressRing } from './ui/ProgressRing';
import { ContextMenu } from './ui/ContextMenu';
import { HistoryModal } from './HistoryModal';
import { GuideModal } from './GuideModal';
import { generateFullHtml } from '../utils/exporter';
import { parseMarkdown } from '../utils/pdfTemplate';

interface WorkspaceProps {
  project: Project | null;
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateStepData: (stepId: string, data: { notes: string; isComplete: boolean }) => void;
  restoreProjectVersion: (version: ProjectVersion) => void;
  deleteAsset: (index: number) => void;
  onReplaceAsset: (index: number, file: File) => void;
  onUploadAsset: (file: File) => void;
  isGuideOpen: boolean;
  setIsGuideOpen: (open: boolean) => void;
  onExport: (project: Project) => void;
  currentStepId: string;
  onStepSelect: (stepId: string) => void;
  className?: string;
}

export const Workspace: React.FC<WorkspaceProps> = ({
  project,
  updateProject,
  updateStepData,
  restoreProjectVersion,
  deleteAsset,
  onReplaceAsset,
  onUploadAsset,
  isGuideOpen,
  setIsGuideOpen,
  onExport,
  currentStepId,
  onStepSelect,
  className = '',
}) => {
  const [notes, setNotes] = useState('');
  const [activeMobileTab, setActiveMobileTab] = useState<'strategy' | 'evidence'>('strategy');
  const [isPreviewMode, setIsPreviewMode] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'idle' | 'modified'>('idle');
  const [showCelebration, setShowCelebration] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [exportEditMode, setExportEditMode] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; assetIndex: number; } | null>(null);

  const replaceInputRef = useRef<HTMLInputElement>(null);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const notesRef = useRef(notes);

  const currentStage = STAGES.find(s => s.id === currentStepId) || STAGES[0];
  const currentStepIndex = STAGES.findIndex(s => s.id === currentStepId);
  const nextStep = STAGES[currentStepIndex + 1];
  const prevStep = STAGES[currentStepIndex - 1];

  const phaseTemplates = TEMPLATES.filter(t => t.category === currentStage.templateCategory || t.key === currentStage.id);

  useEffect(() => {
    if (project && project.steps) {
      const stepData = project.steps[currentStepId] || { notes: '', isComplete: false };
      let externalNotes = stepData.notes;
      if (currentStepId === 'problem' && !externalNotes && project.notes) {
        externalNotes = project.notes;
      }
      if (externalNotes !== notesRef.current) {
        setNotes(externalNotes);
        notesRef.current = externalNotes;
      }
    }
  }, [project?.id, currentStepId, project?.steps?.[currentStepId]?.notes]);

  const handleNotesChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newVal = e.target.value;
    setNotes(newVal);
    notesRef.current = newVal;
    setSaveStatus('modified');
  };

  const handleSave = useCallback(() => {
    if (!project || !project.steps) return;
    setSaveStatus('saving');
    const currentIsComplete = project.steps[currentStepId]?.isComplete || false;
    setTimeout(() => {
      updateStepData(currentStepId, { notes: notesRef.current, isComplete: currentIsComplete });
      setSaveStatus('saved');
      setTimeout(() => setSaveStatus('idle'), 2000);
    }, 400);
  }, [project, currentStepId, updateStepData]);

  useEffect(() => {
    const intervalId = setInterval(() => { if (saveStatus === 'modified') handleSave(); }, 5000);
    return () => clearInterval(intervalId);
  }, [handleSave, saveStatus]);

  const toggleStepCompletion = () => {
    if (!project || !project.steps) return;
    const isCurrentlyComplete = project.steps[currentStepId]?.isComplete || false;
    const nextCompleteState = !isCurrentlyComplete;
    if (nextCompleteState) {
      setShowCelebration(true);
      setTimeout(() => setShowCelebration(false), 3000);
    }
    updateStepData(currentStepId, { notes, isComplete: nextCompleteState });
  };

  const handleInsert = (content: string) => {
    const newNotes = notes.trim() ? notes + "\n\n" + content : content;
    setNotes(newNotes);
    notesRef.current = newNotes;
    setSaveStatus('modified');
    handleSave();
  };

  const updateExportConfig = (updates: Partial<ExportConfig>) => {
    if (!project) return;
    const current = project.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: [],
      sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id),
      customSections: []
    };
    updateProject(project.id, { exportConfig: { ...current, ...updates } });
  };

  const toggleSectionExcluded = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.excludedSteps || [];
    const next = current.includes(id) ? current.filter(x => x !== id) : [...current, id];
    updateExportConfig({ excludedSteps: next });
  };

  const moveSection = (id: string, direction: 'up' | 'down') => {
    if (!project) return;
    const order = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    const index = order.indexOf(id);
    if (index === -1) return;
    const newOrder = [...order];
    if (direction === 'up' && index > 0) {
      [newOrder[index], newOrder[index - 1]] = [newOrder[index - 1], newOrder[index]];
    } else if (direction === 'down' && index < newOrder.length - 1) {
      [newOrder[index], newOrder[index + 1]] = [newOrder[index + 1], newOrder[index]];
    }
    updateExportConfig({ sectionOrder: newOrder });
  };

  const updateOverride = (id: string, content: string) => {
    if (!project) return;
    const currentOverrides = project.exportConfig?.customOverrides || {};
    updateExportConfig({ customOverrides: { ...currentOverrides, [id]: content } });
  };

  const addCustomSection = () => {
    if (!project) return;
    const id = 'custom_' + Date.now();
    const newSection: CustomSection = { id, title: 'New Custom Section', content: '', showAssets: false };
    const currentSections = project.exportConfig?.customSections || [];
    const currentOrder = project.exportConfig?.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);
    updateExportConfig({ 
      customSections: [...currentSections, newSection],
      sectionOrder: [...currentOrder, id]
    });
  };

  const updateCustomSection = (id: string, updates: Partial<CustomSection>) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const next = current.map(s => s.id === id ? { ...s, ...updates } : s);
    updateExportConfig({ customSections: next });
  };

  const removeCustomSection = (id: string) => {
    if (!project) return;
    const current = project.exportConfig?.customSections || [];
    const nextSections = current.filter(s => s.id !== id);
    const currentOrder = project.exportConfig?.sectionOrder || [];
    const nextOrder = currentOrder.filter(oid => oid !== id);
    updateExportConfig({ customSections: nextSections, sectionOrder: nextOrder });
  };

  const handleAssetCaptionChange = (index: number, caption: string) => {
    if (!project) return;
    const updatedAssets = [...project.assets];
    updatedAssets[index] = { ...updatedAssets[index], caption };
    updateProject(project.id, { assets: updatedAssets });
  };

  if (!project) return null;

  const isStepComplete = project.steps?.[currentStepId]?.isComplete;
  const progress = project.steps ? Math.round((STAGES.filter(s => project.steps?.[s.id]?.isComplete).length / STAGES.length) * 100) : 0;
  const stepAssets = project.assets ? project.assets.filter(a => (a.stepId === currentStepId) || (currentStepId === 'problem' && !a.stepId)) : [];

  if (currentStepId === 'casestudy') {
    const config = project.exportConfig || { theme: 'modern', primaryColor: '#3B82F6', fontFamily: 'Inter', showCover: true, showTOC: true, showAssets: true, designerName: '', designerRole: 'UX Designer', excludedSteps: [], sectionOrder: STAGES.filter(s => s.id !== 'casestudy').map(s => s.id), customSections: [] };
    const previewHtml = generateFullHtml(project, true);
    const order = config.sectionOrder || STAGES.filter(s => s.id !== 'casestudy').map(s => s.id);

    return (
      <main className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${className}`}>
        {/* Export Studio Header */}
        <div className="bg-white border-b border-slate-200 p-6 md:p-10 flex flex-col md:flex-row justify-between items-center shrink-0 pt-safe gap-4">
          <div className="flex items-center gap-6">
            <button onClick={() => onStepSelect(STAGES[STAGES.length - 2].id)} className="p-3 -ml-4 text-slate-400 hover:text-slate-900 active:scale-95 transition-premium"><IconArrowRight className="w-6 h-6 rotate-180" /></button>
            <div className="flex flex-col">
               <span className="label-caps mb-1">Portfolio Output</span>
               <h1 className="heading-section text-slate-900 leading-none">Export Studio</h1>
            </div>
          </div>
          <div className="flex gap-3 w-full md:w-auto">
            <Button onClick={() => setExportEditMode(!exportEditMode)} variant="outline" className="flex-1 md:flex-none">
              {exportEditMode ? <><IconEye className="w-4 h-4 mr-2" /> Preview</> : <><IconEdit className="w-4 h-4 mr-2" /> Edit Output</>}
            </Button>
            <Button onClick={() => onExport(project)} className="flex-1 md:flex-none bg-blue-600 hover:bg-blue-700 text-white shadow-fab">
              <IconDownload className="w-4 h-4 mr-2" /> Download Case Study
            </Button>
          </div>
        </div>

        <div className="flex-1 flex flex-col lg:grid lg:grid-cols-12 gap-0 lg:gap-10 overflow-hidden p-0 lg:p-10">
          {/* Controls Panel */}
          <div className="lg:col-span-4 bg-white lg:border lg:border-slate-200 lg:card-radius p-8 md:p-10 shadow-soft flex flex-col gap-10 overflow-y-auto max-h-[35vh] lg:max-h-full">
             <section>
                <div className="flex items-center justify-between mb-8">
                   <h3 className="label-caps">Layout Sections</h3>
                   <button onClick={addCustomSection} className="text-[11px] font-black uppercase text-blue-600 hover:underline tracking-widest">+ Add New</button>
                </div>
                <div className="space-y-3">
                   {order.map((oid) => {
                     const stage = STAGES.find(s => s.id === oid);
                     const custom = config.customSections?.find(cs => cs.id === oid);
                     const isExcluded = config.excludedSteps.includes(oid);
                     if (!stage && !custom) return null;
                     return (
                       <div key={oid} className={`group relative flex items-center justify-between p-5 rounded-2xl border transition-premium ${isExcluded ? 'bg-slate-50 text-slate-300 border-slate-100 opacity-60' : 'bg-white border-slate-200 text-slate-900 hover:border-blue-500'}`}>
                          <div className="flex items-center gap-4 truncate">
                             <div className="flex flex-col gap-1 shrink-0">
                                <button onClick={() => moveSection(oid, 'up')} className="p-1 hover:text-blue-500 transition-colors"><IconChevronDown className="w-3.5 h-3.5 rotate-180" /></button>
                                <button onClick={() => moveSection(oid, 'down')} className="p-1 hover:text-blue-500 transition-colors"><IconChevronDown className="w-3.5 h-3.5" /></button>
                             </div>
                             <span className="text-xl shrink-0">{stage?.icon || '📄'}</span>
                             <span className="text-xs font-black truncate uppercase tracking-tight">{stage?.label.split('. ')[1] || custom?.title}</span>
                          </div>
                          <div className="flex items-center gap-2">
                             <button onClick={() => toggleSectionExcluded(oid)} className={`p-2 rounded-xl transition-colors ${isExcluded ? 'text-emerald-500 hover:bg-emerald-50' : 'text-slate-300 hover:text-red-500 hover:bg-red-50'}`}>
                                {isExcluded ? <IconPlus className="w-4 h-4" /> : <IconClose className="w-4 h-4" />}
                             </button>
                          </div>
                       </div>
                     );
                   })}
                </div>
             </section>

             <section>
                <h3 className="label-caps mb-8">Personal Branding</h3>
                <div className="space-y-6">
                   <div className="flex flex-col gap-2">
                      <label className="label-caps text-[9px] ml-1">Color Palette</label>
                      <div className="flex gap-4 items-center">
                         <input type="color" className="w-12 h-12 rounded-2xl cursor-pointer bg-white border-4 border-slate-100 shadow-sm transition-premium hover:scale-105" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                         <input type="text" className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-5 py-3 text-xs font-mono uppercase font-black text-slate-600 focus:ring-4 focus:ring-blue-500/10 outline-none transition-premium" value={config.primaryColor} onChange={e => updateExportConfig({ primaryColor: e.target.value })} />
                      </div>
                   </div>
                   <div className="flex flex-col gap-2">
                      <label className="label-caps text-[9px] ml-1">Visual Tone</label>
                      <select 
                        className="w-full text-xs font-black p-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-500/10 appearance-none cursor-pointer tracking-wider" 
                        value={config.fontFamily} 
                        onChange={e => updateExportConfig({ fontFamily: e.target.value as any })}
                      >
                         <option value="Inter">Modern Professional (Inter)</option>
                         <option value="Serif">Classic Editorial (Serif)</option>
                         <option value="Mono">Tech Minimalist (Mono)</option>
                      </select>
                   </div>
                </div>
             </section>
          </div>

          {/* Builder Canvas Area */}
          <div className="lg:col-span-8 bg-slate-100 flex-1 flex flex-col p-4 lg:p-0 overflow-hidden relative">
             <div className="w-full h-full bg-white shadow-2xl lg:card-radius overflow-hidden border border-slate-200 flex flex-col relative">
                {exportEditMode ? (
                  <div className="flex-1 overflow-y-auto p-12 md:p-18 bg-white flex flex-col gap-20 max-w-4xl mx-auto w-full selection:bg-blue-100 selection:text-blue-900">
                    {/* WYSIWYG COVER */}
                    <div className="border-l-[24px] pl-16 md:pl-20 py-20 flex flex-col gap-10 group relative" style={{ borderColor: config.primaryColor }}>
                       <div className="label-caps" style={{ color: config.primaryColor }}>Designer Portfolio Deliverable</div>
                       <input 
                         className="heading-huge text-slate-900 border-none outline-none p-0 bg-transparent w-full focus:ring-0"
                         value={project.title}
                         onChange={(e) => updateProject(project.id, { title: e.target.value })}
                       />
                       <textarea 
                         className="body-large italic border-none outline-none p-0 bg-transparent w-full resize-none focus:ring-0"
                         rows={3}
                         value={project.desc}
                         onChange={(e) => updateProject(project.id, { desc: e.target.value })}
                       />
                       <div className="flex flex-col gap-2 mt-20">
                         <input 
                            className="text-3xl font-black text-slate-900 border-none outline-none p-0 bg-transparent w-full focus:ring-0 tracking-tightest"
                            value={config.designerName}
                            placeholder="Your Name"
                            onChange={(e) => updateExportConfig({ designerName: e.target.value })}
                         />
                         <input 
                            className="label-caps tracking-[0.4em] border-none outline-none p-0 bg-transparent w-full focus:ring-0"
                            style={{ color: config.primaryColor }}
                            value={config.designerRole}
                            placeholder="Your Professional Role"
                            onChange={(e) => updateExportConfig({ designerRole: e.target.value })}
                         />
                       </div>
                    </div>

                    {/* WYSIWYG SECTIONS */}
                    {order.map((oid) => {
                       const stage = STAGES.find(s => s.id === oid);
                       const custom = config.customSections?.find(cs => cs.id === oid);
                       if (config.excludedSteps.includes(oid)) return null;
                       const content = custom ? custom.content : (config.customOverrides?.[oid] || project.steps[oid]?.notes || (oid === 'problem' ? project.notes : ''));

                       return (
                         <div key={oid} className="flex flex-col gap-8 p-10 md:p-14 rounded-[3rem] bg-slate-50/40 border border-slate-100 hover:border-blue-300 transition-premium group relative">
                            <div className="flex items-center gap-8">
                               <div className="w-16 h-16 rounded-[1.5rem] bg-slate-900 text-white flex items-center justify-center font-black text-2xl shadow-lg" style={{ backgroundColor: config.primaryColor }}>
                                  {order.indexOf(oid) + 1}
                               </div>
                               {custom ? (
                                  <input 
                                    className="text-4xl font-black text-slate-900 bg-transparent border-none outline-none p-0 flex-1 focus:ring-0 tracking-tightest"
                                    value={custom.title}
                                    onChange={(e) => updateCustomSection(oid, { title: e.target.value })}
                                  />
                               ) : (
                                  <h2 className="text-4xl font-black text-slate-900 tracking-tightest uppercase">{stage?.label.split('. ')[1]}</h2>
                               )}
                            </div>
                            <textarea 
                               className="w-full min-h-[300px] bg-white border border-slate-200 rounded-[2rem] p-10 text-slate-800 leading-relaxed text-xl focus:ring-[12px] focus:ring-blue-500/5 outline-none transition-premium shadow-soft font-sans placeholder:text-slate-200"
                               value={content}
                               placeholder={`Describe the ${custom?.title || stage?.label}...`}
                               onChange={(e) => custom ? updateCustomSection(oid, { content: e.target.value }) : updateOverride(oid, e.target.value)}
                            />
                            <div className="absolute top-10 right-10 label-caps opacity-0 group-hover:opacity-100">Live Editor</div>
                         </div>
                       );
                    })}

                    <div className="py-32 flex justify-center">
                       <Button onClick={addCustomSection} variant="outline" className="rounded-full border-dashed border-2 px-12 py-10 text-slate-400 hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50/50">
                          <IconPlus className="w-6 h-6 mr-4" /> Expand Case Study Structure
                       </Button>
                    </div>
                  </div>
                ) : (
                  <iframe srcDoc={previewHtml} className="w-full h-full border-0" sandbox="allow-same-origin" />
                )}
             </div>
          </div>
        </div>
      </main>
    );
  }

  // STANDARD WORKSPACE (PHASES)
  return (
    <main className={`flex-1 flex flex-col min-w-0 h-full overflow-hidden ${className}`} role="main">
      {/* Verification Celebration */}
      {showCelebration && (
        <div className="fixed inset-0 pointer-events-none z-[110] flex items-center justify-center animate-out fade-out duration-1000 delay-2000">
           <div className="bg-white/95 backdrop-blur-2xl p-16 rounded-[4rem] shadow-fab border border-blue-100 flex flex-col items-center animate-in zoom-in-95 duration-500">
              <span className="text-8xl mb-8">💎</span>
              <h3 className="heading-section text-slate-900 text-center">Milestone Verified</h3>
              <p className="text-slate-500 font-black text-xl mt-3 uppercase tracking-widest">Process Authenticated</p>
           </div>
        </div>
      )}

      {/* Main Workspace Header */}
      <div className="bg-white border-b border-slate-200 p-6 md:p-10 shadow-sm flex flex-col gap-6 shrink-0 pt-safe">
        <div className="flex justify-between items-center">
          <div className="min-w-0">
            <div className="flex items-center gap-4 mb-3">
              <span className="label-caps text-blue-600 bg-blue-50 px-3 py-1.5 rounded-xl border border-blue-100">Step {currentStepIndex + 1}</span>
              {isStepComplete && <span className="bg-emerald-50 text-emerald-600 label-caps px-4 py-1.5 rounded-xl border border-emerald-100 flex items-center gap-3"><IconCheck className="w-3.5 h-3.5" /> Accomplished</span>}
            </div>
            <h1 className="heading-section text-slate-900 truncate leading-tight">{currentStage.label.replace(/^\d+\.\s/, '')}</h1>
          </div>
          <div className="flex items-center gap-6">
             <button onClick={() => setIsPreviewMode(!isPreviewMode)} className={`p-4 rounded-[1.5rem] border transition-premium active-scale ${isPreviewMode ? 'bg-slate-900 text-white border-slate-900 shadow-glow' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>
                <IconEye className="w-7 h-7" />
             </button>
             <ProgressRing progress={progress} radius={32} stroke={5} className="text-blue-600" />
          </div>
        </div>

        {/* Responsive Tab Switcher (Mobile Only) */}
        <div className="md:hidden flex bg-slate-100 p-2 rounded-[2.5rem]">
          <button onClick={() => setActiveMobileTab('strategy')} className={`flex-1 flex items-center justify-center gap-4 py-5 text-[11px] font-black uppercase tracking-widest rounded-[2rem] transition-premium active-scale ${activeMobileTab === 'strategy' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}>
            <IconFile className="w-5 h-5" /> Design Strategy
          </button>
          <button onClick={() => setActiveMobileTab('evidence')} className={`flex-1 flex items-center justify-center gap-4 py-5 text-[11px] font-black uppercase tracking-widest rounded-[2rem] transition-premium active-scale ${activeMobileTab === 'evidence' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}>
            <IconLayout className="w-5 h-5" /> Evidence <span className="bg-slate-100 text-slate-600 w-7 h-7 rounded-full flex items-center justify-center text-[11px] font-black">{stepAssets.length}</span>
          </button>
        </div>
      </div>

      {/* Main Content Grid */}
      <div className="flex-1 flex flex-col md:grid md:grid-cols-2 gap-0 md:gap-10 overflow-hidden p-0 md:p-10">
        {/* Strategy Editor Pane */}
        <div className={`flex flex-col min-h-0 flex-1 h-full bg-white md:bg-transparent transition-premium ${activeMobileTab === 'strategy' ? 'translate-x-0' : '-translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:card-radius shadow-soft flex-1 flex flex-col relative overflow-hidden">
            <div className="flex flex-col border-b border-slate-100 bg-slate-50/40">
              <div className="flex items-center justify-between px-10 py-6">
                 <button onClick={() => setIsGuideOpen(true)} className="bg-slate-900 text-white rounded-full px-8 py-4 label-caps flex items-center shadow-fab active-scale transition-premium hover:bg-black">
                    <IconLayout className="w-5 h-5 mr-4" /> Specialist Tools
                 </button>
                 <div className={`label-caps text-[10px] ${saveStatus === 'saved' ? 'text-emerald-500' : 'text-slate-300'}`}>
                     {saveStatus === 'saving' ? 'Syncing...' : saveStatus === 'saved' ? 'Synced' : ''}
                 </div>
              </div>

              {phaseTemplates.length > 0 && !isPreviewMode && (
                <div className="px-10 pb-6 flex gap-4 overflow-x-auto hide-scrollbar">
                   {phaseTemplates.map(t => (
                     <button key={t.key} onClick={() => handleInsert(t.content)} className="px-6 py-3 bg-white border border-slate-200 rounded-full text-[10px] font-black text-slate-600 hover:border-blue-500 hover:text-blue-600 transition-premium whitespace-nowrap active-scale shadow-sm">+ {t.label}</button>
                   ))}
                </div>
              )}
            </div>

            <div className="flex-1 relative overflow-hidden">
              {isPreviewMode ? (
                <div className="absolute inset-0 p-10 md:p-14 overflow-y-auto prose prose-slate max-w-none bg-white font-sans selection:bg-blue-100">
                  <div className="text-slate-800 leading-[2.1] text-lg font-medium" dangerouslySetInnerHTML={{ __html: parseMarkdown(notes) }} />
                  {notes.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-200 italic"><IconFile className="w-20 h-20 mb-8 opacity-20" /> No strategy defined.</div>}
                </div>
              ) : (
                <textarea
                  value={notes}
                  onChange={handleNotesChange}
                  onBlur={handleSave} 
                  placeholder={`Phase Guide: ${currentStage.help}\n\nOutline your approach here...`}
                  className="w-full h-full bg-white p-10 md:p-14 resize-none focus:outline-none text-slate-800 leading-[2] text-xl font-medium font-sans placeholder:text-slate-200"
                />
              )}
            </div>
          </div>
        </div>

        {/* Assets Pane */}
        <div className={`flex flex-col flex-1 min-h-0 h-full bg-slate-50 md:bg-transparent transition-premium ${activeMobileTab === 'evidence' ? 'translate-x-0' : 'translate-x-full md:translate-x-0 absolute md:relative opacity-0 md:opacity-100'}`}>
          <div className="bg-white md:border md:border-slate-200 md:card-radius shadow-soft flex-1 flex flex-col overflow-hidden">
            <div className="flex items-center justify-between px-10 py-6 border-b border-slate-100 bg-slate-50/40">
               <h3 className="label-caps">Process Artifacts</h3>
               <label className="cursor-pointer active-scale transition-premium">
                  <input type="file" className="hidden" accept="image/*" onChange={e => e.target.files?.[0] && onUploadAsset(e.target.files[0])} />
                  <div className="px-8 py-4 bg-white border-2 border-slate-900 text-slate-900 rounded-full label-caps shadow-lg flex items-center hover:bg-slate-900 hover:text-white">
                    <IconPlus className="w-5 h-5 mr-4" /> Add Artifact
                  </div>
               </label>
            </div>

            <div className="flex-1 overflow-y-auto p-8 md:p-12 bg-slate-50/20">
              {stepAssets.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-center p-16">
                   <div className="w-32 h-32 rounded-[3rem] bg-white border border-slate-100 shadow-soft flex items-center justify-center mb-10 transition-premium hover:rotate-3">
                     <IconFile className="w-14 h-14 text-slate-100" />
                   </div>
                   <h4 className="heading-section text-slate-300 text-xl uppercase mb-4 tracking-widest">Vault Empty</h4>
                   <p className="body-large text-slate-400 max-w-[300px]">Visual proof of your work increases the perceived value of your design solutions.</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-12">
                  {[...stepAssets].reverse().map((asset, i) => {
                    const originalIdx = project.assets.indexOf(asset);
                    return (
                      <div key={i} className="bg-white border border-slate-200 rounded-[3rem] p-8 shadow-soft group animate-in slide-in-from-bottom-8 duration-500">
                        <div className="relative aspect-video bg-slate-100 rounded-[2rem] overflow-hidden mb-8 border border-slate-100 shadow-inner">
                          <img src={asset.url || asset.dataURL} className="w-full h-full object-contain" alt={asset.name} />
                          <div className="absolute top-6 right-6 flex gap-4 translate-y-3 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-premium">
                             <button onClick={() => window.open(asset.url || asset.dataURL, '_blank')} className="p-5 bg-white/95 backdrop-blur-2xl rounded-2xl shadow-xl text-slate-900 active-scale"><IconEye className="w-6 h-6" /></button>
                             <button onClick={() => deleteAsset(originalIdx)} className="p-5 bg-white/95 backdrop-blur-2xl rounded-2xl shadow-xl text-red-500 active-scale"><IconTrash className="w-6 h-6" /></button>
                          </div>
                        </div>
                        <div className="px-2">
                          <div className="flex justify-between items-center mb-6">
                            <h5 className="label-caps text-slate-900 tracking-tight text-xs">{asset.name}</h5>
                            <span className="text-[11px] font-black text-slate-300 uppercase tracking-widest">{new Date(asset.createdAt).toLocaleDateString()}</span>
                          </div>
                          <textarea 
                            placeholder="Add strategic context to this proof..." 
                            className="w-full text-lg p-8 bg-slate-50 border border-slate-200 rounded-[2rem] outline-none focus:ring-[12px] focus:ring-blue-500/5 transition-premium resize-none h-40 text-slate-700 leading-relaxed font-sans placeholder:text-slate-300"
                            value={asset.caption || ''}
                            onChange={(e) => handleAssetCaptionChange(originalIdx, e.target.value)}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Primary Interaction Footer */}
      <div className="sticky bottom-0 md:static bg-white p-6 md:px-10 flex justify-between items-center z-50 pb-safe shadow-sheet border-t border-slate-100">
         <button onClick={() => prevStep && onStepSelect(prevStep.id)} className={`flex items-center gap-4 label-caps p-5 active-scale transition-premium ${!prevStep && 'invisible opacity-0'}`}>
           <IconArrowRight className="w-6 h-6 rotate-180" /> Back
         </button>

         <div className="flex gap-8 items-center">
            <button 
                onClick={toggleStepCompletion} 
                className={`w-18 h-18 rounded-[2rem] flex items-center justify-center transition-premium active-scale border-4 ${isStepComplete ? 'bg-emerald-500 border-emerald-100 text-white shadow-fab shadow-emerald-500/40' : 'bg-white border-slate-100 text-slate-200 hover:border-slate-300'}`}
            >
                <IconCheck className="w-10 h-10" />
            </button>
            <Button onClick={() => nextStep ? onStepSelect(nextStep.id) : onStepSelect('casestudy')} size="lg" className="bg-slate-900 text-white px-14 rounded-full shadow-fab">
                {nextStep ? 'Next Phase' : 'Compile Case Study'} <IconArrowRight className="w-6 h-6 ml-6" />
            </Button>
         </div>
      </div>

      <input type="file" ref={replaceInputRef} className="hidden" accept="image/*" onChange={e => { if (e.target.files?.[0] && replaceIndex !== null) onReplaceAsset(replaceIndex, e.target.files[0]); setReplaceIndex(null); }} />
      <ContextMenu isOpen={!!contextMenu} x={contextMenu?.x || 0} y={contextMenu?.y || 0} onClose={() => setContextMenu(null)} items={[
          { label: 'Replace Image', icon: <IconReplace className="w-4 h-4" />, onClick: () => contextMenu && (setReplaceIndex(contextMenu.assetIndex), replaceInputRef.current?.click()) },
          { label: 'Delete Asset', icon: <IconTrash className="w-4 h-4" />, danger: true, onClick: () => contextMenu && deleteAsset(contextMenu.assetIndex) }
      ]} />

      <HistoryModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} versions={project.history || []} onRestore={restoreProjectVersion} />
      <GuideModal isOpen={isGuideOpen} onClose={() => setIsGuideOpen(false)} onInsert={handleInsert} currentStepId={currentStepId} />
    </main>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, AppState } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
import { IconPlus, IconCheck, IconTrash, IconCopy, IconChevronDown, IconSearch, IconArrowRight, IconClose, IconFile, IconLayout } from './ui/Icons';

interface SidebarProps {
  state: AppState;
  onOpenCreateModal: () => void;
  switchProject: (id: string) => void;
  deleteProject: (id: string) => void;
  duplicateProject: (id: string) => void;
  onExport: (project: Project) => void;
  activeProject: Project | null;
  onStepSelect: (stepId: string) => void;
  currentStepId: string;
  className?: string;
  mobileOpen?: boolean;
  onCloseMobile?: () => void;
}

const PROJECT_ROW_HEIGHT = 80;

export const Sidebar: React.FC<SidebarProps> = ({
  state,
  onOpenCreateModal,
  switchProject,
  deleteProject,
  duplicateProject,
  activeProject,
  onStepSelect,
  currentStepId,
  className = '',
  mobileOpen = false,
  onCloseMobile
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const listRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(400);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setScrollTop(0);
    }, 200);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  useEffect(() => {
    if (listRef.current) {
      setViewportHeight(listRef.current.clientHeight);
      const ro = new ResizeObserver(() => setViewportHeight(listRef.current?.clientHeight || 400));
      ro.observe(listRef.current);
      return () => ro.disconnect();
    }
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => setScrollTop(e.currentTarget.scrollTop);

  const filteredProjects = useMemo(() => {
    const all = Object.values(state.projects) as Project[];
    const sorted = all.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    if (!debouncedSearch.trim()) return sorted;
    const lower = debouncedSearch.toLowerCase();
    return sorted.filter(p => p.title.toLowerCase().includes(lower));
  }, [state.projects, debouncedSearch]);

  const totalCount = filteredProjects.length;
  const startIndex = Math.max(0, Math.floor(scrollTop / PROJECT_ROW_HEIGHT) - 1);
  const endIndex = Math.min(totalCount, Math.ceil((scrollTop + viewportHeight) / PROJECT_ROW_HEIGHT) + 1);
  const visibleProjects = filteredProjects.slice(startIndex, endIndex);

  return (
    <aside 
      className={`
        fixed inset-0 z-[100] bg-white flex flex-col transition-transform duration-500 ease-in-out md:relative md:translate-y-0 md:inset-auto md:z-0 md:bg-transparent md:w-80 lg:w-96 md:gap-8
        ${mobileOpen ? 'translate-y-0' : 'translate-y-full md:translate-y-0'}
        ${className}
      `}
      role="complementary"
    >
        {/* Mobile Sidebar Header */}
        <div className="md:hidden pt-safe shrink-0 bg-slate-900 text-white p-8 rounded-b-[4rem] shadow-fab">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h2 className="text-3xl font-black tracking-tightest">Design Flow</h2>
              <p className="label-caps text-slate-400 mt-2">Milestones & Mapping</p>
            </div>
            <button onClick={onCloseMobile} className="w-14 h-14 rounded-3xl bg-white/10 flex items-center justify-center active-scale transition-premium">
              <IconClose className="w-7 h-7 text-white" />
            </button>
          </div>

          <div className="flex gap-4 mb-2 overflow-x-auto hide-scrollbar">
             <div className="bg-white/5 border border-white/10 rounded-[2rem] p-5 min-w-[160px]">
                <div className="label-caps text-slate-500 text-[9px]">Success Rate</div>
                <div className="text-2xl font-black mt-2 text-emerald-400 tracking-tightest">
                  {activeProject ? STAGES.filter(s => activeProject.steps?.[s.id]?.isComplete).length : 0} <span className="text-sm opacity-50 font-medium">/ 12 Done</span>
                </div>
             </div>
             <div className="bg-white/5 border border-white/10 rounded-[2rem] p-5 min-w-[160px]">
                <div className="label-caps text-slate-500 text-[9px]">Active Phase</div>
                <div className="text-2xl font-black mt-2 text-blue-400 tracking-tightest">
                  Phase {STAGES.findIndex(s => s.id === currentStepId) + 1}
                </div>
             </div>
          </div>
        </div>

        {/* Project Selector */}
        <div className="md:bg-white md:border md:border-slate-200 md:card-radius p-6 md:shadow-soft flex flex-col h-[20vh] md:h-auto md:max-h-[35vh] overflow-hidden">
          <div className="flex items-center justify-between mb-5 px-2">
            <h3 className="label-caps tracking-widest text-[9px]">My Projects</h3>
            <Button size="sm" variant="ghost" onClick={onOpenCreateModal} className="h-8 px-4 text-blue-600 font-black hover:bg-blue-50">
              <IconPlus className="w-3.5 h-3.5 mr-2" /> New
            </Button>
          </div>

          <div ref={listRef} onScroll={handleScroll} className="flex-1 overflow-y-auto pr-1 space-y-3 px-2">
            {totalCount === 0 ? (
              <div className="text-center py-10 text-slate-400 text-xs font-black uppercase opacity-40">No projects</div>
            ) : (
              <div style={{ paddingTop: `${startIndex * PROJECT_ROW_HEIGHT}px`, paddingBottom: `${(totalCount - endIndex) * PROJECT_ROW_HEIGHT}px` }}>
                {visibleProjects.map(p => {
                  const isActive = activeProject?.id === p.id;
                  const completedCount = STAGES.filter(s => p.steps?.[s.id]?.isComplete).length;
                  return (
                    <div key={p.id} style={{ height: `${PROJECT_ROW_HEIGHT}px` }} className="pb-3">
                      <div 
                        className={`p-5 h-full rounded-2xl transition-premium cursor-pointer border flex justify-between items-center active-scale ${isActive ? 'bg-slate-900 border-slate-900 text-white shadow-fab' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`} 
                        onClick={() => { switchProject(p.id); }}
                      >
                        <div className="min-w-0 pr-4">
                          <div className={`text-sm font-black truncate uppercase tracking-tight ${isActive ? 'text-white' : 'text-slate-900'}`}>{p.title}</div>
                          <div className={`text-[10px] font-black mt-1 uppercase tracking-widest ${isActive ? 'text-slate-400' : 'text-slate-400'}`}>{completedCount}/{STAGES.length} Milestones</div>
                        </div>
                        <div className="flex gap-2 shrink-0">
                          <button className={`p-2.5 rounded-xl transition-premium ${isActive ? 'bg-white/10 hover:bg-white/20' : 'text-slate-400 hover:bg-slate-200'}`} onClick={(e) => { e.stopPropagation(); duplicateProject(p.id); }}><IconCopy className="w-4 h-4" /></button>
                          <button className={`p-2.5 rounded-xl transition-premium ${isActive ? 'bg-white/10 hover:bg-red-400/30' : 'text-slate-400 hover:text-red-500 hover:bg-red-50'}`} onClick={(e) => { e.stopPropagation(); deleteProject(p.id); }}><IconTrash className="w-4 h-4" /></button>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Process Flow View */}
        <div className="flex-1 bg-white md:border md:border-slate-200 md:card-radius p-8 md:shadow-soft flex flex-col overflow-hidden mb-24 md:mb-0">
          <div className="flex justify-between items-center mb-8">
            <h3 className="label-caps tracking-widest text-[9px]">Project Roadmap</h3>
            <div className="flex bg-slate-100 p-1 rounded-xl">
               <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-premium ${viewMode === 'list' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}><IconFile className="w-4 h-4" /></button>
               <button onClick={() => setViewMode('map')} className={`p-2 rounded-lg transition-premium ${viewMode === 'map' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}><IconLayout className="w-4 h-4" /></button>
            </div>
          </div>

          <div className="overflow-y-auto flex-1 pr-3 pb-24">
            {activeProject ? (
              viewMode === 'list' ? (
                <div className="space-y-4">
                  {STAGES.map((stage, idx) => {
                    const isDone = activeProject.steps?.[stage.id]?.isComplete;
                    const isActive = currentStepId === stage.id;
                    return (
                      <button 
                        key={stage.id} 
                        onClick={() => { onStepSelect(stage.id); }} 
                        className={`w-full text-left rounded-[1.5rem] transition-premium border flex items-center gap-5 p-5 active-scale group ${isActive ? 'bg-blue-50 border-blue-200 shadow-md ring-8 ring-blue-50/50' : 'bg-white border-slate-100 hover:border-slate-300'}`}
                      >
                          <div className={`w-12 h-12 rounded-[1.25rem] flex items-center justify-center text-xs font-black border-2 shrink-0 transition-premium ${isActive ? 'bg-slate-900 border-slate-900 text-white shadow-fab' : isDone ? 'bg-emerald-500 border-emerald-500 text-white shadow-lg' : 'bg-slate-50 border-slate-200 text-slate-300'}`}>
                            {isDone && !isActive ? <IconCheck className="w-6 h-6" /> : (idx + 1)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className={`text-xs font-black uppercase tracking-widest ${isActive ? 'text-blue-900' : isDone ? 'text-emerald-900' : 'text-slate-600'}`}>{stage.label.split('. ')[1]}</div>
                          </div>
                          {isActive && <IconArrowRight className="w-5 h-5 text-blue-300 transition-premium group-hover:translate-x-1" />}
                      </button>
                    );
                  })}
                </div>
              ) : (
                <div className="grid grid-cols-3 gap-4">
                  {STAGES.map((stage, idx) => {
                    const isDone = activeProject.steps?.[stage.id]?.isComplete;
                    const isActive = currentStepId === stage.id;
                    return (
                      <button 
                        key={stage.id} 
                        onClick={() => { onStepSelect(stage.id); }} 
                        className={`aspect-square flex flex-col items-center justify-center rounded-[1.5rem] border transition-premium active-scale relative ${isActive ? 'bg-slate-900 border-slate-900 text-white shadow-fab scale-110 z-10' : isDone ? 'bg-emerald-50 text-emerald-100 border-emerald-200' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-slate-300'}`}
                      >
                        <span className="text-2xl mb-2">{stage.icon || '📦'}</span>
                        <span className={`text-[10px] font-black ${isActive ? 'text-white' : isDone ? 'text-emerald-600' : 'text-slate-400'}`}>{idx + 1}</span>
                        {isDone && !isActive && <div className="absolute top-2 right-2 w-2.5 h-2.5 bg-emerald-500 rounded-full border-2 border-white" />}
                      </button>
                    );
                  })}
                </div>
              )
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-200 gap-6 opacity-40 py-20">
                 <IconFile className="w-16 h-16" />
                 <span className="label-caps tracking-widest">Workspace Required</span>
              </div>
            )}
          </div>
        </div>
    </aside>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Project, AppState } from '../types';
import { STAGES } from '../constants';
import { Button } from './ui/Button';
import { IconPlus, IconCheck, IconTrash, IconCopy, IconChevronDown, IconSearch, IconArrowRight, IconClose, IconFile, IconLayout } from './ui/Icons';

interface SidebarProps {
  state: AppState;
  onOpenCreateModal: () => void;
  switchProject: (id: string) => void;
  deleteProject: (id: string) => void;
  duplicateProject: (id: string) => void;
  onExport: (project: Project) => void;
  activeProject: Project | null;
  onStepSelect: (stepId: string) => void;
  currentStepId: string;
  className?: string;
  mobileOpen?: boolean;
  onCloseMobile?: () => void;
}

const PROJECT_ROW_HEIGHT = 80;

export const Sidebar: React.FC<SidebarProps> = ({
  state,
  onOpenCreateModal,
  switchProject,
  deleteProject,
  duplicateProject,
  activeProject,
  onStepSelect,
  currentStepId,
  className = '',
  mobileOpen = false,
  onCloseMobile
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const listRef = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewportHeight, setViewportHeight] = useState(400);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setScrollTop(0);
    }, 200);
    return () => clearTimeout(handler);
  }, [searchTerm]);

  useEffect(() => {
    if (listRef.current) {
      setViewportHeight(listRef.current.clientHeight);
      const ro = new ResizeObserver(() => setViewportHeight(listRef.current?.clientHeight || 400));
      ro.observe(listRef.current);
      return () => ro.disconnect();
    }
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => setScrollTop(e.currentTarget.scrollTop);

  const filteredProjects = useMemo(() => {
    const all = Object.values(state.projects) as Project[];
    const sorted = all.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    if (!debouncedSearch.trim()) return sorted;
    const lower = debouncedSearch.toLowerCase();
    return sorted.filter(p => p.title.toLowerCase().includes(lower));
  }, [state.projects, debouncedSearch]);

  const totalCount = filteredProjects.length;
  const startIndex = Math.max(0, Math.floor(scrollTop / PROJECT_ROW_HEIGHT) - 1);
  const endIndex = Math.min(totalCount, Math.ceil((scrollTop + viewportHeight) / PROJECT_ROW_HEIGHT) + 1);
  const visibleProjects = filteredProjects.slice(startIndex, endIndex);

  return (
    <aside 
      className={`
        fixed inset-0 z-[100] bg-white flex flex-col transition-transform duration-500 ease-in-out md:relative md:translate-y-0 md:inset-auto md:z-0 md:bg-transparent md:w-80 lg:w-96 md:gap-8
        ${mobileOpen ? 'translate-y-0' : 'translate-y-full md:translate-y-0'}
        ${className}
      `}
      role="complementary"
    >
        {/* Mobile Sidebar Header */}
        <div className="md:hidden pt-safe shrink-0 bg-slate-900 text-white p-8 rounded-b-[3rem] shadow-fab">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h2 className="text-2xl font-black tracking-tightest">Design Flow</h2>
              <p className="label-caps text-slate-400 mt-1">Milestones & Mapping</p>
            </div>
            <button onClick={onCloseMobile} className="w-12 h-12 rounded-2xl bg-white/10 flex items-center justify-center active-scale transition-premium">
              <IconClose className="w-6 h-6 text-white" />
            </button>
          </div>

          <div className="flex gap-4 overflow-x-auto hide-scrollbar">
             <div className="bg-white/5 border border-white/10 rounded-2xl p-4 min-w-[140px]">
                <div className="label-caps text-slate-500 text-[8px]">Success Rate</div>
                <div className="text-xl font-black mt-1 text-emerald-400 tracking-tightest">
                  {activeProject ? STAGES.filter(s => activeProject.steps?.[s.id]?.isComplete).length : 0} <span className="text-xs opacity-50 font-medium">/ 12</span>
                </div>
             </div>
             <div className="bg-white/5 border border-white/10 rounded-2xl p-4 min-w-[140px]">
                <div className="label-caps text-slate-500 text-[8px]">Current Phase</div>
                <div className="text-xl font-black mt-1 text-blue-400 tracking-tightest">
                  {STAGES.findIndex(s => s.id === currentStepId) + 1} / 12
                </div>
             </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto hide-scrollbar md:flex md:flex-col md:gap-8 md:overflow-visible">
          {/* Project Selector */}
          <div className="md:bg-white md:border md:border-slate-200 md:card-radius p-6 md:shadow-soft flex flex-col min-h-[250px] md:h-auto md:max-h-[35vh]">
            <div className="flex items-center justify-between mb-5 px-2">
              <h3 className="label-caps tracking-widest text-[9px]">My Projects</h3>
              <Button size="sm" variant="ghost" onClick={onOpenCreateModal} className="h-8 px-4 text-blue-600 font-black hover:bg-blue-50">
                <IconPlus className="w-3.5 h-3.5 mr-2" /> New
              </Button>
            </div>

            <div ref={listRef} onScroll={handleScroll} className="flex-1 overflow-y-auto pr-1 space-y-3 px-2">
              {totalCount === 0 ? (
                <div className="text-center py-10 text-slate-400 text-xs font-black uppercase opacity-40">No projects</div>
              ) : (
                <div style={{ paddingTop: `${startIndex * PROJECT_ROW_HEIGHT}px`, paddingBottom: `${(totalCount - endIndex) * PROJECT_ROW_HEIGHT}px` }}>
                  {visibleProjects.map(p => {
                    const isActive = activeProject?.id === p.id;
                    const completedCount = STAGES.filter(s => p.steps?.[s.id]?.isComplete).length;
                    return (
                      <div key={p.id} style={{ height: `${PROJECT_ROW_HEIGHT}px` }} className="pb-3">
                        <div 
                          className={`p-4 h-full rounded-2xl transition-premium cursor-pointer border flex justify-between items-center active-scale ${isActive ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`} 
                          onClick={() => { switchProject(p.id); }}
                        >
                          <div className="min-w-0 pr-4">
                            <div className={`text-xs font-black truncate uppercase tracking-tight ${isActive ? 'text-white' : 'text-slate-900'}`}>{p.title}</div>
                            <div className={`text-[9px] font-black mt-0.5 uppercase tracking-widest ${isActive ? 'text-slate-400' : 'text-slate-400'}`}>{completedCount}/{STAGES.length} Done</div>
                          </div>
                          <div className="flex gap-1.5 shrink-0">
                            <button className={`p-2 rounded-xl transition-premium ${isActive ? 'bg-white/10 hover:bg-white/20' : 'text-slate-400 hover:bg-slate-200'}`} onClick={(e) => { e.stopPropagation(); duplicateProject(p.id); }}><IconCopy className="w-3.5 h-3.5" /></button>
                            <button className={`p-2 rounded-xl transition-premium ${isActive ? 'bg-white/10 hover:bg-red-400/30' : 'text-slate-400 hover:text-red-500 hover:bg-red-50'}`} onClick={(e) => { e.stopPropagation(); deleteProject(p.id); }}><IconTrash className="w-3.5 h-3.5" /></button>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          {/* Process Flow View */}
          <div className="bg-white md:border md:border-slate-200 md:card-radius p-8 md:shadow-soft flex flex-col mb-32 md:mb-0">
            <div className="flex justify-between items-center mb-8">
              <h3 className="label-caps tracking-widest text-[9px]">Project Roadmap</h3>
              <div className="flex bg-slate-100 p-1 rounded-xl">
                 <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-premium ${viewMode === 'list' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}><IconFile className="w-4 h-4" /></button>
                 <button onClick={() => setViewMode('map')} className={`p-2 rounded-lg transition-premium ${viewMode === 'map' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}><IconLayout className="w-4 h-4" /></button>
              </div>
            </div>

            <div className="space-y-4">
              {activeProject ? (
                viewMode === 'list' ? (
                  STAGES.map((stage, idx) => {
                    const isDone = activeProject.steps?.[stage.id]?.isComplete;
                    const isActive = currentStepId === stage.id;
                    return (
                      <button 
                        key={stage.id} 
                        onClick={() => { onStepSelect(stage.id); }} 
                        className={`w-full text-left rounded-2xl transition-premium border flex items-center gap-4 p-4 active-scale group ${isActive ? 'bg-blue-50 border-blue-200 shadow-sm ring-4 ring-blue-50/50' : 'bg-white border-slate-100 hover:border-slate-300'}`}
                      >
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-[10px] font-black border-2 shrink-0 transition-premium ${isActive ? 'bg-slate-900 border-slate-900 text-white shadow-md' : isDone ? 'bg-emerald-500 border-emerald-500 text-white shadow-sm' : 'bg-slate-50 border-slate-200 text-slate-300'}`}>
                            {isDone && !isActive ? <IconCheck className="w-5 h-5" /> : (idx + 1)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className={`text-[10px] font-black uppercase tracking-widest ${isActive ? 'text-blue-900' : isDone ? 'text-emerald-900' : 'text-slate-600'}`}>{stage.label.split('. ')[1]}</div>
                          </div>
                          {isActive && <IconArrowRight className="w-4 h-4 text-blue-300 transition-premium group-hover:translate-x-1" />}
                      </button>
                    );
                  })
                ) : (
                  <div className="grid grid-cols-3 gap-3">
                    {STAGES.map((stage, idx) => {
                      const isDone = activeProject.steps?.[stage.id]?.isComplete;
                      const isActive = currentStepId === stage.id;
                      return (
                        <button 
                          key={stage.id} 
                          onClick={() => { onStepSelect(stage.id); }} 
                          className={`aspect-square flex flex-col items-center justify-center rounded-2xl border transition-premium active-scale relative ${isActive ? 'bg-slate-900 border-slate-900 text-white shadow-md scale-110 z-10' : isDone ? 'bg-emerald-50 text-emerald-100 border-emerald-200' : 'bg-slate-50 border-slate-100 hover:bg-white hover:border-slate-300'}`}
                        >
                          <span className="text-xl mb-1.5">{stage.icon || '📦'}</span>
                          <span className={`text-[8px] font-black ${isActive ? 'text-white' : isDone ? 'text-emerald-600' : 'text-slate-400'}`}>{idx + 1}</span>
                          {isDone && !isActive && <div className="absolute top-2 right-2 w-2 h-2 bg-emerald-500 rounded-full border-2 border-white" />}
                        </button>
                      );
                    })}
                  </div>
                )
              ) : (
                <div className="text-center py-20 opacity-40">
                   <IconFile className="w-12 h-12 mx-auto mb-4 text-slate-300" />
                   <span className="label-caps">Select Project</span>
                </div>
              )}
            </div>
          </div>
        </div>
    </aside>
  );
};

import React, { useState, useEffect } from 'react';
import { Project, ExportConfig } from '../types';
import { generateFullHtml, downloadCaseStudy, exportToPrintable } from '../utils/exporter';
import { Button } from './ui/Button';
import { IconClose, IconDownload, IconFile, IconCheck, IconLayout, IconEye, IconEdit } from './ui/Icons';

interface ExportModalProps {
  project: Project | null;
  isOpen: boolean;
  onClose: () => void;
  onUpdateProject?: (id: string, updates: Partial<Project>) => void;
}

export const ExportModal: React.FC<ExportModalProps> = ({ project, isOpen, onClose, onUpdateProject }) => {
  const [format, setFormat] = useState<'html' | 'pdf'>('html');
  const [previewHtml, setPreviewHtml] = useState('');
  const [estimatedSize, setEstimatedSize] = useState<string>('Calculating...');
  const [mobileView, setMobileView] = useState<'settings' | 'preview'>('settings');

  const [isExporting, setIsExporting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');

  // Local config initialized from project or defaults
  const [config, setConfig] = useState<ExportConfig>(() => {
    return project?.exportConfig || {
      theme: 'modern',
      primaryColor: '#3B82F6',
      fontFamily: 'Inter',
      showCover: true,
      showTOC: true,
      showAssets: true,
      designerName: '',
      designerRole: 'UX Designer',
      excludedSteps: []
    };
  });

  useEffect(() => {
    if (project && isOpen) {
      const mergedProject = { ...project, exportConfig: config };
      const html = generateFullHtml(mergedProject, config.showAssets);
      setPreviewHtml(html);

      const sizeBytes = new Blob([html]).size;
      const kb = Math.round(sizeBytes / 1024);

      if (format === 'html') {
        setEstimatedSize(`~${kb} KB`);
      } else {
        const pdfEst = Math.round(kb * 1.5 + 500); 
        setEstimatedSize(`~${pdfEst} KB`);
      }
    }
  }, [project, isOpen, format, config]);

  const updateConfig = (updates: Partial<ExportConfig>) => {
    const next = { ...config, ...updates };
    setConfig(next);
    // If we have an update callback, persist it
    if (onUpdateProject && project) {
      onUpdateProject(project.id, { exportConfig: next });
    }
  };

  if (!isOpen || !project) return null;

  const handleExport = async () => {
    setIsExporting(true);
    setProgress(0);

    // Create a virtual project with the current config tweaks
    const finalProject = { ...project, exportConfig: config };

    try {
      if (format === 'html') {
        setStatusText('Preparing HTML...');
        setProgress(50);
        await new Promise(r => setTimeout(r, 500)); 
        downloadCaseStudy(finalProject, config.showAssets);
        setProgress(100);
        setStatusText('Download started!');
        setTimeout(() => {
           setIsExporting(false);
           onClose();
        }, 1000);
      } else {
        setStatusText('Inlining images & preparing document...');
        setProgress(30);
        await new Promise(r => setTimeout(r, 300));

        const result = await exportToPrintable(finalProject, config.showAssets);

        setProgress(100);
        if (result.method === 'print') {
          setStatusText('Print dialog opened!');
        } else {
          setStatusText('Popup blocked: HTML downloaded.');
        }

        setTimeout(() => {
           setIsExporting(false);
           onClose();
        }, 1500);
      }
    } catch (e) {
      console.error(e);
      setStatusText('Export failed.');
      setIsExporting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[80] flex items-end lg:items-center justify-center bg-slate-900/50 backdrop-blur-sm p-0 lg:p-4 animate-in fade-in duration-200">
      <div className="bg-white border border-slate-200 w-full lg:max-w-6xl h-[95vh] lg:h-[90vh] rounded-t-[2.5rem] lg:rounded-3xl shadow-2xl flex flex-col overflow-hidden">

        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-slate-100 bg-white shrink-0">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 lg:w-12 lg:h-12 rounded-xl lg:rounded-2xl bg-blue-600 flex items-center justify-center text-white shadow-lg">
                <IconDownload className="w-5 h-5 lg:w-6 lg:h-6" />
             </div>
             <div className="min-w-0">
               <h2 className="text-lg lg:text-xl font-black text-slate-900 leading-tight">Export Case Study</h2>
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5 truncate">Project: {project.title}</p>
             </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-900 p-2 rounded-full hover:bg-slate-100 transition-colors">
            <IconClose className="w-6 h-6" />
          </button>
        </div>

        {/* Tab Switcher for Mobile */}
        <div className="lg:hidden flex bg-slate-50 border-b border-slate-100 p-1.5 mx-6 my-2 rounded-2xl">
           <button onClick={() => setMobileView('settings')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-premium ${mobileView === 'settings' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}>Configuration</button>
           <button onClick={() => setMobileView('preview')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-premium ${mobileView === 'preview' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-400'}`}>Live Preview</button>
        </div>

        <div className="flex-1 flex flex-col lg:flex-row overflow-hidden">

          {/* Sidebar Controls */}
          <div className={`w-full lg:w-96 bg-slate-50 border-r border-slate-100 p-6 lg:p-8 flex flex-col overflow-y-auto gap-8 ${mobileView === 'preview' ? 'hidden lg:flex' : 'flex'}`}>

            {/* Format Selection */}
            <section>
              <h3 className="label-caps mb-4">Export Mode</h3>
              <div className="grid grid-cols-2 gap-3">
                <button 
                  onClick={() => setFormat('html')}
                  className={`flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${format === 'html' ? 'bg-blue-600 text-white border-blue-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
                >
                  <IconLayout className="w-5 h-5" />
                  <span className="text-[10px] font-black uppercase">Web View</span>
                </button>
                <button 
                  onClick={() => setFormat('pdf')}
                  className={`flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${format === 'pdf' ? 'bg-blue-600 text-white border-blue-600 shadow-lg' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
                >
                  <IconFile className="w-5 h-5" />
                  <span className="text-[10px] font-black uppercase">Print / PDF</span>
                </button>
              </div>
            </section>

            {/* Typography & Styling */}
            <section>
              <h3 className="label-caps mb-4">Aesthetics</h3>
              <div className="space-y-4">
                 <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Typography</label>
                    <select 
                      className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm font-bold text-slate-700 focus:ring-4 focus:ring-blue-500/10 outline-none"
                      value={config.fontFamily}
                      onChange={e => updateConfig({ fontFamily: e.target.value as any })}
                    >
                       <option value="Inter">Modern Sans (Inter)</option>
                       <option value="Serif">Classic Serif</option>
                       <option value="Mono">Clean Monospace</option>
                    </select>
                 </div>

                 <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Layout Theme</label>
                    <div className="grid grid-cols-3 gap-2">
                       {['modern', 'classic', 'minimal'].map(t => (
                         <button 
                           key={t}
                           onClick={() => updateConfig({ theme: t as any })}
                           className={`py-2 text-[10px] font-black uppercase rounded-xl border transition-all ${config.theme === t ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}`}
                         >
                           {t}
                         </button>
                       ))}
                    </div>
                 </div>
              </div>
            </section>

            {/* Document Structure */}
            <section>
              <h3 className="label-caps mb-4">Structure</h3>
              <div className="space-y-2">
                 {[
                   { id: 'showCover', label: 'Cover Page' },
                   { id: 'showTOC', label: 'T.O.C' },
                   { id: 'showAssets', label: 'Artifact Gallery' }
                 ].map(opt => (
                   <label key={opt.id} className="flex items-center justify-between p-4 bg-white border border-slate-200 rounded-2xl cursor-pointer transition-all hover:border-blue-400">
                      <span className="text-[11px] font-black uppercase tracking-tight text-slate-600">{opt.label}</span>
                      <div className={`w-9 h-5 rounded-full p-1 transition-colors ${config[opt.id as keyof ExportConfig] ? 'bg-blue-600' : 'bg-slate-200'}`}>
                         <div className={`bg-white w-3 h-3 rounded-full transition-transform ${config[opt.id as keyof ExportConfig] ? 'translate-x-4' : ''}`} />
                      </div>
                      <input 
                        type="checkbox" 
                        className="hidden" 
                        checked={config[opt.id as keyof ExportConfig] as boolean} 
                        onChange={e => updateConfig({ [opt.id]: e.target.checked })} 
                      />
                   </label>
                 ))}
              </div>
            </section>

            {/* Summary */}
            <div className="mt-auto pt-6 border-t border-slate-200 hidden lg:block">
               <div className="flex justify-between items-end bg-blue-50/50 p-4 rounded-2xl border border-blue-100">
                  <div>
                    <div className="text-[9px] font-black text-blue-400 uppercase tracking-widest mb-1">Estimated Size</div>
                    <div className="text-lg font-black text-blue-600 font-mono">{estimatedSize}</div>
                  </div>
                  <IconEye className="w-5 h-5 text-blue-300 mb-1" />
               </div>
            </div>
          </div>

          {/* Preview Area */}
          <div className={`flex-1 bg-slate-100 p-4 lg:p-10 flex flex-col items-center justify-center overflow-hidden relative ${mobileView === 'settings' ? 'hidden lg:flex' : 'flex'}`}>
            <div className="absolute top-4 lg:top-6 left-1/2 -translate-x-1/2 flex items-center gap-2 bg-slate-900 text-white text-[9px] font-black uppercase tracking-widest px-4 py-2 rounded-full z-10 shadow-xl">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
              Live Output Preview
            </div>

            <div className="w-full h-full max-w-4xl bg-white shadow-2xl rounded-2xl overflow-hidden relative border border-slate-200">
               <iframe 
                 srcDoc={previewHtml} 
                 title="Export Preview"
                 className="w-full h-full border-0 bg-white"
                 sandbox="allow-same-origin"
               />
            </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-6 border-t border-slate-100 bg-white flex flex-col lg:flex-row items-center justify-between gap-6 shrink-0 pb-safe">
          <div className="flex-1 max-w-md hidden lg:block">
            {isExporting ? (
              <div className="space-y-2">
                <div className="flex justify-between label-caps text-[9px]">
                   <span>{statusText}</span>
                   <span className="text-blue-600">{Math.round(progress)}%</span>
                </div>
                <div className="h-1 bg-slate-100 rounded-full overflow-hidden">
                  <div className="h-full bg-blue-600 transition-all duration-300 ease-out" style={{ width: `${progress}%` }}></div>
                </div>
              </div>
            ) : (
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider italic">
                Local Generation — No data leaves your device.
              </p>
            )}
          </div>
          <div className="flex gap-4 w-full lg:w-auto">
             <Button variant="ghost" onClick={onClose} disabled={isExporting} className="flex-1 lg:flex-none rounded-full">Cancel</Button>
             <Button onClick={handleExport} disabled={isExporting} className="flex-[2] lg:flex-none bg-slate-900 text-white rounded-full shadow-fab">
               {isExporting ? 'Processing...' : `Export ${format.toUpperCase()}`}
             </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Project, ProjectVersion, ExportConfig, Asset, CustomSection } from '../types';
import { STAGES, TEMPLATES } from '../constants';
